function initializePersonalNc(){state.personalNc={owner:'browser',servers:[],loaded:false,busy:false,error:'',notice:'',path:'',items:[],active:'',manage:false,openUrl:'',partial:false,generation:0,removeConfirm:false,addOpen:false,addDraft:{name:'',url:''},pins:[],search:null};}
function pncFavsMarkup(n){if(!n.pins.length)return '';return `<div class="pnc-favs"><span class="subtle">Favourites</span>${n.pins.map(p=>`<span class="pnc-fav"><button type="button" class="pnc-fav-go" data-pnc-pin="${esc(p.path)}">📌 ${esc(p.label)}</button><button type="button" class="pnc-fav-x" data-pnc-unpin="${esc(p.path)}" aria-label="Remove favourite ${esc(p.label)}">×</button></span>`).join('')}</div>`;}
function pncSearchMarkup(n){const parent=x=>'/'+x.path.split('/').slice(0,-1).join('/');return n.search.results.map((x,i)=>x.folder?`<button class="pnc-file" data-pnc-result="${i}"><span aria-hidden="true">▣</span><strong>${esc(x.name)}</strong><span class="subtle">${esc(parent(x))}</span></button>`:`<div class="pnc-file"><span aria-hidden="true">▤</span><strong>${esc(x.name)}</strong><span class="subtle">${esc(parent(x))} · ${x.size?Math.ceil(x.size/1024)+' KB':'File'}</span></div>`).join('')||'<p class="subtle">No matches on this server.</p>';}
document.addEventListener('submit',e=>{if(e.target.id!=='pnc-search')return;e.preventDefault();const n=state.personalNc;const q=e.target.elements.q.value.trim();if(q.length<2){n.notice='Search needs at least two characters.';render();return;}pncRun(async()=>{const d=await pncRequest('search?id='+encodeURIComponent(n.active)+'&q='+encodeURIComponent(q));n.search={q:d.query,results:d.results||[],truncated:!!d.truncated};n.notice='';});});
function personalNcWidget(){const n=state.personalNc;const s=n.servers.find(x=>x.id===n.active);return `<section class="section personal-nc" aria-label="My Nextcloud files"><div class="section-head"><div><div class="eyebrow">YOUR NEXTCLOUD</div><h3>My files</h3></div><button class="btn secondary" data-pnc="manage">${n.manage?'Close connection':'My connection'}</button></div><div class="pnc-private-actions"><button class="btn secondary" data-pnc="add-toggle" ${n.busy?'disabled':''}>${n.addOpen?'Close add server':'+ Add my server'}</button><span class="subtle">Your own servers stay private to this browser.</span></div>${n.addOpen?personalNcAddForm():''}${n.error?`<p class="notice" role="alert">${esc(n.error)} <button class="btn secondary" data-pnc="reload">Retry connection</button></p>`:''}${n.notice?`<p class="subtle" role="status">${esc(n.notice)}</p>`:''}${n.servers.length?`<div class="pnc-toolbar"><label>Nextcloud server<select id="pnc-server" ${n.busy?'disabled':''}>${n.servers.map(x=>`<option value="${esc(x.id)}" ${x.id===n.active?'selected':''}>${esc(x.name)}${x.personal?' · My server':''}</option>`).join('')}</select></label>${s?.username?`<button class="btn secondary" data-pnc="refresh" ${n.busy?'disabled':''}>Refresh</button>`:`<button class="btn" data-pnc="connect" ${n.busy?'disabled':''}>Login to Nextcloud</button>`}</div>`:'<p class="subtle">Add your own Nextcloud server above, or choose a server provided by an administrator.</p>'}${n.manage?`<div class="panel"><p class="subtle">Choose an available server and authorize your existing Nextcloud account. Your files and connection stay private to this browser.</p>${s?`<p class="subtle">${esc(s.url)}${s.username?' · Connected as '+esc(s.username):' · Not connected'}</p><span class="tag">${s.personal?'My private server':'Provided by admin'}</span>${s.username?`<button class="btn secondary" data-pnc="connect" ${n.busy?'disabled':''}>Reconnect account</button> <button class="btn secondary" data-pnc="remove" ${n.busy?'disabled':''}>Disconnect account</button>`:''}${s.personal?` <button class="btn secondary" data-pnc="remove-server" ${n.busy?'disabled':''}>Remove my server</button>${n.removeConfirm?`<div class="pnc-remove-confirm" role="group" aria-label="Confirm private server removal"><p>Remove this private server and its stored login from this browser?</p><button class="btn" data-pnc="confirm-remove-server">Remove server</button> <button class="btn secondary" data-pnc="cancel-remove-server">Cancel</button></div>`:''}`:''}`:''}<p class="subtle">Revoke Tavern’s app password in Nextcloud Security settings to invalidate access there. Administrator servers are shared choices. Servers you add are visible only in this browser.</p></div>`:''}${s?.username?`<div class="pnc-where">☁ Browsing <strong>${esc(s.name)}</strong> <span class="subtle">${esc(s.url.replace(/^https?:\/\//,''))}</span></div>${pncFavsMarkup(n)}<form id="pnc-search" class="pnc-search"><input name="q" maxlength="80" placeholder="Search ${esc(s.name)}…" value="${esc(n.search?.q||'')}" aria-label="Search this Nextcloud server"><button class="btn secondary" type="submit" ${n.busy?'disabled':''}>Search</button>${n.search?`<button class="btn secondary" type="button" data-pnc="clear-search">Clear search</button>`:''}</form><div class="pnc-toolbar"><strong>${esc(n.path?'/'+n.path:'All files')}</strong><button class="btn secondary" data-pnc="root" ${n.busy?'disabled':''}>Root</button><button class="btn secondary" data-pnc="up" ${n.busy||!n.path?'disabled':''}>Up</button>${n.pins.some(p=>p.path===n.path)?'<span class="tag">📌 Pinned</span>':`<button class="btn secondary" data-pnc="pin-current" ${n.busy?'disabled':''}>📌 Pin folder</button>`}${s.allow_custom?`<button class="btn secondary" data-pnc="save" ${n.busy?'disabled':''}>Use as starting folder</button>${s.folder_override?`<button class="btn secondary" data-pnc="default" ${n.busy?'disabled':''}>${s.personal?'Use original starting folder':'Use admin default'}</button>`:''}`:''}${n.openUrl?`<a class="btn secondary" href="${esc(n.openUrl)}" target="_blank" rel="noopener noreferrer">Open in Nextcloud ↗</a>`:''}</div>${n.busy?'<p role="status">Loading Nextcloud…</p>':`<div class="pnc-files">${n.search?pncSearchMarkup(n):n.items.map((x,i)=>x.folder?`<button class="pnc-file" data-pnc-folder="${i}"><span aria-hidden="true">▣</span><strong>${esc(x.name)}</strong><span aria-hidden="true">›</span></button>`:`<div class="pnc-file"><span aria-hidden="true">▤</span><strong>${esc(x.name)}</strong><span class="subtle">${x.size?Math.ceil(x.size/1024)+' KB':'File'}</span></div>`).join('')||'<p class="subtle">No files to display in this folder.</p>'}</div>${n.search?`<p class="subtle">Search on ${esc(s.name)} for “${esc(n.search.q)}”${n.search.truncated?' — first matches only; narrow the search to see more':''}.</p>`:''}`}${n.partial?'<p class="subtle">Showing the first 200 entries. Open Nextcloud to see the full folder.</p>':''}`:''}<p class="subtle">${s?.folder?'Starting folder: /'+esc(s.folder):s?'Starting folder: All files':''}</p></section>`;}
async function pncRequest(action,body){const generation=state.personalNc.generation;const r=await fetch('/api/plex/nextcloud/'+action,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(generation!==state.personalNc.generation)throw Error('Account changed. Please retry.');if(!r.ok)throw Error(d.error||'Nextcloud request failed');return d;}
async function pncBrowse(path){const n=state.personalNc,gen=n.generation,id=n.active;const d=await pncRequest('browse?id='+encodeURIComponent(id)+'&path='+encodeURIComponent(path));if(gen!==n.generation||id!==n.active)return;Object.assign(n,{path:d.path,items:d.items||[],openUrl:d.openUrl||'',partial:d.partial});pncRequest('pins?id='+encodeURIComponent(id)).then(p=>{if(gen===n.generation&&id===n.active)n.pins=p.pins||[];}).catch(()=>{});}
async function pncLoad(){const n=state.personalNc,gen=n.generation;n.loaded=true;n.search=null;const d=await pncRequest('servers');if(gen!==n.generation)return;n.servers=d.servers||[];n.loaded=true;if(!n.servers.some(x=>x.id===n.active))n.active=n.servers.find(x=>x.chosen)?.id||n.servers[0]?.id||'';const s=n.servers.find(x=>x.id===n.active);n.items=[];n.openUrl='';n.path=s?.folder||'';if(s?.username)await pncBrowse(n.path);if(!d.secretConfigured)n.notice='Administrator setup needed: configure NC_LAB_ENCRYPTION_KEY (32+ characters) before connecting.';}
async function pncRun(fn){const n=state.personalNc;if(n.busy)return;const owner=n.owner;n.busy=true;n.error='';n.notice='';render();try{await fn()}catch(e){if(owner===n.owner)n.error=e.message}finally{if(owner===n.owner){n.busy=false;render()}}}
document.addEventListener('change',e=>{if(e.target.id!=='pnc-server')return;const id=e.target.value;pncRun(async()=>{const n=state.personalNc;n.active=id;n.removeConfirm=false;n.generation++;await pncRequest('choose',{id});await pncLoad()})});
document.addEventListener('click',e=>{const btn=e.target.closest('[data-pnc],[data-pnc-folder],[data-pnc-pin],[data-pnc-unpin],[data-pnc-result]');if(!btn)return;const n=state.personalNc;if(n.busy&&btn.dataset.pnc!=='manage')return;if(btn.dataset.pnc==='add-toggle'){n.addOpen=!n.addOpen;render();return;}if(btn.dataset.pnc==='manage'){n.manage=!n.manage;n.removeConfirm=false;render();return;}const action=btn.dataset.pnc,id=n.active;if(action==='remove-server'){n.removeConfirm=true;render();return;}if(action==='cancel-remove-server'){n.removeConfirm=false;render();return;}if(action==='remove'&&!confirm('Disconnect your Nextcloud account from this browser?'))return;
 // Open synchronously so the browser does not block the authorization popup.
 const popup=action==='connect'?window.open('about:blank','tavern-nextcloud-login','width=650,height=780'):null;
 pncRun(async()=>{if(btn.dataset.pncFolder!==undefined){await pncBrowse(n.items[Number(btn.dataset.pncFolder)].path);return;}if(btn.dataset.pncPin!==undefined){n.search=null;await pncBrowse(btn.dataset.pncPin);return;}if(btn.dataset.pncUnpin!==undefined){await pncRequest('unpin',{id,path:btn.dataset.pncUnpin});n.pins=n.pins.filter(p=>p.path!==btn.dataset.pncUnpin);n.notice='Favourite removed.';return;}if(btn.dataset.pncResult!==undefined){const r=n.search?.results[Number(btn.dataset.pncResult)];if(r&&r.folder){n.search=null;await pncBrowse(r.path);}return;}if(action==='pin-current'){await pncRequest('pin',{id,path:n.path});const p=await pncRequest('pins?id='+encodeURIComponent(id));n.pins=p.pins||[];n.notice='Folder added to your favourites for this server.';}if(action==='clear-search'){n.search=null;}if(action==='reload')await pncLoad();if(action==='refresh')await pncBrowse(n.path);if(action==='root')await pncBrowse('');if(action==='up')await pncBrowse(n.path.split('/').slice(0,-1).join('/'));if(action==='default'){await pncRequest('folder-default',{id});await pncLoad();n.notice='Starting folder reset.';}if(action==='save'){await pncRequest('folder',{id,path:n.path});const s=n.servers.find(x=>x.id===id);if(s){s.folder=n.path;s.folder_override=1;}n.notice='Starting folder saved for this server.';}if(action==='confirm-remove-server'){n.removeConfirm=false;const d=await pncRequest('remove-server',{id});n.active='';await pncLoad();n.notice=d.notice;}if(action==='remove'){const d=await pncRequest('remove',{id});await pncLoad();n.notice=d.notice;}if(action==='connect'){if(!popup)throw Error('Allow popups for this site, then connect again.');const gen=n.generation;try{popup.opener=null;const d=await pncRequest('start',{id});popup.location=d.loginUrl;n.notice='Complete authorization in Nextcloud. Waiting for your approval…';render();for(let i=0;i<170;i++){await new Promise(done=>setTimeout(done,4000));if(gen!==n.generation)return;const p=await pncRequest('poll',{id});if(p.connected){popup.close();await pncLoad();n.notice='Nextcloud connected.';return;}if(popup.closed)throw Error('Login window closed. Connect again to continue.');}throw Error('Login timed out. Connect again.');}catch(e){try{popup.close()}catch{}throw e;}}});});
function pncSyncIdentity(){if(state.adminLoggedIn&&!state.ncAvailable.loaded)ncAdminLoad();}
window.addEventListener('DOMContentLoaded',()=>{new MutationObserver(pncSyncIdentity).observe(app,{childList:true});pncRun(pncLoad);pncSyncIdentity();});

