function uiIcon(name){const paths={Home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',Calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h.01M15 15h.01"/>','Shared Files':'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',Downloads:'<path d="M12 3v11m0 0 4-4m-4 4-4-4"/><path d="M4 17v1a3 3 0 0 0 3 3h10a3 3 0 0 0 3-3v-1"/>',Games:'<path d="M6.5 8h11a4.5 4.5 0 0 1 4.4 5.6l-.6 2.6a3 3 0 0 1-5 1.7L14.5 16h-5l-1.8 1.9a3 3 0 0 1-5-1.7L2.1 13.6A4.5 4.5 0 0 1 6.5 8Z"/><path d="M8 11v4M6 13h4"/><path d="M16.5 11.5h.01M18.5 14h.01"/>',Notifications:'<path d="M6 9a6 6 0 0 1 12 0c0 5 2 6 2 6H4s2-1 2-6"/><path d="M10 20a2.2 2.2 0 0 0 4 0"/>',Requests:'<path d="M4 5h16a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1Z"/><path d="m3 7 9 6 9-6"/>',Roadmap:'<path d="M5 21V4"/><path d="M5 4h12l-2.5 4L17 12H5"/>',Resources:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>','Discover Media':'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>','Tavern News':'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h8M8 11h8m-8 4h3m-3 3h8"/>','Movie Night':'<path d="m4 3 5 4-5 4m8-8 5 4-5 4M3 11h18v10H3z"/>',Settings:'<path d="m9 3-1 3-3 1v4l-2 1 2 1v4l3 1 1 3h6l1-3 3-1v-4l2-1-2-1V7l-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',More:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',Search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',Play:'<path d="m8 4 12 8-12 8z"/>'};return '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]||paths.Resources)+'</svg>';}
function mobileNavigation(){return '<nav class="mobile-nav '+(state.adminLoggedIn?'':'member-nav')+'" aria-label="Mobile navigation">'+['Home','Shared Files','Discover Media','Calendar'].filter(n=>n!=='Discover Media'||state.adminLoggedIn).map(n=>n==='Discover Media'?'<a href="/media-discovery">'+uiIcon(n)+'<span>Discover</span></a>':'<button data-page="'+n+'" class="'+(state.page===n?'active':'')+'" '+(state.page===n?'aria-current="page"':'')+'>'+uiIcon(n)+'<span>'+(n==='Shared Files'?'Files':n)+'</span></button>').join('')+'<button data-mobile-menu aria-controls="mobile-more" aria-expanded="'+!!state.mobileMenu+'">'+uiIcon('More')+'<span>More</span></button></nav><div id="mobile-more" class="mobile-more" '+(state.mobileMenu?'open':'')+'><div class="more-head"><strong>Your Tavern</strong><button class="btn secondary" data-mobile-close aria-label="Close menu">×</button></div>'+['Resources','Downloads','Games','Requests','Notifications','Tavern News','Movie Night','Roadmap','Settings'].map(n=>'<button class="nav" data-page="'+n+'">'+uiIcon(n)+esc(n)+'</button>').join('')+sidebarLinks()+'</div>';}
