function rouletteReady(){return state.roulette.server===state.plexSelectedMachine&&state.roulette.owner===plexPreferenceKey();}
function rouletteSvg(items){const colors=['#65518b','#235d65','#4e527d','#76593b','#455f78','#704e71','#346754','#665b80'],n=items.length,step=360/n;return `<svg viewBox="0 0 400 400" role="img" aria-label="Watch roulette wheel with ${n} candidates">${items.map((m,i)=>{const a=(i*step-90)*Math.PI/180,b=((i+1)*step-90)*Math.PI/180,mid=(i+.5)*step;const path=`M200 200 L${200+190*Math.cos(a)} ${200+190*Math.sin(a)} A190 190 0 ${step>180?1:0} 1 ${200+190*Math.cos(b)} ${200+190*Math.sin(b)} Z`;return `<g><path d="${path}" fill="${colors[i%colors.length]}" stroke="#0e1016" stroke-width="2"/><title>${esc(m.title)} · ${m.type==='show'?'TV series':'Movie'}</title><text transform="rotate(${mid} 200 200)" x="200" y="75" text-anchor="middle" fill="#fff" font-size="13" font-family="system-ui"><tspan x="200">${esc(m.title.length>18?m.title.slice(0,17)+'…':m.title)}</tspan><tspan x="200" dy="19">${m.type==='show'?'TV':'Movie'} · ${i+1}</tspan></text></g>`;}).join('')}<circle cx="200" cy="200" r="34" fill="#1a1d27" stroke="#c6b4ed" stroke-width="3"/><text x="200" y="206" text-anchor="middle" fill="#eee7ff" font-size="17">▶</text></svg>`;}
function rouletteWidget(){const r=state.roulette,ready=rouletteReady(),items=ready?r.items:[],busy=r.loading||r.spinning||r.searching;return `<section class="section roulette-section"><div class="section-head"><div><div class="eyebrow">LET YOUR LIBRARY DECIDE</div><h3>Watch Roulette</h3><p class="subtle">Random picks, your edits, one spin. Uses your selected Plex server.</p></div></div><div class="roulette-controls"><label>Include<select data-roulette-kind ${busy?'disabled':''}><option value="movie" ${r.kind==='movie'?'selected':''}>Movies</option><option value="show" ${r.kind==='show'?'selected':''}>TV shows</option><option value="both" ${r.kind==='both'?'selected':''}>Movies &amp; TV shows</option></select></label><button class="btn secondary" data-roulette-fill ${busy?'disabled':''}>${r.loading?'Loading library…':items.length?'Refill randomly':'Fill wheel randomly'}</button><button class="btn" data-roulette-spin ${busy||items.length<2?'disabled':''}>${r.spinning?'Spinning…':'Spin the wheel'}</button></div><p class="subtle" role="status">${esc(r.message||(!state.plexUser?'Sign in to Plex to build your wheel.':!ready&&r.items.length?'Server or account changed. Fill a new wheel for this library.':'Choose a mode and fill the wheel, then replace any candidates you like.'))}</p>${items.length?`<div class="roulette-grid"><div><div class="roulette-stage"><span class="roulette-pointer" aria-hidden="true">▼</span><div class="roulette-wheel ${r.spinning?'is-spinning':''}" style="--wheel-from:${r.from}deg;--wheel-to:${r.to}deg;--wheel-duration:${r.duration}ms;--wheel-delay:-${r.spinning?Math.min(r.duration,Math.max(0,performance.now()-r.started)):0}ms;transform:rotate(${r.spinning?r.to:r.rotation}deg)">${rouletteSvg(items)}</div></div>${r.winner?`<div class="panel roulette-winner" role="status"><div class="eyebrow">YOUR NEXT WATCH</div><h3>${esc(r.winner.title)}</h3><p class="subtle">${r.winner.type==='show'?'TV series':'Movie'}${r.winner.year?' · '+esc(r.winner.year):''}</p><p>${esc(r.winner.summary)}</p><a class="btn" href="${esc(r.winner.link)}" target="_blank" rel="noopener noreferrer">Open in Plex ↗</a> ${myListButton(r.winner)}</div>`:''}</div><div><h4>On the wheel</h4><p class="subtle">Replace any title by searching this Plex library. Candidates stay in this tab until refresh.</p><ol class="roulette-candidates">${items.map((m,i)=>`<li><div><strong>${esc(m.title)}</strong><span class="subtle">${m.type==='show'?'TV series':'Movie'}${m.year?' · '+esc(m.year):''}</span></div><button class="btn secondary" data-roulette-replace="${i}" ${busy?'disabled':''}>Replace</button></li>`).join('')}</ol>${r.edit>=0?`<div class="panel roulette-editor"><h4>Replace candidate ${r.edit+1}</h4><form id="roulette-search-form"><label>Search your library<input name="query" minlength="2" maxlength="100" required value="${esc(r.query)}" placeholder="Movie or series title" ${r.spinning?'disabled':''}></label><button class="btn secondary" ${r.searching||r.spinning?'disabled':''}>${r.searching?'Searching…':'Search library'}</button><button type="button" class="btn secondary" data-roulette-cancel ${r.spinning?'disabled':''}>Cancel</button></form><div class="roulette-search-results">${r.results.map((m,i)=>`<div><span><strong>${esc(m.title)}</strong><span class="subtle">${m.type==='show'?'TV series':'Movie'}${m.year?' · '+esc(m.year):''}</span></span><button class="btn secondary" data-roulette-use="${i}" ${r.spinning?'disabled':''}>Use this title</button></div>`).join('')}</div></div>`:''}</div></div>`:'<div class="empty">Your wheel will appear here. Fill it with up to eight titles from Plex.</div>'}</section>`;}
function rouletteRandomIndex(n){const data=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(data);}while(data[0]>=limit);return data[0]%n;}
function resetRoulette(){const old=state.roulette;state.roulette={...newRouletteState(old.kind),request:old.request+1};}
document.addEventListener('change',e=>{if(!e.target.matches('[data-roulette-kind]'))return;if(state.roulette.spinning)return;const kind=e.target.value;if(!['movie','show','both'].includes(kind))return;resetRoulette();state.roulette.kind=kind;render();});
document.addEventListener('input',e=>{if(e.target.closest('#roulette-search-form'))state.roulette.query=e.target.value;});
document.addEventListener('click',async e=>{
 const action=e.target.closest('[data-roulette-fill],[data-roulette-spin],[data-roulette-replace],[data-roulette-use],[data-roulette-cancel]');if(!action)return;const r=state.roulette;if(r.spinning)return;
 if(action.hasAttribute('data-roulette-fill')){
  if(r.loading)return;if(!state.plexUser){r.message='Sign in to Plex first.';render();return;}const server=state.plexSelectedMachine,owner=plexPreferenceKey();if(!server){r.message='Select a Plex server first.';render();return;}
  const request=++r.request;r.loading=true;r.message='Filling your wheel from Plex…';r.winner=null;render();
  try{const d=await plexFetch('roulette/candidates?server='+encodeURIComponent(server)+'&kind='+r.kind);if(state.roulette!==r||request!==r.request)return;if(server!==state.plexSelectedMachine||owner!==plexPreferenceKey()){r.message='Library changed. Fill the wheel again.';return;}r.items=d.items||[];r.server=server;r.owner=owner;r.edit=-1;r.results=[];r.rotation=0;r.message=(r.items.length<2?'At least two titles are needed to spin. ':'Wheel ready. Replace any candidates or spin. ')+(d.warning||'');}catch(error){r.message='Could not fill wheel: '+error.message;}finally{r.loading=false;render();}return;
 }
 if(action.hasAttribute('data-roulette-cancel')){r.edit=-1;r.results=[];r.request++;r.searching=false;render();return;}
 if(action.hasAttribute('data-roulette-replace')){r.edit=Number(action.dataset.rouletteReplace);r.query='';r.results=[];r.request++;r.searching=false;render();document.querySelector('#roulette-search-form input')?.focus();return;}
 if(action.hasAttribute('data-roulette-use')){if(!rouletteReady())return;const m=r.results[Number(action.dataset.rouletteUse)];if(!m||r.edit<0||r.edit>=r.items.length)return;if(r.items.some((x,i)=>i!==r.edit&&x.machine===m.machine&&x.ratingKey===m.ratingKey)){r.message='That title is already on the wheel. Choose a different one.';render();return;}r.items[r.edit]=m;r.winner=null;r.edit=-1;r.results=[];r.message='Candidate replaced. Your wheel is ready.';render();return;}
 if(!rouletteReady()||r.items.length<2||r.loading)return;
 const index=rouletteRandomIndex(r.items.length),step=360/r.items.length,target=(360-(index+.5)*step)%360,current=((r.rotation%360)+360)%360;
 r.from=r.rotation;r.to=r.rotation+6*360+((target-current+360)%360);r.duration=matchMedia('(prefers-reduced-motion: reduce)').matches?0:4800;r.started=performance.now();r.spinning=true;r.winner=null;r.message='Spinning…';const winner={...r.items[index]};render();
 setTimeout(()=>{if(state.roulette!==r)return;r.rotation=r.to;r.spinning=false;r.winner=winner;r.message='The wheel chose '+winner.title+'.';render();},r.duration);
});
document.addEventListener('submit',async e=>{if(e.target.id!=='roulette-search-form')return;e.preventDefault();const r=state.roulette;if(r.spinning||r.searching||!rouletteReady())return;r.query=e.target.elements.query.value.trim();const request=++r.request,server=r.server,owner=r.owner;r.searching=true;r.message='Searching your Plex library…';render();try{const d=await plexFetch('roulette/search?server='+encodeURIComponent(server)+'&kind='+r.kind+'&q='+encodeURIComponent(r.query));if(state.roulette!==r||request!==r.request||server!==state.plexSelectedMachine||owner!==plexPreferenceKey())return;r.results=d.items||[];r.message=(r.results.length?r.results.length+' library matches. Choose a replacement. ':'No matching titles. ')+(d.warning||'');}catch(error){if(state.roulette===r&&request===r.request)r.message='Search failed: '+error.message;}finally{if(state.roulette===r&&request===r.request){r.searching=false;render();}}});

function date(s){if(!s)return 'Unknown date';const d=new Date(s);return isNaN(d)?'Unknown date':d.toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});}
function bytes(n){if(!n)return '—';const u=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${u[i]}`}
function ncOpen(path,id,file){return '/api/nextcloud/open?path='+encodeURIComponent(path)+(id?'&id='+encodeURIComponent(id):'')+(file?'&file=1':'');}
function rows(items){if(!items.length)return '<div class="empty">No new top-level additions detected yet.</div>';return `<div class="files">${items.map(f=>`<div class="file-row"><div class="file-icon">${f.type==='Folder'?'▤':'▣'}</div><div><div class="file-name">${esc(f.name)}</div><div class="file-meta">${esc(f.type)} · ${bytes(f.size)} · ${f.baseline?'Existing at setup':'Added '+date(f.detectedAt)}</div></div><span class="tag">${f.baseline?'Existing':'New'}</span><span class="subtle">${f.type==='Folder'?`<button class="link" data-folder="${esc(f.name)}">Browse →</button>`:''}<a class="link" href="${esc(ncOpen(f.name,f.id,f.type!=='Folder'))}" target="_blank" rel="noopener noreferrer">Open in Nextcloud ↗</a></span></div>`).join('')}</div>`}
function effectivePins(){const games=state.items.find(f=>f.type==='Folder'&&f.name.toLowerCase()==='games');return games?[{id:games.id,name:games.name}]:[];}
function pinned(){const found=effectivePins().map(p=>({pin:p,file:state.items.find(f=>f.id===p.id&&f.type==='Folder')})).filter(x=>x.file);if(!found.length)return '';return `<div class="pin-head">📌 Pinned folders</div><div class="pinned-list">${found.map(({pin,file})=>`<button class="pinned-folder" data-folder="${esc(file.name)}"><span>▤</span><span>${esc(file.name)}</span><span>›</span></button><a class="link" href="${esc(ncOpen(file.name,file.id,false))}" target="_blank" rel="noopener noreferrer">Open in Nextcloud ↗</a>`).join('')}</div>`;}
function feed(){if(state.loading)return '<div class="panel">Loading your Nextcloud feed…</div>';if(state.error)return `<div class="panel"><strong>Connection issue</strong><p class="subtle">${esc(state.error)}</p><button class="btn secondary" data-refresh="1">Try again</button></div>`;const added=state.items.filter(f=>!f.baseline&&!effectivePins().some(p=>p.id===f.id));const ordinary=state.items.filter(f=>!effectivePins().some(p=>p.id===f.id));return `${pinned()}<div class="feed-status"><span class="dot" style="background:#67d5a1"></span> Nextcloud feed · ${added.length} new · ${state.items.length} total <button class="link" data-refresh="1">↻ Refresh</button></div>${rows(added.length?added:ordinary.slice(0,8))}${!added.length?'<p class="subtle">Showing existing top-level items until a new addition is detected.</p>':''}`;}
function folderView(){if(state.folderPath===null)return '';const segments=state.folderPath?state.folderPath.split('/'):[];const crumbs=['<button class="link" data-folder="">Shared</button>',...segments.map((s,i)=>`<span>›</span><button class="link" data-folder="${esc(segments.slice(0,i+1).join('/'))}">${esc(s)}</button>`)];return `<section class="section folder-panel"><div class="section-head"><h3>Browse Shared</h3><button class="btn secondary" data-close-folder="1">Close</button></div><div class="folder-crumbs">${crumbs.join('')}</div>${state.folderLoading?'<div class="panel">Loading folder…</div>':state.folderError?`<div class="panel">${esc(state.folderError)}</div>`:`<div class="files">${state.folderItems.map(f=>`<div class="file-row"><div class="file-icon">${f.folder?'▤':'▣'}</div><div><div class="file-name">${esc(f.name)}</div><div class="file-meta">${f.folder?'Folder':esc(f.type)} · ${bytes(f.size)}</div></div>${f.folder?`<button class="btn secondary" data-folder="${esc(f.path)}">Browse →</button>`:''}<a class="btn secondary" href="${esc(ncOpen(f.path,f.id,!f.folder))}" target="_blank" rel="noopener noreferrer">Open in Nextcloud ↗</a></div>`).join('')||'<div class="panel">This folder is empty.</div>'}</div>`}<p class="subtle">Open in Nextcloud uses Nextcloud’s own sign-in and file permissions.</p></section>`;}
function mediaCards(items,limit=10){if(!items.length)return '<div class="panel"><p class="subtle">Nothing available in this row.</p></div>';return '<div class="media-rail"><button type="button" class="rail-btn" data-rail-edge="start" aria-label="Jump to start of media row" title="Jump to start">&#x276E;</button><div class="media-grid" tabindex="0" aria-label="Scrollable media row">'+items.slice(0,limit).map(m=>{const pct=m.duration?Math.min(100,Math.round(m.viewOffset/m.duration*100)):0;const link='https://app.plex.tv/desktop/#!/server/'+encodeURIComponent(m.machine)+'/details?key='+encodeURIComponent(m.detailKey);const art=m.thumb?'/api/plex/art?server='+encodeURIComponent(m.machine)+'&path='+encodeURIComponent(m.thumb):'';return `<div class="media-card-wrap"><a class="media-card" href="${esc(link)}" target="_blank" rel="noopener noreferrer"><div class="art" style="--a:#2a3e67;--b:#503c75">${art?`<img loading="lazy" alt="" src="${esc(art)}" onerror="this.remove()">`:''}<span class="art-title">${esc(m.title)}</span></div><div class="media-name">${esc(m.title)}</div><div class="subtle">${esc(m.subtitle||m.year||m.type)}</div>${pct?`<div class="progress"><div style="width:${pct}%"></div></div>`:''}</a>${myListCardButton(m)}</div>`}).join('')+'</div><button type="button" class="rail-btn" data-rail-edge="end" aria-label="Jump to end of media row" title="Jump to end">&#x276F;</button></div>'}
function plexContent(){if(!state.plexUser)return `<section class="hero"><div class="hero-inner"><span class="pill">PERSONAL PLEX DASHBOARD</span><h2>Your media.<br>One home.</h2><p>Sign in with your own Plex account to load the servers and libraries shared with you.</p><button class="btn" data-plex-login="1">Sign in with Plex</button>${state.plexError?`<p class="notice">${esc(state.plexError)}</p>`:''}</div></section>`;if(state.plexLoading&& !state.plexServers.length)return '<div class="panel">Loading your Plex servers and media…</div>';return `<div class="plex-refresh-row"><span class="subtle">${state.plexLastFetched?'Plex checked '+date(state.plexLastFetched):'Plex not yet refreshed'}</span><button class="btn secondary" data-plex-refresh="1" ${state.plexLoading?'disabled':''}>${state.plexLoading?'Refreshing…':'↻ Refresh Plex'}</button></div>${state.plexError?`<div class="notice">${esc(state.plexError)}</div>`:''}${state.plexServers.length?'':`<div class="panel">No Plex servers were returned for this account.</div>`}${state.plexServers.length>1?`<div class="plex-server-controls"><label class="plex-server-picker">Plex server <select id="plex-server-select" aria-label="Choose Plex server">${state.plexServers.map(s=>`<option value="${esc(s.machine)}" ${s.machine===(state.plexSelectedMachine||state.plexServers[0].machine)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><button class="btn secondary plex-default-btn" type="button" data-plex-default="1" >${savedPlexServer()===(state.plexSelectedMachine||state.plexServers[0].machine)?'✓ My default':'Set as my default'}</button></div>`:''}${state.plexServers.filter(s=>s.machine===(state.plexSelectedMachine||state.plexServers[0]?.machine)).map(s=>`<section class="section plex-server-section"><div class="section-head"><div><div class="eyebrow">${esc(s.name)}</div><h3>Continue Watching</h3></div><span class="tag">${s.connected?'Connected':'Unreachable'}</span></div>${mediaCards(s.continueWatching)}<div class="section-head plex-recent-head"><h3>Recently Added</h3></div>${mediaCards(s.recentlyAdded,20)}</section>`).join('')}`}
const HOME_LAYOUT_DEFAULT=[{id:'personalNextcloud',width:'full',enabled:false},{id:'files',width:'half',enabled:true},{id:'events',width:'half',enabled:true},{id:'status',width:'half',enabled:true},{id:'announcements',width:'half',enabled:true},{id:'links',width:'half',enabled:true},{id:'featured',width:'full',enabled:true},{id:'movieFeatured',width:'full',enabled:true},{id:'surprise',width:'half',enabled:true},{id:'surpriseShow',width:'half',enabled:true},{id:'roulette',width:'full',enabled:true},{id:'staff',width:'full',enabled:true},{id:'news',width:'half',enabled:true},{id:'movieNight',width:'half',enabled:true},{id:'games',width:'full',enabled:true},{id:'gameWeek',width:'full',enabled:true},{id:'newGames',width:'full',enabled:true},{id:'favorites',width:'half',enabled:true},{id:'myList',width:'full',enabled:true},{id:'resources',width:'full',enabled:true},{id:'plex',width:'full',enabled:true}];
const HOME_NAMES={personalNextcloud:'Nextcloud browser (experimental)',files:'Nextcloud Files',events:'Upcoming Events',status:'Service Health',announcements:'Announcements',links:'Quick Links',plex:'Plex Media',featured:'Show of the Week',movieFeatured:'Movie of the Week',surprise:'Surprise Me · Movies',surpriseShow:'Surprise Me · TV Shows',roulette:'Watch Roulette',staff:'Staff Picks',news:'Latest Tavern News',movieNight:'Movie Night Voting',games:'Recently Added Games',gameWeek:'Game of the Week',newGames:'New Games',favorites:'Favorite Services',myList:'My List',resources:'Resources'};
function normalizedHomeLayout(input){const existing=Array.isArray(input)?input:[];const valid=existing.filter(x=>x&&HOME_NAMES[x.id]&&['half','full'].includes(x.width)&&typeof x.enabled==='boolean');const seen=new Set(valid.map(x=>x.id));return [...valid,...HOME_LAYOUT_DEFAULT.filter(x=>!seen.has(x.id))];}

// My Tavern is browser-local in this checkpoint. The admin's shared layout
// defines the allowed sections; personal choices cannot enable hidden sections.
const MY_TAVERN_KEY='mh_my_tavern_layout_v1';
function myTavernSaved(){try{const x=JSON.parse(localStorage.getItem(MY_TAVERN_KEY)||'null');if(!x||!Array.isArray(x.order)||!x.visibility||typeof x.visibility!=='object')return null;const extras=JSON.parse(localStorage.getItem('mh_my_tavern_extras_v1')||'{}');for(const id of ['surprise','staff','news','movieNight'])if(!(id in x.visibility)&&extras[id]===false)x.visibility[id]=false;return x;}catch{return null;}}
function myTavernBase(){return normalizedHomeLayout(state.homeLayout);}
function myTavernLayout(){const base=myTavernBase(),prefs=myTavernSaved();if(!prefs)return base;const allowed=base.filter(x=>x.enabled);const order=new Map(prefs.order.map((id,i)=>[id,i]));return allowed.map(x=>({...x,enabled:prefs.visibility[x.id]!==false})).sort((a,b)=>(order.get(a.id)??(prefs.order.length+base.findIndex(z=>z.id===a.id)))-(order.get(b.id)??(prefs.order.length+base.findIndex(z=>z.id===b.id))));}
function myTavernSettings(){const base=myTavernBase().filter(x=>x.enabled),prefs=myTavernSaved(),layout=myTavernLayout();return `<details class="settings-outer my-tavern"><summary>My Tavern · Personalize your dashboard</summary><div class="settings-group-body"><section class="section"><div class="section-head"><h3>My Tavern</h3></div><div class="panel"><p class="subtle">Customize the sections you see on Home. The administrator controls which sections are available. These preferences are saved only in this browser for now.</p><div class="layout-list">${layout.map((x,i)=>`<div class="layout-item"><strong>${esc(HOME_NAMES[x.id]||x.id)}</strong><label class="layout-visible"><input type="checkbox" data-my-tavern-visible="${esc(x.id)}" ${x.enabled?'checked':''}> Show</label><button class="btn secondary" data-my-tavern-move="${esc(x.id)}" data-delta="-1" ${i===0?'disabled':''} aria-label="Move up">↑</button><button class="btn secondary" data-my-tavern-move="${esc(x.id)}" data-delta="1" ${i===layout.length-1?'disabled':''} aria-label="Move down">↓</button></div>`).join('')||'<p class="subtle">No customizable sections enabled by the administrator.</p>'}</div><button class="btn secondary" type="button" data-my-tavern-reset="1">Restore my default layout</button>${prefs?'<p class="subtle">Personal layout saved on this device.</p>':''}</div>${myTavernExtrasSettings()}</section></div></details>`;}
function saveMyTavern(update){const base=myTavernBase().filter(x=>x.enabled);const current=myTavernLayout();const order=current.map(x=>x.id);const visibility=Object.fromEntries(current.map(x=>[x.id,x.enabled]));update({order,visibility});try{localStorage.setItem(MY_TAVERN_KEY,JSON.stringify({order,visibility}));}catch{alert('Your browser could not save My Tavern preferences.');}render();}
document.addEventListener('change',e=>{const el=e.target.closest('[data-my-tavern-visible]');if(!el)return;saveMyTavern(p=>{p.visibility[el.dataset.myTavernVisible]=el.checked;});});
document.addEventListener('click',e=>{const move=e.target.closest('[data-my-tavern-move]');if(move){saveMyTavern(p=>{const i=p.order.indexOf(move.dataset.myTavernMove),j=i+Number(move.dataset.delta);if(i>=0&&j>=0&&j<p.order.length)[p.order[i],p.order[j]]=[p.order[j],p.order[i]];});return;}if(e.target.closest('[data-my-tavern-reset]')){try{localStorage.removeItem(MY_TAVERN_KEY);}catch{}render();}});

function homeSection(id){switch(id){case 'files':return `<section class="section shared-feature"><div class="section-head"><div><div class="eyebrow">LIVE NEXTCLOUD FEED</div><h3>New on Shared Files</h3><p class="subtle">Direct children of /Shared only · ${state.lastSync?'Last checked '+date(state.lastSync):'Checking feed'}</p></div><button class="btn secondary" data-page="Shared Files">View shared files →</button></div>${feed()}</section>`;case 'personalNextcloud':return personalNcWidget();case 'events':return `<section class="section"><div class="section-head"><h3>Upcoming events</h3><button class="btn secondary" data-page="Calendar">Full calendar →</button></div>${calendarEntries(3)}</section>`;case 'status':return kumaHome();case 'announcements':return announcementHome();case 'plex':return plexContent();case 'resources':return resourcesPanel(true);case 'featured':return featuredWidget('show');case 'movieFeatured':return featuredWidget('movie');case 'surprise':return tavernEnabled('surprise')?surpriseWidget():'';case 'surpriseShow':return tavernEnabled('surpriseShow')?surpriseShowWidget():'';case 'roulette':return tavernEnabled('roulette')?rouletteWidget():'';case 'staff':return tavernEnabled('staff')?staffPicksWidget():'';case 'news':return tavernEnabled('news')?newsWidget():'';case 'movieNight':return tavernEnabled('movieNight')?movieNightWidget():'';case 'games':return tavernEnabled('games')?recentGamesWidget():'';case 'gameWeek':return gameWeekWidget();case 'newGames':return newGamesWidget();case 'myList':return myListWidget();case 'favorites':return favoriteServicesWidget();case 'links':return quickLinksWidget();default:return '';}}
// My List: per-member Plex bookmarks. The server stores them per Plex
// account (see /api/plex/my-list in worker.js); the client only sends the
// server machine + ratingKey, and the server captures verified metadata.
function myListHas(machine,ratingKey){return state.myList.items.some(x=>x.machine===machine&&x.ratingKey===String(ratingKey));}
async function loadMyList(){if(!state.plexUser){state.myList={items:[],loaded:false,error:''};return;}try{const r=await dashboardRequest('/api/plex/my-list');state.myList={items:r.items||[],loaded:true,error:''};}catch(e){state.myList={items:state.myList.items,loaded:true,error:e.message};}}
function myListButton(item){if(!state.plexUser||!item)return '';const rk=String(item.ratingKey||item.id||'');if(!item.machine||!rk)return '';const on=myListHas(item.machine,rk);return `<button type="button" class="btn ${on?'':'secondary'} mylist-btn" data-mylist-toggle data-machine="${esc(item.machine)}" data-rating-key="${esc(rk)}" aria-pressed="${on}">${on?'✓ In My List':'+ My List'}</button>`;}
function myListCardButton(m){if(!state.plexUser)return '';const rk=String(m.ratingKey||m.id||'');if(!m.machine||!rk)return '';const on=myListHas(m.machine,rk);return `<button type="button" class="mylist-card-btn${on?' on':''}" data-mylist-toggle data-machine="${esc(m.machine)}" data-rating-key="${esc(rk)}" aria-pressed="${on}" aria-label="${on?'Remove from':'Add to'} My List: ${esc(m.title)}" title="${on?'In My List — tap to remove':'Add to My List'}">${on?'✓':'+'}</button>`;}
function myListWidget(){
 if(!state.plexUser)return `<section class="section"><div class="section-head"><div><div class="eyebrow">YOUR BOOKMARKS</div><h3>My List</h3></div></div><div class="panel"><p class="subtle">Sign in with Plex to build your personal watchlist — saved titles live here, tied to your Plex account.</p></div></section>`;
 const items=state.myList.items;
 const cards=items.map(x=>({id:x.ratingKey,machine:x.machine,detailKey:x.detailKey||'/library/metadata/'+x.ratingKey,thumb:x.thumb,title:x.title,subtitle:x.subtitle||(x.type==='show'?'TV series':x.type==='episode'?'Episode':'Movie'),year:x.year,type:x.type}));
 return `<section class="section"><div class="section-head"><div><div class="eyebrow">YOUR BOOKMARKS</div><h3>My List</h3></div>${items.length?`<span class="tag">${items.length} saved</span>`:''}</div>${state.myList.error?`<p class="notice" role="alert">${esc(state.myList.error)}</p>`:''}${!state.myList.loaded?`<div class="panel"><p class="subtle">Loading your list…</p></div>`:items.length?mediaCards(cards,50):`<div class="panel"><p class="subtle">Nothing saved yet. Tap + on any poster — or + My List on a featured or surprise pick — to keep it here.</p></div>`}</section>`;
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-mylist-toggle]');if(!b)return;e.preventDefault();const machine=b.dataset.machine,ratingKey=b.dataset.ratingKey,on=myListHas(machine,ratingKey);b.disabled=true;try{const r=await dashboardRequest('/api/plex/my-list',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:on?'remove':'add',machine,ratingKey})});if(on)state.myList.items=state.myList.items.filter(x=>!(x.machine===machine&&x.ratingKey===ratingKey));else if(r.item)state.myList.items=[r.item,...state.myList.items.filter(x=>!(x.machine===machine&&x.ratingKey===ratingKey))];state.myList.error='';}catch(ex){state.myList.error=ex.message;}render();});

function featuredWidget(kind='show'){const f=featuredSlot(kind).featured;if(!f)return '';return `<section class="section featured-media"><div class="section-head"><div><div class="eyebrow">STAFF PICK</div><h3>${kind==='movie'?'Movie':'Show'} of the Week</h3></div></div><div class="featured-inner">${f.art?`<img class="featured-poster" src="${esc(f.art)}" alt="${esc(f.title)} poster" loading="lazy">`:''}<div><h3>${esc(f.title)}${f.year?' ('+esc(f.year)+')':''}</h3><p>${esc(f.note||f.summary||'Featured from our Plex library')}</p><a class="btn" target="_blank" rel="noopener noreferrer" href="${esc(f.plexUrl)}">View on Plex ↗</a> ${myListButton(f)}</div></div></section>`;}
function surpriseWidget(){const m=state.surpriseMovie;const art=m?.thumb?'/api/plex/art?server='+encodeURIComponent(m.machine)+'&path='+encodeURIComponent(m.thumb):'';return `<section class="section surprise-section"><div class="section-head"><div><div class="eyebrow">YOUR PLEX MOVIES</div><h3>Surprise Me Movie Picker</h3></div></div><div class="panel surprise-card">${!m?`<button type="button" class="surprise-start" data-surprise="1" ${state.surpriseLoading?'disabled':''}><span class="surprise-icon">⤨</span><strong>${state.surpriseLoading?'Finding a movie…':'Surprise Me'}</strong><small>Not sure what to watch? Shuffle your selected Plex server.</small></button>`:`<div class="surprise-result">${art?`<img class="surprise-art" src="${esc(art)}" alt="${esc(m.title)} poster" loading="lazy">`:''}<div><div class="eyebrow">TONIGHT'S WILD CARD</div><h3>${esc(m.title)}</h3><p class="subtle">${esc(m.year||'')} · ${esc(m.serverName||'Plex')}</p><p>${esc(m.summary||'Pick a movie and enjoy.')}</p><div class="surprise-actions"><a class="btn" href="${esc(m.link)}" target="_blank" rel="noopener noreferrer">Open in Plex ↗</a>${myListButton(m)}<button class="btn secondary" type="button" data-surprise="1" ${state.surpriseLoading?'disabled':''}>${state.surpriseLoading?'Shuffling…':'⤨ Shuffle again'}</button></div></div></div>`}${state.surpriseError?`<p class="notice" role="alert">${esc(state.surpriseError)}</p>`:''}</div></section>`;}
function surpriseShowWidget(){const m=state.surpriseShow;const art=m?.thumb?'/api/plex/art?server='+encodeURIComponent(m.machine)+'&path='+encodeURIComponent(m.thumb):'';return `<section class="section surprise-section"><div class="section-head"><div><div class="eyebrow">YOUR PLEX TV SHOWS</div><h3>Surprise Me TV Show Picker</h3></div></div><div class="panel surprise-card">${!m?`<button type="button" class="surprise-start" data-surprise-show="1" ${state.surpriseShowLoading?'disabled':''}><span class="surprise-icon">⤨</span><strong>${state.surpriseShowLoading?'Finding a TV show…':'Surprise Me'}</strong><small>Not sure what to watch? Shuffle TV shows on your selected Plex server.</small></button>`:`<div class="surprise-result">${art?`<img class="surprise-art" src="${esc(art)}" alt="${esc(m.title)} poster" loading="lazy">`:''}<div><div class="eyebrow">TONIGHT'S WILD CARD</div><h3>${esc(m.title)}</h3><p class="subtle">${esc(m.year||'')} · ${esc(m.serverName||'Plex')}</p><p>${esc(m.summary||'Pick a TV show and enjoy.')}</p><div class="surprise-actions"><a class="btn" href="${esc(m.link)}" target="_blank" rel="noopener noreferrer">Open in Plex ↗</a>${myListButton(m)}<button class="btn secondary" type="button" data-surprise-show="1" ${state.surpriseShowLoading?'disabled':''}>${state.surpriseShowLoading?'Shuffling…':'⤨ Shuffle again'}</button></div></div></div>`}${state.surpriseShowError?`<p class="notice" role="alert">${esc(state.surpriseShowError)}</p>`:''}</div></section>`;}
document.addEventListener('click',async e=>{if(!e.target.closest('[data-surprise]'))return;if(!state.plexUser){state.surpriseError='Sign in to Plex first.';render();return;}if(state.surpriseLoading)return;state.surpriseLoading=true;state.surpriseError='';render();try{const d=await plexFetch('random-movie?server='+encodeURIComponent(state.plexSelectedMachine||''));state.surpriseMovie=d.movie||null;}catch(ex){state.surpriseError=ex.message;}finally{state.surpriseLoading=false;render();}});
document.addEventListener('click',async e=>{if(!e.target.closest('[data-surprise-show]'))return;if(!state.plexUser){state.surpriseShowError='Sign in to Plex first.';render();return;}if(state.surpriseShowLoading)return;state.surpriseShowLoading=true;state.surpriseShowError='';render();try{const d=await plexFetch('random-show?server='+encodeURIComponent(state.plexSelectedMachine||''));if(!d.show)throw Error('No TV show was returned. Try again.');state.surpriseShow=d.show;}catch(ex){state.surpriseShowError=ex.message;}finally{state.surpriseShowLoading=false;render();}});

function recentlyAddedGamesWidget(){if(!tavernEnabled('games')||!myTavernExtraVisible('games'))return '';const games=state.recentGames;if(!games.length)return '';return `<section class="section"><div class="section-head"><h3>Recently Added Games</h3></div><div class="media-grid tavern-picks">${games.slice(0,8).map(g=>`<a class="media-card" href="${esc(g.nextcloudUrl||'#')}" target="_blank" rel="noopener noreferrer"><div class="art">${g.image?`<img loading="lazy" src="${esc(g.image)}" alt="">`:''}<span class="art-title">${esc(g.title||'Game')}</span></div><strong>${esc(g.title||'Game')}</strong></a>`).join('')}</div></section>`;}
async function loadRecentGames(){try{const d=await dashboardRequest('/api/games/recent');state.recentGames=Array.isArray(d.items)?d.items:[];state.recentGamesError='';}catch(e){state.recentGamesError=e.message;state.recentGames=[];}if(state.page==='Home')render();}
window.addEventListener('DOMContentLoaded',loadRecentGames);

function home(){const layout=state.layoutDraft?normalizedHomeLayout(state.layoutDraft):myTavernLayout();return `${presentationTop()}<div class="home-grid">${layout.filter(x=>x.enabled).map(x=>{const body=homeSection(x.id);return body?`<div class="home-slot ${x.width==='full'?'home-full':'home-half'}" data-home-widget="${esc(x.id)}">${body}<button class="widget-report-btn" type="button" data-broken-widget="${esc(x.id)}" title="Something's broken in this widget? Report it" aria-label="Report a problem with ${esc(HOME_NAMES[x.id]||x.id)}">⚠</button></div>`:''}).join('')}</div>`;}

function shared(){return `<a class="ftp-guide-card" href="/ftp-guide"><span class="ftp-guide-icon" aria-hidden="true">↓</span><span><strong>Download files with Cyberduck</strong><span>FTP connection guide · Illustrated setup, downloads & troubleshooting</span></span><span aria-hidden="true">→</span></a><div class="resource-shortcut"><button class="btn secondary" data-page="Resources">Browse shared resources →</button></div>${folderView()}<section class="section"><div class="section-head"><div><h3>Shared Files</h3><p class="subtle">Only the immediate contents of /Shared are monitored. Use Open in Nextcloud to view folders or files in Nextcloud (sign-in may be required).</p></div></div>${feed()}</section>`}
// Maintenance banner (v3.6.17): an announcement flagged as a banner shows
// site-wide, under the top bar on every page, until its expiry passes. The
// server already hides expired announcements; the client check here keeps a
// long-open tab honest as well.
function maintenanceBanner(){const b=state.announcements.find(a=>a.banner&&(!a.expiresAt||Date.parse(a.expiresAt)>Date.now()));if(!b)return '';return `<div class="maintenance-banner" role="alert"><span class="maintenance-icon" aria-hidden="true">⚠</span><div class="maintenance-text"><strong>${esc(b.title)}</strong><span>${esc(b.body)}</span></div>${b.expiresAt?`<span class="maintenance-until">Until ${esc(new Date(b.expiresAt).toLocaleString())}</span>`:''}</div>`;}
function announcementHome(){const list=state.announcements.filter(a=>!a.banner);if(!list.length)return '';return `<section class="section"><div class="section-head"><h3>Site communications — community announcements</h3></div>${list.slice(0,4).map(a=>`<div class="panel" style="margin-bottom:10px"><strong>${a.pinned?'📌 ':''}${esc(a.title)}</strong><p style="white-space:pre-wrap">${esc(a.body)}</p><p class="subtle">${date(a.createdAt)}</p></div>`).join('')}</section>`;}
async function loadAnnouncements(){try{const d=await dashboardRequest('/api/announcements');state.announcements=d.announcements||[];render();}catch(e){console.warn('Announcements unavailable:',e.message);}}
function announcementsAdmin(){return `<div class="section-head" style="margin-top:25px"><h3>Site communications — community announcements</h3></div><form id="announcement-form"><label>Title<input name="title" maxlength="120" required></label><label>Message<textarea name="body" maxlength="2000" rows="4" required></textarea></label><label><input name="pinned" type="checkbox" value="1"> Pin above other announcements</label><label><input name="banner" type="checkbox" value="1"> Show as a site-wide maintenance banner (every page, until it expires)</label><label>Expires (optional)<input name="expiresAt" type="datetime-local"></label><button class="btn" type="submit">Publish announcement</button></form>${state.announcements.map(a=>`<div class="calendar-entry"><span>${esc(a.title)}${a.banner?' — site-wide banner':''}${a.expiresAt?' · expires '+esc(new Date(a.expiresAt).toLocaleString()):''}</span><button class="btn secondary" data-announcement-delete="${esc(a.id)}">Delete</button></div>`).join('')}`;}
document.addEventListener('submit',async e=>{if(e.target.id!=='announcement-form')return;e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));d.pinned=!!f.elements.pinned.checked;d.banner=!!f.elements.banner.checked;try{await dashboardRequest('/api/announcements',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(d)});state.adminError='';f.reset();await loadAnnouncements();}catch(err){state.adminError=err.message;render();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-announcement-delete]');if(!b)return;if(!confirm('Delete this announcement?'))return;try{await dashboardRequest('/api/announcements',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'delete',id:b.dataset.announcementDelete})});await loadAnnouncements();}catch(err){state.adminError=err.message;render();}});
function metadataAdminPanel(){if(!state.adminLoggedIn)return '';const cfg=state.metadataSettings||{movie:'tmdb',tv:'tmdb',game:'steam',gameFallback:'none'};const status=state.metadataConfigured||{};const opt=(value,label,current)=>`<option value="${value}" ${current===value?'selected':''}>${label}</option>`;return `<details class="panel admin-panel settings-outer" open><summary>Metadata connections & game library</summary><div class="settings-group-body"><h3>Metadata providers</h3><p class="subtle">Set the default metadata source for each media type. Changes are saved by the Administration Save Changes button.</p><div class="setting"><label>Movies <select data-meta-setting="movie">${opt('tmdb','TMDB',cfg.movie)}${opt('plex','Plex library',cfg.movie)}</select></label></div><div class="setting"><label>TV <select data-meta-setting="tv">${opt('tmdb','TMDB',cfg.tv)}${opt('plex','Plex library',cfg.tv)}</select></label></div><div class="setting"><label>Games <select data-meta-setting="game">${opt('steam','Steam (default)',cfg.game)}${opt('rawg','RAWG',cfg.game)}${opt('igdb','IGDB',cfg.game)}</select></label></div><div class="setting"><label>Game fallback <select data-meta-setting="gameFallback">${opt('none','None',cfg.gameFallback)}${opt('rawg','RAWG',cfg.gameFallback)}${opt('igdb','IGDB',cfg.gameFallback)}</select></label></div><h3>Provider connections</h3><p class="subtle">Enter credentials below. They are encrypted before being saved in D1, and never returned to the browser. A one-time Cloudflare encryption secret is required. Status only confirms that credentials are stored, not that the provider accepted them.</p><div class="setting">Steam <span class="tag">Public storefront</span></div>${[['TMDB_API_KEY','TMDB','https://www.themoviedb.org/settings/api'],['RAWG_API_KEY','RAWG','https://rawg.io/apidocs'],['IGDB_CLIENT_ID','IGDB Client ID','https://dev.twitch.tv/console/apps'],['IGDB_ACCESS_TOKEN','IGDB Access Token','https://dev.twitch.tv/docs/authentication/getting-tokens-oauth/']].map(([key,label,url])=>`<div class="setting" style="display:block;margin:14px 0"><label for="meta-${key}"><strong>${label}</strong> <span class="tag">${key==='IGDB_CLIENT_ID'||key==='IGDB_ACCESS_TOKEN'?(status.igdb?'Configured':'Check credentials'):(status[key==='TMDB_API_KEY'?'tmdb':'rawg']?'Configured':'Not configured')}</span></label><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px"><input id="meta-${key}" type="password" autocomplete="new-password" placeholder="Paste ${label} here" style="flex:1;min-width:180px"><button type="button" class="btn" data-meta-save="${key}">Save key</button><button type="button" class="btn secondary" data-meta-remove="${key}">Remove</button></div><small><a href="${url}" target="_blank" rel="noopener noreferrer">Get credentials ↗</a> · Stored encrypted in D1, never displayed again</small></div>`).join('')}<p class="subtle">${state.metadataStorageReady?'Encrypted credential storage ready.':'One-time setup required: add METADATA_ENCRYPTION_KEY as a Cloudflare Worker secret (a long random value). See METADATA-KEY-SETUP.md.'}</p><h3>Recently Added Games</h3><p class="subtle">Search authorized Nextcloud folders, review cleaned game titles, choose Steam/RAWG/IGDB matches, and publish to the dashboard. Game widget visibility is controlled under Widget availability.</p><a class="btn secondary" href="/media-discovery">Open Game Importer &amp; Coming Soon ↗</a>${state.metadataMessage?`<p role="status" class="notice">${esc(state.metadataMessage)}</p>`:''}</div></details>`;}

document.addEventListener('click',async e=>{const button=e.target.closest('[data-meta-save],[data-meta-remove]');if(!button||!state.adminLoggedIn)return;const name=button.dataset.metaSave||button.dataset.metaRemove;const remove=!!button.dataset.metaRemove;const field=document.getElementById('meta-'+name);const value=remove?'':field?.value||'';if(!remove&&!value.trim()){state.metadataMessage='Enter a key before saving';render();return}if(remove&&!confirm('Remove saved '+name+' credential?'))return;button.disabled=true;try{await dashboardRequest('/api/admin/metadata/credentials',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,value,remove})});await loadMetadataAdmin();state.metadataMessage=remove?name+' removed.':name+' saved securely.';render()}catch(error){state.metadataMessage='Credential update failed: '+error.message;render()}finally{button.disabled=false}});
async function loadMetadataAdmin(){if(!state.adminLoggedIn)return;try{const d=await dashboardRequest('/api/metadata/settings');state.metadataSettings=d.providers;state.metadataConfigured=d.configured;state.metadataStorageReady=d.credentialStorageReady;state.metadataMessage='';render()}catch(e){state.metadataSettings={movie:'tmdb',tv:'tmdb',game:'steam',gameFallback:'none'};state.metadataMessage='Metadata settings unavailable: '+e.message;render()}}
document.addEventListener('change',e=>{const el=e.target.closest('[data-meta-setting]');if(!el||!state.adminLoggedIn)return;state.metadataSettings={...(state.metadataSettings||{}),[el.dataset.metaSetting]:el.value};state.metadataDirty=true;state.adminSaveMessage='Unsaved admin changes';render()});
function adminSaveToolbar(){return `<div class="panel admin-panel admin-save-toolbar"><div class="section-head"><h3>Save Administration changes</h3><button class="btn" type="button" data-admin-save-all="1">Save Changes</button></div><details class="admin-save-help"><summary>What does this save?</summary><p class="subtle">Saves all pending configuration edits across Administration: branding, entry question, welcome message, dashboard layout, widget availability, and metadata providers. Publishing new content, uploading files, and deleting items remain deliberate actions.</p></details>${state.adminSaveMessage?`<p role="status" class="notice">${esc(state.adminSaveMessage)}</p>`:''}</div>`;}
// Central Administration save: read editable forms BEFORE any render can replace them.
// Creation, publication, file uploads and deletion are intentionally not auto-triggered.
async function saveAdministrationChanges(){
 const errors=[],saved=[];
 const post=async(url,data)=>dashboardRequest(url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});
 const changed=(form)=>!!form&&[...form.elements].some(el=>el.name&&el.dataset.adminInitial!==undefined&&el.value!==el.dataset.adminInitial);
 const branding=document.getElementById('branding-form');
 const gate=document.getElementById('gate-settings-form');
 const welcome=document.getElementById('presentation-welcome');
 const brandingDraft=changed(branding)?Object.fromEntries(new FormData(branding)):null;
 const gateDraft=changed(gate)?Object.fromEntries(new FormData(gate)):null;
 const welcomeDraft=changed(welcome)?Object.fromEntries(new FormData(welcome)):null;
 const attempt=async(label,fn)=>{try{await fn();saved.push(label);}catch(e){errors.push(label+': '+e.message);}};
 if(brandingDraft)await attempt('Branding',async()=>{await post('/api/admin/branding',brandingDraft);state.branding={...state.branding,...brandingDraft};});
 if(gateDraft)await attempt('Community entry question',async()=>{const result=await post('/api/gate/admin',{question:gateDraft.question,answer:gateDraft.answer||'',keepExisting:true});if(result.answerChanged)state.adminSaveMessage='Community answer changed; existing sessions were reset.';});
 if(welcomeDraft)await attempt('Welcome message',async()=>{await post('/api/presentation',{action:'welcome',welcome:welcomeDraft.welcome||''});});
 if(state.layoutDraft)await attempt('Dashboard layout',async()=>{const r=await post('/api/admin/layout',{layout:normalizedHomeLayout(state.layoutDraft)});state.homeLayout=normalizedHomeLayout(r.layout);state.layoutDraft=null;});
 if(state.pendingWidgetSettings){
  const pending={...state.pendingWidgetSettings};
  await attempt('Widget availability',async()=>{for(const [id,enabled] of Object.entries(pending)){if(state.tavern.widgets[id]!==enabled){await post('/api/admin/tavern',{action:'widget',id,enabled});state.tavern.widgets[id]=enabled;}}state.pendingWidgetSettings=null;});
 }
 if(state.metadataDirty)await attempt('Metadata providers',async()=>{const meta=state.metadataSettings||{};const r=await post('/api/admin/metadata/settings',{movie:meta.movie,tv:meta.tv,game:meta.game,gameFallback:meta.gameFallback});state.metadataSettings=r.providers;state.metadataDirty=false;});
 if(errors.length){state.adminSaveMessage='Save incomplete. '+errors.join(' | ');}
 else state.adminSaveMessage=saved.length?'Saved: '+saved.join(', ')+'.':'No unsaved configuration changes.';
 if(saved.includes('Branding'))await loadDashboard();
 else if(saved.includes('Welcome message'))await loadPresentation();
 else render();
}
// Track the initial values of persistent admin form controls. No typing-triggered rerender.
function markAdminFormDefaults(){for(const id of ['branding-form','gate-settings-form','presentation-welcome']){const form=document.getElementById(id);if(!form)continue;for(const el of form.elements){if(el.name&&el.dataset.adminInitial===undefined)el.dataset.adminInitial=el.value;}}}
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-admin-save-all]');if(!btn||!state.adminLoggedIn)return;btn.disabled=true;state.adminSaveMessage='Saving…';try{await saveAdministrationChanges();}catch(err){state.adminSaveMessage='Save failed: '+err.message;render();}finally{btn.disabled=false;}});
// Register defaults after each Administration render, without changing other page behavior.
const adminFormObserver=new MutationObserver(()=>{if(state.page==='Settings'&&state.adminLoggedIn)markAdminFormDefaults();});
adminFormObserver.observe(document.documentElement,{childList:true,subtree:true});

// Admin diagnostics (v3.6.16): read-only integration health from
// /api/admin/diagnostics. Shows statuses and counts only — never credentials.
async function loadDiagnostics(){try{state.diag=await dashboardRequest('/api/admin/diagnostics');}catch(e){state.diag={app:{version:'unknown',buildAgent:'unknown'},checkedAt:new Date().toISOString(),checks:[{id:'api',label:'Diagnostics endpoint',status:'fail',detail:e.message}],recentReports:[]};}if(state.page==='Settings')render();}
function diagnosticsPanel(){
 if(!state.adminLoggedIn)return '';
 if(!state.diag&&!state.diagLoading){state.diagLoading=true;Promise.resolve().then(()=>loadDiagnostics()).finally(()=>{state.diagLoading=false;});}
 const d=state.diag;
 const pill={ok:'Connected',warn:'Attention',fail:'Failing',unconfigured:'Not set up'};
 const rows=d?d.checks.map(c=>`<div class="diag-row"><div><strong>${esc(c.label)}</strong><div class="subtle">${esc(c.detail)}</div></div><span class="tag diag-${esc(c.status)}">${esc(pill[c.status]||c.status)}</span></div>`).join(''):'';
 const reports=d?`<h4>Recent problem reports</h4>${d.recentReports.length?d.recentReports.map(r=>`<div class="diag-row"><div><strong>${esc(r.subject||'Report')}</strong><div class="subtle">${esc(r.category||'')} · ${esc(r.area||'')} · ${esc(new Date(r.createdAt).toLocaleString())}</div></div><span class="tag">${esc(r.status||'open')}</span></div>`).join(''):'<p class="subtle">No problem reports stored.</p>'}`:'';
 return `<details class="settings-outer diag-panel"><summary>Diagnostics · Integration health & support</summary><div class="settings-group-body"><section class="section"><div class="section-head"><h3>Diagnostics</h3><button class="btn secondary" type="button" data-diag-run="1">${d?'Re-run checks':'Run checks'}</button></div><div class="panel"><div class="diag-row"><div><strong>Running build</strong><div class="subtle">As reported by this page — if it disagrees with the server line below, a stale cached script is in play.</div></div><span class="tag">${esc(MEDIA_HUB_VERSION)} · Build: ${esc(MEDIA_HUB_BUILD_AGENT)}</span></div>${d?rows+`<p class="subtle">Server reports ${esc(d.app.version)} · Build: ${esc(d.app.buildAgent)} · Checked ${esc(new Date(d.checkedAt).toLocaleString())}. Statuses, counts and hostnames only — credentials are never shown.</p>`+reports:'<p class="subtle">Running the first checks…</p>'}</div></section></div></details>`;
}
document.addEventListener('click',e=>{if(e.target.closest('[data-diag-run]')){state.diagLoading=true;loadDiagnostics().finally(()=>{state.diagLoading=false;});}});

