function render(){if(!state.newsSkipCapture)newsCapture();state.newsSkipCapture=false;const openedSettings=state.page==='Settings'?[...document.querySelectorAll('.settings-group[open],.settings-outer[open]')].map(x=>x.querySelector('summary')?.textContent):[];if(state.page==='Status')state.page='Home';let body=state.page==='Home'?home():state.page==='Shared Files'?shared():state.page==='Calendar'?calendarPage():state.page==='Resources'?resourcesPanel(false):state.page==='Settings'?settings():state.page==='Tavern News'?newsPage():state.page==='Changelog'?changelogPage():state.page==='Movie Night'?movieNightPage():state.page==='Service History'?kumaHistory():state.page==='Report a Problem'?reportPage():state.page==='Downloads'?downloadsPage():state.page==='Games'?gamesPage():state.page==='Requests'?requestsPage():state.page==='Roadmap'?roadmapPage():state.page==='Notifications'?notificationsPage():state.page==='Ombi Lab'?ombiLabPage():`<div class="panel"><h3>${esc(state.page)}</h3><p class="subtle">Your personalized Plex media is on the Home page.</p></div>`;app.innerHTML=`${state.page==='Home'?presentationModal():''}<a class="skip-link" href="#main-content">Skip to content</a><div class="shell"><aside class="sidebar"><div class="brand"><div class="logo">${state.branding.customSvg?'<img class="custom-logo" src="/api/dashboard/logo.svg" alt="">':(state.branding.icon==='▶'?uiIcon('Play'):mhIconHtml(state.branding.icon))}</div><span class="brand-copy">${esc(state.branding.name)}<small>Your media, together</small></span></div><div class="section-label">YOUR SPACE</div>${nav.filter(([n])=>n!=='Settings'&&(n!=='Discover Media'||state.adminLoggedIn)).map(([n,i])=>n==='Discover Media'?`<a class="nav" href="/media-discovery"><span class="nav-icon">${uiIcon(n)}</span>${n}</a>`:`<button class="nav ${state.page===n?'active':''}" data-page="${n}" ${state.page===n?'aria-current="page"':''}><span class="nav-icon">${uiIcon(n)}</span>${n}</button>`).join('')}${sidebarLinks()}<div class="section-label">ACCOUNT</div><button class="nav ${state.page==='Settings'?'active':''}" data-page="Settings"><span class="nav-icon">${uiIcon('Settings')}</span>Settings</button><div class="sidebar-foot"><div class="version-label">${MEDIA_HUB_VERSION}</div><div class="server-status"><span class="dot ${state.error?'failed':state.lastSync?'connected':''}"></span>${state.error?'Feed unavailable':state.lastSync?'Nextcloud connected':'Checking Nextcloud'}</div></div></aside><main class="content" id="main-content" tabindex="-1"><div class="mobile-brand"><span class="logo">${uiIcon('Play')}</span>${esc(state.branding.name)}</div><header class="topbar"><div><div class="eyebrow">${esc(state.branding.tagline)}</div><h1 class="heading">${state.page==='Home'?'Welcome back':esc(state.page)}<span class="heading-dot">.</span></h1></div><div class="top-actions"><button class="btn secondary" data-search-open="1" aria-label="Search dashboard">${uiIcon('Search')} Search</button><button class="btn secondary notif-bell" data-page="Notifications" aria-label="Notifications">${uiIcon('Notifications')} Alerts${state.notif.unread?`<span class="notif-badge">${state.notif.unread>99?'99+':state.notif.unread}</span>`:''}</button><button class="btn secondary" data-kiosk-toggle="1">${state.kiosk?'Exit TV mode':'TV mode'}</button>${state.plexUser?`<span class="subtle">${esc(state.plexUser.name)}</span><button class="btn secondary" data-plex-logout="1">Sign out</button>`:`<button class="btn secondary" data-plex-login="1">Plex sign in</button>`}</div></header>${maintenanceBanner()}${state.searchOpen?searchUI():''}${body}<footer class="dashboard-footer"><span>${esc(state.branding.name)} · ${MEDIA_HUB_VERSION} · Build: ${esc(MEDIA_HUB_BUILD_AGENT)}</span><nav class="dashboard-footer-links" aria-label="Support and release information"><button type="button" data-page="Changelog">Change Log</button><button type="button" data-page="Report a Problem">Report a Problem</button><button type="button" data-page="Service History">Service History</button></nav></footer></main></div>${mobileNavigation()}`;if(state.page==='Settings'&&openedSettings.length){document.querySelectorAll('.settings-group,.settings-outer').forEach(x=>{if(openedSettings.includes(x.querySelector('summary')?.textContent))x.open=true;else x.open=false;});}}
async function refresh(){state.loading=true;state.error='';render();try{const r=await fetch(API+'/api/nextcloud/recent',{cache:'no-store'});let data=await r.json();if(!r.ok)throw Error(data.error||'HTTP '+r.status);state.items=Array.isArray(data.items)?data.items:[];state.mode=data.mode||'';state.lastSync=new Date().toISOString();}catch(e){state.error=e.message||'Could not load feed';}finally{state.loading=false;render()}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-page],[data-refresh],[data-plex-login],[data-plex-logout]');if(!el)return;if(el.dataset.page){state.page=el.dataset.page;if(state.page==='Shared Files' && state.folderPath===null){openFolder('');}else{render();}scrollTo(0,0)}else if(el.dataset.refresh)refresh();else if(el.dataset.plexLogin)startLogin();else if(el.dataset.plexLogout)logout()});
async function openFolder(path){state.folderPath=path;state.folderLoading=true;state.folderError='';state.page='Shared Files';render();try{const r=await fetch('/api/nextcloud/browse?path='+encodeURIComponent(path),{cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'Browse failed');state.folderItems=d.items||[];}catch(e){state.folderError=e.message;}finally{state.folderLoading=false;render();}}
document.addEventListener('click',e=>{const f=e.target.closest('[data-folder]');if(f){e.preventDefault();openFolder(f.dataset.folder);return;}if(e.target.closest('[data-close-folder]')){state.folderPath=null;render();return;}});
render();
refresh();

async function plexFetch(path,options={}){const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),45000);try{const r=await fetch(API+'/api/plex/'+path,{credentials:'include',cache:'no-store',...options,signal:ctl.signal});const d=await r.json();if(!r.ok)throw Error(d.error||'HTTP '+r.status);return d;}catch(e){if(e.name==='AbortError')throw Error('Plex took too long to answer — your server may be unreachable from the internet right now.');throw e;}finally{clearTimeout(timer);}}
// Browser-only Plex preferences. A stable identity is required for cross-user separation.
function plexPreferenceKey(){const u=state.plexUser||{};const id=u.id??u.uuid??u.username??u.email??u.name??u.title;return id==null?'':('screenden:plex-server:'+String(id));}
function plexStored(which){try{const key=plexPreferenceKey();return key?localStorage.getItem(key+':'+which)||'':'';}catch{return '';}}
function plexStore(which,machine){const key=plexPreferenceKey();if(!key||!machine)return false;try{localStorage.setItem(key+':'+which,machine);return localStorage.getItem(key+':'+which)===machine;}catch{return false;}}
function savedPlexServer(){return state.plexRemoteDefault||plexStored('default');}
function choosePlexServer(servers,current,initial){const available=new Set(servers.map(s=>String(s.machine)));const choices=initial?[savedPlexServer(),plexStored('last'),current]:[current,savedPlexServer(),plexStored('last')];return choices.find(id=>id&&available.has(String(id)))||servers[0]?.machine||'';}
async function loadPlex(){if(!state.plexUser)return;state.plexLoading=true;render();try{
 // Fetch the account-wide default before deciding which server to show.
 if(!state.plexPreferenceReady){
  try{const prefs=await plexFetch('preferences');state.plexRemoteDefault=prefs.defaultMachine||'';state.plexPreferenceError='';
   // Migrate an existing browser default only if this Plex account has none in D1.
   const local=plexStored('default');
   if(!state.plexRemoteDefault&&local){try{const saved=await plexFetch('preferences',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({defaultMachine:local})});state.plexRemoteDefault=saved.defaultMachine||'';}catch(e){state.plexPreferenceError=e.message;}}
  }catch(e){state.plexPreferenceError=e.message;}
  state.plexPreferenceReady=true;
 }
 const d=await plexFetch('home');const servers=d.servers||[];state.plexSelectedMachine=choosePlexServer(servers,state.plexSelectedMachine,!state.plexServers.length);state.plexServers=servers;state.plexLastFetched=new Date().toISOString();state.plexError='';}catch(e){state.plexError=e.message;}finally{state.plexLoading=false;render();}loadUpcoming();}
async function loadUpcoming(){if(!state.plexUser)return;state.upcomingStatus='Checking your Plex TV libraries…';render();try{const d=await plexFetch('upcoming');state.plexUpcoming=d.events||[];state.upcomingPartial=!!d.partial;state.upcomingStatus=d.total?'Checked '+d.scanned+' of '+d.total+' shows'+(d.pending?' · '+d.pending+' waiting for next refresh':'')+(d.failures?' · '+d.failures+' lookup errors':''):'No TV shows found in accessible Plex libraries.';}catch(e){state.upcomingStatus='Could not load TV release dates: '+e.message;}render();}
async function checkPlex(){try{const d=await plexFetch('me');state.plexSelectedMachine='';state.plexServers=[];state.plexRemoteDefault='';state.plexPreferenceReady=false;state.plexUser=d.user;render();await loadPlex();loadMyList();}catch{state.plexUser=null;state.myList={items:[],loaded:false,error:''};render();}}
async function startLogin(){try{state.plexError='';const d=await plexFetch('start',{method:'POST'});state.loginState=d.state;state.loginUrl=d.authUrl;const w=window.open(d.authUrl,'plex-login','width=620,height=760');if(!w){state.plexError='Popup blocked. Allow popups for this site and try again.';render();return;}state.plexError='Complete Plex sign-in in the popup. This page will update automatically.';render();for(let i=0;i<90;i++){await new Promise(r=>setTimeout(r,3000));const p=await plexFetch('poll',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:d.state})});if(p.loggedIn){state.plexSelectedMachine='';state.plexServers=[];state.plexRemoteDefault='';state.plexPreferenceReady=false;state.plexUser=p.user;state.plexError='';try{w.close()}catch{}render();await loadPlex();return;}}state.plexError='Sign-in timed out. Please try again.';render();}catch(e){state.plexError=e.message;render();}}
async function logout(){try{await plexFetch('logout',{method:'POST'});}catch{}state.plexUser=null;state.plexServers=[];state.plexSelectedMachine='';state.plexRemoteDefault='';state.plexPreferenceReady=false;state.plexUpcoming=[];state.upcomingStatus='Sign in to Plex to see library releases.';state.plexError='';render();}
checkPlex();

// v1.2: Native horizontal wheel/tilt events scroll the media rails.
// Vertical wheel events remain untouched so the page scrolls normally.

// v1.3: arrow-key navigation for horizontal Plex media rails.
// Hover chooses a rail; clicking its background or a card also makes it active.
let activeMediaRail = null;
document.addEventListener('pointerover', event => {
  const rail = event.target.closest?.('.media-grid');
  if (rail) activeMediaRail = rail;
});
document.addEventListener('pointerdown', event => {
  const rail = event.target.closest?.('.media-grid');
  if (rail) activeMediaRail = rail;
});
document.addEventListener('keydown', event => {
  if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
  if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  const target = event.target;
  if (target?.isContentEditable || target?.closest?.('input, textarea, select, [contenteditable="true"], [role="textbox"]')) return;
  const focusedRail = target?.closest?.('.media-grid');
  const hoveredRail = document.querySelector('.media-grid:hover');
  const rail = focusedRail || hoveredRail || (activeMediaRail?.isConnected ? activeMediaRail : null);
  if (!rail || rail.scrollWidth <= rail.clientWidth + 1) return;
  const direction = event.key === 'ArrowRight' ? 1 : -1;
  const next = Math.max(0, Math.min(rail.scrollWidth - rail.clientWidth, rail.scrollLeft + direction * 240));
  if (Math.abs(next - rail.scrollLeft) < 1) return;
  event.preventDefault();
  rail.scrollBy({ left: direction * 240, behavior: 'smooth' });
});

// v1.5: TV-friendly, keyboard-accessible jump-to-start/end controls.
document.addEventListener('click', event => {
  const button = event.target.closest?.('[data-rail-edge]');
  if (!button) return;
  const rail = button.closest('.media-rail')?.querySelector('.media-grid');
  if (!rail) return;
  activeMediaRail = rail;
  rail.scrollTo({left: button.dataset.railEdge === 'end' ? rail.scrollWidth - rail.clientWidth : 0, behavior: 'smooth'});
});


// Automatic releases are per signed-in Plex user. Manual events remain shared.
function allUpcoming(){const today=new Date().toISOString().slice(0,10);return [...state.events,...state.plexUpcoming].filter(e=>e.date>=today).sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title));}
function calendarEntries(limit=60){const upcoming=allUpcoming().slice(0,limit);return upcoming.length?upcoming.map(e=>`<div class="calendar-entry"><div class="calendar-date">${esc(new Date(e.date+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}))}</div><div><strong>${esc(e.title)}</strong><div class="subtle">${esc(e.source==='tvmaze'?'TV release · Not yet on Plex':e.category)}${e.notes?' · '+esc(e.notes):''}</div></div></div>`).join(''):'<p class="subtle">No scheduled events or matching upcoming episodes found.</p>';}

state.party={member:null,parties:[],events:[],polls:[],active:'all',mode:'',error:'',newCode:'',showEvent:false,showPoll:false};
async function partyFetch(path,body){const token=localStorage.getItem('mh_community_token')||'';return dashboardRequest(path,{...(body?{method:'POST',body:JSON.stringify(body)}:{}),headers:{'x-community-token':token,...(body?{'content-type':'application/json'}:{})}});}
async function loadParty(){try{const me=await partyFetch('/api/party/me');state.party.member=me.member;state.party.parties=me.parties||[];if(state.party.active!=='all'&&!state.party.parties.some(p=>p.id===state.party.active))state.party.active='all';const data=await partyFetch('/api/party/data');state.party.events=data.events||[];state.party.polls=data.polls||[];state.party.error='';}catch(e){state.party.error=e.message;}render();}
function partyHeader(){const p=state.party,active=p.parties.find(x=>x.id===p.active);return `<div class="party-bar"><div><strong>Party calendar</strong><p class="subtle">${p.member?'Signed in as '+esc(p.member.display_name):'Create a party identity to share events with friends.'}</p></div><div class="party-bar-actions"><select id="party-selector" aria-label="Choose party"><option value="all" ${p.active==='all'?'selected':''}>All my parties</option>${p.parties.map(x=>`<option value="${esc(x.id)}" ${x.id===p.active?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="btn secondary" data-party-mode="join">Join Party</button>${p.member?'<button class="btn secondary" data-party-mode="rename">Change name</button>':''}<button class="btn secondary" data-party-mode="create">+ Create Party</button></div></div>${p.error?`<p class="notice">${esc(p.error)}</p>`:''}${p.newCode?`<div class="panel"><strong>Save your invitation code now:</strong> <code>${esc(p.newCode)}</code><button class="btn secondary" data-party-copy>Copy</button><p class="subtle">This code is shown only when generated. Anyone with it can join the party.</p></div>`:''}${p.mode==='rename'&&p.member?`<form class="panel" id="party-rename"><h3>Change display name</h3><label>Display name<input name="name" minlength="2" maxlength="40" value="${esc(p.member.display_name)}" required></label><button class="btn">Save name</button><button type="button" class="btn secondary" data-party-mode="">Cancel</button></form>`:''}${p.mode==='identity'?`<form class="panel" id="party-identity"><h3>Choose a display name</h3><p class="subtle">This creates a browser-based party identity, separate from Plex.</p><label>Display name<input name="name" minlength="2" maxlength="40" required></label><button class="btn">Continue</button></form>`:p.mode==='create'?`<form class="panel" id="party-create"><h3>Create Party</h3><label>Party name<input name="name" minlength="2" maxlength="80" required></label><button class="btn">Create and get code</button><button type="button" class="btn secondary" data-party-mode="">Cancel</button></form>`:p.mode==='join'?`<form class="panel" id="party-join"><h3>Join Party</h3><label>Invitation code<input name="code" placeholder="PARTY-..." required></label><button class="btn">Join</button><button type="button" class="btn secondary" data-party-mode="">Cancel</button></form>`:''}${active?`<div class="party-manage"><span class="subtle">Viewing ${esc(active.name)}</span>${active.ownerId===p.member?.id?'<button class="btn secondary" data-party-rotate>Regenerate invite code</button>':'<button class="btn secondary" data-party-leave>Leave party</button>'}</div>`:''}`;}
function partyEventForm(){const p=state.party;if(!p.showEvent)return '';if(!p.member)return '<div class="panel"><p>Create or join a party first to schedule shared events.</p><button class="btn" data-party-mode="identity">Set up party identity</button></div>';if(!p.parties.length)return '<div class="panel">Create or join a party to add events.</div>';return `<form class="panel" id="party-event"><h3>Schedule party event</h3><label>Party<select name="partyId" required>${p.parties.map(x=>`<option value="${esc(x.id)}" ${x.id===p.active?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Title<input name="title" maxlength="120" required></label><label>Description<input name="description" maxlength="1000"></label><label>Start<input name="startsAt" type="datetime-local" value="${esc(calendarUI.selected)}T19:00" required></label><label>End (optional)<input name="endsAt" type="datetime-local"></label><button class="btn">Create event</button></form>`;}
function partyPolls(){const p=state.party,visible=p.polls.filter(x=>p.active==='all'||x.partyId===p.active);return `<div class="section-head"><h3>Party date polls</h3>${p.parties.length?'<button class="btn secondary" data-party-poll-toggle>+ Date poll</button>':''}</div>${p.showPoll?`<form id="party-poll" class="panel"><label>Party<select name="partyId">${p.parties.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label><label>Poll title<input name="title" maxlength="120" required></label><label>Possible dates (one per line, YYYY-MM-DDTHH:MM)<textarea name="dates" rows="3" required></textarea></label><p class="subtle">Agree on a timezone with your party; automatic timezone conversion is not implemented.</p><button class="btn">Create poll</button></form>`:''}${visible.map(x=>`<div class="panel"><div class="section-head"><strong>${esc(x.title)}</strong>${x.canDelete?`<button class="btn secondary" data-party-poll-delete="${esc(x.id)}">Delete</button>`:''}</div>${x.options.map(o=>`<div class="calendar-entry"><div><strong>${esc(o.startsAt.replace('T',' at '))}</strong><p class="subtle">${['Going','Maybe','Unavailable'].map(a=>a+': '+o.votes.filter(v=>v.response===a).length).join(' · ')}</p><div class="community-actions">${['Going','Maybe','Unavailable'].map(a=>`<button class="btn secondary" data-party-vote="${esc(o.id)}" data-response="${a}">${a}</button>`).join('')}</div></div></div>`).join('')}</div>`).join('')}`;}
document.addEventListener('change',e=>{if(e.target.id==='party-selector'){state.party.active=e.target.value;render();}});
document.addEventListener('click',async e=>{
 const p=state.party,mode=e.target.closest('[data-party-mode]');if(mode){const requested=mode.dataset.partyMode;p.afterIdentity=(!p.member&&['create','join'].includes(requested))?requested:'';p.mode=requested&&!p.member?'identity':requested;p.error='';render();return;}
 if(e.target.closest('[data-party-copy]')){try{await navigator.clipboard.writeText(p.newCode);}catch(e){p.error='Copy failed. Select the code manually.';render();}return;}
 if(e.target.closest('[data-party-poll-toggle]')){p.showPoll=!p.showPoll;render();return;}
 const rsvp=e.target.closest('[data-party-rsvp]'),vote=e.target.closest('[data-party-vote]'),del=e.target.closest('[data-party-event-delete]'),pollDel=e.target.closest('[data-party-poll-delete]'),rotate=e.target.closest('[data-party-rotate]'),leave=e.target.closest('[data-party-leave]');if(!rsvp&&!vote&&!del&&!pollDel&&!rotate&&!leave)return;
 if((del||pollDel||rotate||leave)&&!confirm('Confirm this party action?'))return;
 try{let path,body;if(rsvp){path='/api/party/event';body={action:'rsvp',eventId:rsvp.dataset.partyRsvp,response:rsvp.dataset.response};}else if(vote){path='/api/party/poll';body={action:'vote',optionId:vote.dataset.partyVote,response:vote.dataset.response};}else if(del){path='/api/party/event';body={action:'delete',id:del.dataset.partyEventDelete};}else if(pollDel){path='/api/party/poll';body={action:'delete',id:pollDel.dataset.partyPollDelete};}else if(rotate){path='/api/party/rotate';body={partyId:p.active};}else{path='/api/party/leave';body={partyId:p.active};}const result=await partyFetch(path,body);if(result.code)p.newCode=result.code;await loadParty();}catch(ex){p.error=ex.message;render();}
});
document.addEventListener('submit',async e=>{if(!['party-identity','party-create','party-join','party-event','party-poll','party-rename'].includes(e.target.id))return;e.preventDefault();const p=state.party,d=Object.fromEntries(new FormData(e.target));try{const type=e.target.id;const path={'party-rename':'profile','party-identity':'identity','party-create':'create','party-join':'join','party-event':'event','party-poll':'poll'}[type];const result=await partyFetch('/api/party/'+path,d);if(result.token)localStorage.setItem('mh_community_token',result.token);if(result.code)p.newCode=result.code;if(type==='party-create'&&result.id)p.active=result.id;p.mode=type==='party-identity'?(p.afterIdentity||''):'';if(type==='party-identity')p.afterIdentity='';p.showEvent=false;p.showPoll=false;await loadParty();}catch(ex){p.error=ex.message;render();}});

const calendarUI={month:new Date().getFullYear()*12+new Date().getMonth(),selected:new Date().toLocaleDateString('en-CA'),filters:{community:true,custom:true,plex:true}};
function calendarLocalDate(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
calendarUI.selected=calendarLocalDate(new Date());
function calendarData(){const out=[];for(const e of state.party.events||[]){const day=String(e.startsAt||'').slice(0,10);if(/^\d{4}-\d{2}-\d{2}$/.test(day))out.push({date:day,title:e.title,kind:'community',notes:e.description||'',partyId:e.partyId,time:String(e.startsAt).slice(11,16),id:e.id});}for(const e of state.events||[]){if(e.date)out.push({date:e.date,title:e.title,kind:'custom',notes:e.notes||''});}for(const e of state.plexUpcoming||[]){if(e.date)out.push({date:e.date,title:e.title,kind:'plex',notes:'TV release — not necessarily available on Plex'});}return out.filter(e=>calendarUI.filters[e.kind]&&(e.kind!=='community'||state.party.active==='all'||e.partyId===state.party.active)).sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title));}
function partyEventActions(e){const item=state.party.events.find(x=>x.id===e.id);if(!item)return '';return `<div class="community-actions">${['Going','Maybe','Unavailable'].map(s=>`<button class="btn secondary" data-party-rsvp="${esc(item.id)}" data-response="${s}">${s}</button>`).join('')}${item.canDelete?`<button class="btn secondary" data-party-event-delete="${esc(item.id)}">Delete</button>`:''}</div><p class="subtle">${item.rsvps.map(r=>esc(r.name)+': '+esc(r.response)).join(' · ')}</p>`;}
function calendarPage(){const y=Math.floor(calendarUI.month/12),mo=((calendarUI.month%12)+12)%12,first=new Date(y,mo,1),days=new Date(y,mo+1,0).getDate(),offset=first.getDay(),entries=calendarData(),byDay={};for(const e of entries)(byDay[e.date]??=[]).push(e);const cells=[];for(let i=0;i<Math.ceil((offset+days)/7)*7;i++){const n=i-offset+1;if(n<1||n>days){cells.push('<div class="month-cell outside" aria-hidden="true"></div>');continue;}const d=y+'-'+String(mo+1).padStart(2,'0')+'-'+String(n).padStart(2,'0'),items=byDay[d]||[];cells.push(`<button class="month-cell ${d===calendarUI.selected?'chosen':''} ${d===calendarLocalDate(new Date())?'today':''}" data-calendar-day="${d}" aria-label="${esc(d)}: ${items.length} events" aria-pressed="${d===calendarUI.selected}"><span class="month-number">${n}</span><span class="month-dots">${items.slice(0,4).map(e=>`<i class="month-dot ${e.kind}"></i>`).join('')}</span>${items.length?`<span class="month-count">${items.length} event${items.length===1?'':'s'}</span>`:''}</button>`);}const selected=entries.filter(e=>e.date===calendarUI.selected);return `<section class="section"><div class="section-head"><div><div class="eyebrow">COMMUNITY & RELEASES</div><h3>Calendar</h3><p class="subtle">Your party sessions and upcoming releases, all in one place.</p></div></div>${partyHeader()}<div class="calendar-toolbar"><button class="btn secondary" data-calendar-move="-1" aria-label="Previous month">❮</button><h3>${esc(first.toLocaleDateString(undefined,{month:'long',year:'numeric'}))}</h3><button class="btn secondary" data-calendar-move="1" aria-label="Next month">❯</button><button class="btn secondary" data-calendar-today="1">Today</button></div><div class="calendar-filters">${[['community','Community events'],['custom','Custom releases'],['plex','Plex TV releases']].map(([k,v])=>`<label><input type="checkbox" data-calendar-filter="${k}" ${calendarUI.filters[k]?'checked':''}> ${v}</label>`).join('')}</div><div class="month-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<span>${d}</span>`).join('')}</div><div class="month-grid">${cells.join('')}</div><div class="panel calendar-day-panel"><div class="section-head"><h3>${esc(new Date(calendarUI.selected+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}))}</h3><button class="btn secondary" data-calendar-create="1">+ Schedule event</button></div>${selected.length?selected.map(e=>`<div class="calendar-entry"><span class="calendar-kind ${e.kind}">${esc(e.kind==='plex'?'TV release':e.kind==='custom'?'Custom':'Community')}</span><div><strong>${esc(e.title)}</strong><div class="subtle">${esc([e.time,e.notes].filter(Boolean).join(' · '))}</div>${e.kind==='community'?partyEventActions(e):''}</div></div>`).join(''):'<p class="subtle">Nothing scheduled for this date.</p>'}<p class="subtle">Select a day and press + to schedule a party event. External release dates do not mean a title is on Plex.</p></div>${partyEventForm()}${partyPolls()}<div class="section-head"><h3>Upcoming entries</h3><button class="btn secondary" data-upcoming-refresh="1">Refresh Plex releases</button></div><p class="subtle">${esc(state.upcomingStatus)}</p><div class="calendar-list">${entries.filter(e=>e.date>=calendarLocalDate(new Date())).slice(0,30).map(e=>`<div class="calendar-entry"><div class="calendar-date">${esc(e.date)}</div><div><strong>${esc(e.title)}</strong><div class="subtle">${esc(e.kind==='community'?'Community':e.kind==='plex'?'TV release':'Custom release')}</div></div></div>`).join('')||'<p class="subtle">No upcoming entries in selected categories.</p>'}</div></section>`;}
document.addEventListener('click',e=>{const move=e.target.closest('[data-calendar-move]'),day=e.target.closest('[data-calendar-day]'),today=e.target.closest('[data-calendar-today]'),create=e.target.closest('[data-calendar-create]');if(move){calendarUI.month+=Number(move.dataset.calendarMove);render();}else if(day){calendarUI.selected=day.dataset.calendarDay;render();}else if(today){calendarUI.month=new Date().getFullYear()*12+new Date().getMonth();calendarUI.selected=calendarLocalDate(new Date());render();}else if(create){state.party.showEvent=!state.party.showEvent;render();}});
document.addEventListener('change',e=>{const k=e.target.dataset.calendarFilter;if(k){calendarUI.filters[k]=e.target.checked;render();}});
document.addEventListener('click',e=>{if(e.target.closest('[data-upcoming-refresh]'))loadUpcoming();});
