const MH_ICON_KEYS=Object.keys(MH_ICONS);
function mhIconHtml(icon){const d=MH_ICONS[icon];return d?`<svg viewBox="${d.vb}" class="brand-svg" aria-hidden="true">${d.body}</svg>`:esc(icon);}
function adminPanel(){if(!state.adminEnabled)return '<div class="panel">To enable administration, set the Cloudflare Worker secret <code>ADMIN_PASSWORD</code> and refresh.</div>';if(!state.adminLoggedIn)return `<div class="panel admin-panel"><p class="subtle">Admin password is stored only as a Cloudflare Worker secret.</p><form id="admin-login"><input name="password" type="password" autocomplete="current-password" placeholder="Admin password" required><button class="btn" type="submit">Unlock admin</button></form>${state.adminError?`<p class="notice">${esc(state.adminError)}</p>`:''}</div>`;return `<div class="panel admin-panel"><details class="settings-group" open><summary>Appearance & branding</summary><div class="settings-group-body"><div class="section-head"><h3>Dashboard branding</h3><button class="btn secondary" data-admin-logout="1">Lock</button></div><form id="branding-form"><label>Dashboard name<input name="name" maxlength="60" value="${esc(state.branding.name)}" required></label><label>Tagline<input name="tagline" maxlength="120" value="${esc(state.branding.tagline)}"></label><label>Accent color<input name="accent" type="color" value="${esc(state.branding.accent)}"></label><span class="subtle">Site icon</span><div class="icon-grid" role="radiogroup" aria-label="Site icon">${['▶','◆','◈','▣','☁','★','✦','⬢','●','■','▲','♥','♦','♠','♣','☾','☀','⚡','⌂','♪','❖','⚓','✿','♜'].map(i=>`<label class="icon-tile"><input type="radio" name="icon" value="${i}" ${state.branding.icon===i?'checked':''}><span>${i}</span></label>`).join('')}</div><span class="subtle">Icon library (drawn icons — look the same on every device)</span><input id="brand-icon-search" type="search" placeholder="Search icons…" aria-label="Search icons"><div class="icon-grid" role="radiogroup" aria-label="Icon library">${MH_ICON_KEYS.map(k=>`<label class="icon-tile" data-icon-tile="${k.slice(4)}" title="${k.slice(4)}"><input type="radio" name="icon" value="${k}" ${state.branding.icon===k?'checked':''}><span>${mhIconHtml(k)}</span></label>`).join('')}</div><p class="subtle">Classic symbols above still work. Drawn icons vendored from the local icon library (Tabler MIT, Simple Icons CC0, Font Awesome Free CC BY 4.0) — no downloads, they render identically everywhere.</p><span class="subtle">Theme</span><div class="theme-grid" role="radiogroup" aria-label="Theme">${[['tavern','Tavern','The classic look','#b19aff','#14171f'],['ember','Ember Hearth','Warm firelight, deep charcoal','#f59e0b','#1d130c'],['abyss','Midnight Abyss','Deep sea blues, cyan glow','#22d3ee','#0a1626'],['neon','Neon Arcade','Violet night, magenta buzz','#e879f9','#150a1f'],['forest','Elder Forest','Canopy greens, moss light','#4ade80','#0c1a10'],['royal','Royal Velvet','Plum velvet, gold trim','#fbbf24','#1c0f1e']].map(([id,name,desc,accent,bg])=>`<label class="theme-tile"><input type="radio" name="theme" value="${id}" ${(state.branding.theme||'tavern')===id?'checked':''}><span class="theme-swatches"><i style="background:${bg}"></i><i style="background:${accent}"></i></span><span class="theme-meta"><strong>${name}</strong><span class="subtle">${desc}</span></span></label>`).join('')}</div><p class="subtle">Picking a theme previews it instantly; it applies for everyone once you save branding. Your custom accent colour (above) still wins over a theme's accent — set it back to the default lavender to use the theme's.</p><button class="btn" type="submit">Save branding</button></form><div class="section-head" style="margin-top:25px"><h3>Custom SVG logo</h3></div><form id="svg-logo-form"><label>Upload SVG (max 45 KB)<input name="logo" type="file" accept=".svg,image/svg+xml" required></label><button class="btn" type="submit">Upload logo</button></form>${state.branding.customSvg?'<button class="btn secondary" data-logo-remove="1" style="margin-top:10px">Remove custom logo</button>':''}<p class="subtle">Simple vector SVGs only; scripts, styles, embedded images and external resources are blocked.</p></div></details><details class="settings-group"><summary>Custom calendar events</summary><div class="settings-group-body"><div class="section-head" style="margin-top:25px"><h3>${state.editingEventId?'Edit custom release / event':'Add custom release / event'}</h3></div><form id="event-form"><label>Title<input name="title" maxlength="120" value="${esc(state.events.find(x=>x.id===state.editingEventId)?.title||'')}" required></label><label>Date<input name="date" type="date" value="${esc(state.events.find(x=>x.id===state.editingEventId)?.date||'')}" required></label><label>Category<select name="category">${['Event','TV','Movie','Other'].map(c=>`<option ${state.events.find(x=>x.id===state.editingEventId)?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Notes (optional)<input name="notes" maxlength="500" value="${esc(state.events.find(x=>x.id===state.editingEventId)?.notes||'')}"></label><button class="btn" type="submit">${state.editingEventId?'Save changes':'Add custom release'}</button>${state.editingEventId?'<button type="button" class="btn secondary" data-event-cancel="1">Cancel editing</button>':''}</form><h3 style="margin-top:24px">Existing events</h3>${state.events.map(e=>`<div class="calendar-entry"><span>${esc(e.date)} · ${esc(e.title)}</span><button class="btn secondary" data-event-edit="${esc(e.id)}">Edit</button><button class="btn secondary" data-event-delete="${esc(e.id)}">Delete</button></div>`).join('')||'<p class="subtle">No events yet.</p>'}</div></details><details class="settings-group"><summary>Community access</summary><div class="settings-group-body">${gateSettingsAdmin()}</div></details><details class="settings-group"><summary>Messages, banners & countdowns</summary><div class="settings-group-body">${presentationAdmin()}${announcementsAdmin()}</div></details><details class="settings-group"><summary>Sidebar links</summary><div class="settings-group-body">${quickLinksAdmin()}</div></details>${state.adminError?`<p class="notice">${esc(state.adminError)}</p>`:''}</div>`;}
async function dashboardRequest(path,options={}){const r=await fetch(path,{credentials:'same-origin',cache:'no-store',...options});const raw=await r.text();let d;try{d=JSON.parse(raw)}catch{const type=r.headers.get('content-type')||'unknown';const html=/^\s*(?:<!doctype html|<html)/i.test(raw);throw Error('ScreenDen API '+path.split('?')[0]+' returned HTTP '+r.status+' ('+type+') with '+(html?'an HTML page':'non-JSON content')+'. '+(r.status===502||r.status===504?'Check the upstream service or proxy.':r.status===401||r.status===403?'Check your admin session and access gate.':'Check Worker routing and Cloudflare logs.'));}if(!r.ok||d?.ok===false)throw Error(d?.error||d?.message||'ScreenDen API '+path.split('?')[0]+' failed (HTTP '+r.status+')');return d;}

// Community membership and scheduling (separate from Plex).
const communityStore='mh_community_token';
async function communityFetch(path,options={}){const token=localStorage.getItem(communityStore)||'';return dashboardRequest(path,{...options,headers:{...(options.headers||{}),'x-community-token':token}});}
async function loadCommunity(){try{const [me,events,polls]=await Promise.all([communityFetch('/api/community/me'),communityFetch('/api/community/events'),communityFetch('/api/community/polls')]);state.community.polls=polls.polls||[];state.community.member=me.member;state.community.admin=me.admin;state.community.events=events.events||[];state.community.error='';}catch(e){state.community.error=e.message;}render();}
function communityPage(){const c=state.community;return `<section class="section"><div class="section-head"><div><div class="eyebrow">YOUR GROUP</div><h3>Community calendar</h3><p class="subtle">Schedule D&D sessions and get a clear view of who can attend. Separate from Plex release dates.</p></div><button class="btn secondary" data-community-refresh="1">Refresh</button></div>${c.error?`<p class="notice">${esc(c.error)}</p>`:''}${!c.member?`<div class="panel"><h3>Join the community</h3><p class="subtle">Ask an admin for a one-time invitation code. No Plex account required.</p><form id="community-join"><label>Display name<input name="name" maxlength="40" required></label><label>Invitation code<input name="code" placeholder="MH-..." required></label><button class="btn" type="submit">Join</button></form></div>`:`<p class="subtle">Signed in as ${esc(c.member.display_name)} · Your RSVP is saved for this browser.</p><div class="panel"><h3>Propose an event</h3><form id="community-member-event"><label>Title<input name="title" maxlength="120" required></label><label>Description<input name="description" maxlength="1000"></label><label>Start<input name="startsAt" type="datetime-local" required></label><label>End (optional)<input name="endsAt" type="datetime-local"></label><button class="btn" type="submit">Create event</button></form></div>`}<div class="calendar-list">${c.events.map(e=>{const counts=['Going','Maybe','Unavailable'].map(s=>s+': '+e.rsvps.filter(r=>r.response===s).length).join(' · ');return `<div class="panel community-event"><div class="section-head"><div><h3>${esc(e.title)}</h3><p class="subtle">${esc(e.startsAt.replace('T',' at '))}${e.endsAt?' – '+esc(e.endsAt.replace('T',' at ')):''}</p></div>${c.admin?`<button class="btn secondary" data-community-delete="${esc(e.id)}">Delete</button>`:''}</div><p>${esc(e.description)}</p><p class="subtle">${esc(counts)}</p><div class="community-rsvps">${e.rsvps.map(r=>`<span class="community-pill">${esc(r.name)}: ${esc(r.response)}</span>`).join('')}</div>${c.member?`<div class="community-actions">${['Going','Maybe','Unavailable'].map(s=>`<button class="btn secondary" data-community-rsvp="${esc(e.id)}" data-answer="${s}">${s}</button>`).join('')}</div>`:''}</div>`;}).join('')||'<div class="panel"><p class="subtle">No community events scheduled yet.</p></div>'}</div>${communityPolls()}</section>`;}
function communityAdmin(){if(!state.adminLoggedIn)return '';return `<div class="section-head" style="margin-top:25px"><h3>Community scheduling</h3></div><p class="subtle">Create an invitation code for each member. Codes are single-use.</p><button class="btn secondary" data-community-invite="1">Generate invitation</button>${state.community.invite?`<div class="panel"><strong>Copy this code now:</strong> <code>${esc(state.community.invite)}</code><button class="btn secondary" data-community-copy="1">Copy</button><p class="subtle">For security, this code is only displayed now.</p></div>`:''}<form id="community-event-form"><label>Event title<input name="title" maxlength="120" required></label><label>Description<input name="description" maxlength="1000"></label><label>Start date and time<input name="startsAt" type="datetime-local" required></label><label>End date and time (optional)<input name="endsAt" type="datetime-local"></label><button class="btn" type="submit">Add community event</button></form>`;}
document.addEventListener('click',async e=>{if(e.target.closest('[data-community-refresh]'))return loadParty();if(e.target.closest('[data-community-copy]')){try{await navigator.clipboard.writeText(state.community.invite);}catch{state.community.error='Could not copy code; select it manually.';render();}return;}const invite=e.target.closest('[data-community-invite]'),rsvp=e.target.closest('[data-community-rsvp]'),del=e.target.closest('[data-community-delete]');if(!invite&&!rsvp&&!del)return;try{if(invite){const d=await communityFetch('/api/community/admin/invite',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});state.community.invite=d.code;render();return;}if(del&&!confirm('Delete this community event and its RSVPs?'))return;await communityFetch(rsvp?'/api/community/rsvp':state.community.admin?'/api/community/admin/event':'/api/community/event',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(rsvp?{eventId:rsvp.dataset.communityRsvp,response:rsvp.dataset.answer}:{action:'delete',id:del.dataset.communityDelete})});await loadParty();}catch(err){state.community.error=err.message;render();}});
document.addEventListener('submit',async e=>{if(!['community-join','community-event-form','community-member-event'].includes(e.target.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const joining=e.target.id==='community-join';const d=await communityFetch(joining?'/api/community/join':e.target.id==='community-member-event'?'/api/community/event':'/api/community/admin/event',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});if(joining)localStorage.setItem(communityStore,d.token);await loadParty();}catch(err){state.community.error=err.message;render();}});

async function loadDashboard(){try{const [branding,events,status]=await Promise.all([dashboardRequest('/api/dashboard/config'),dashboardRequest('/api/dashboard/events'),dashboardRequest('/api/admin/status')]);state.branding=branding;state.events=events.events||[];state.adminLoggedIn=status.loggedIn;loadFeatured();loadMyList();loadCommunity351();state.adminEnabled=status.enabled;if(state.adminLoggedIn){try{state.gateConfig=await dashboardRequest('/api/gate/admin')}catch(e){console.warn('Gate settings unavailable:',e.message)}}if(branding.accent&&branding.accent.toLowerCase()!=='#b19aff')document.documentElement.style.setProperty('--brand-accent',branding.accent);else document.documentElement.style.removeProperty('--brand-accent');document.documentElement.dataset.theme=branding.theme||'tavern';document.title=branding.name+' — Dashboard';const favicon=document.querySelector('link[rel="icon"]');if(favicon)favicon.href='/favicon.svg?v='+Date.now();render();}catch(e){console.warn('Dashboard settings unavailable:',e.message);}}
document.addEventListener('submit',async e=>{if(e.target.id!=='svg-logo-form')return;e.preventDefault();const file=e.target.elements.logo.files?.[0];if(!file)return;if(file.size>45000){state.adminError='SVG exceeds 45 KB';render();return;}try{const svg=await file.text();await dashboardRequest('/api/admin/logo',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({svg})});state.adminError='';await loadDashboard();await loadPresentation();}catch(err){state.adminError=err.message;render();}});
document.addEventListener('click',async e=>{if(!e.target.closest('[data-logo-remove]'))return;try{await dashboardRequest('/api/admin/logo',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'remove'})});await loadDashboard();await loadPresentation();}catch(err){state.adminError=err.message;render();}});
document.addEventListener('submit',async e=>{if(!['admin-login','branding-form','event-form'].includes(e.target.id))return;e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));const endpoint=form.id==='admin-login'?'/api/admin/login':form.id==='branding-form'?'/api/admin/branding':'/api/admin/events';if(form.id==='event-form'){data.action=state.editingEventId?'update':'add';if(state.editingEventId)data.id=state.editingEventId;}try{await dashboardRequest(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});state.adminError='';if(form.id==='event-form')state.editingEventId=null;await loadDashboard();await loadPresentation();}catch(err){state.adminError=err.message;render();}});
document.addEventListener('click',async e=>{const edit=e.target.closest('[data-event-edit]'),cancel=e.target.closest('[data-event-cancel]');if(edit||cancel){state.editingEventId=edit?edit.dataset.eventEdit:null;render();if(edit)document.getElementById('event-form')?.scrollIntoView({block:'center'});return;}const lock=e.target.closest('[data-admin-logout]'),del=e.target.closest('[data-event-delete]');if(!lock&&!del)return;try{await dashboardRequest(lock?'/api/admin/logout':'/api/admin/events',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(del?{action:'delete',id:del.dataset.eventDelete}:{})});state.adminError='';await loadDashboard();await loadPresentation();}catch(err){state.adminError=err.message;render();}});
loadDashboard();

loadParty();

// Admin-configurable dashboard shortcuts, separate from service integrations.
async function loadQuickLinks(){try{const d=await dashboardRequest('/api/quick-links');state.quickLinks=d.links||[];state.quickLinkGroups=d.groups||[];}catch(e){console.warn('Quick links unavailable:',e.message)}render();}
function quickLinksHome(){return quickLinksWidget();}
function sidebarLinkEntries(){return [...state.quickLinks.map((link,i)=>({kind:'link',value:link,index:i})),...state.quickLinkGroups.map((group,i)=>({kind:'group',value:group,index:state.quickLinks.length+i}))].sort((a,b)=>(Number(a.value.position)||0)-(Number(b.value.position)||0)||a.index-b.index);}
function flatSidebarLinks(){return [...state.quickLinks,...state.quickLinkGroups.flatMap(g=>(g.links||[]).map(l=>({...l,description:[g.title,l.description].filter(Boolean).join(' · ')})))];}
function quickLinksMarkup(){return sidebarLinkEntries().map(entry=>{const l=entry.value;if(entry.kind==='link')return `<a class="nav sidebar-custom-link" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer" title="${esc(l.description||l.title)}"><span class="nav-icon" aria-hidden="true">↗</span><span>${esc(l.title)}</span></a>`;return `<details class="sidebar-link-group" data-sidebar-group="${esc(l.id)}" ${state.openLinkGroups[l.id]?'open':''}><summary class="nav"><span class="nav-icon" aria-hidden="true">${uiIcon('Resources')}</span><span class="sidebar-group-title">${esc(l.title)}</span><span class="sidebar-group-chevron" aria-hidden="true">⌄</span></summary><div class="sidebar-group-links">${(l.links||[]).map(child=>`<a class="nav sidebar-child-link" href="${esc(child.url)}" target="_blank" rel="noopener noreferrer" title="${esc(child.description||child.title)}"><span>${esc(child.title)}</span><span aria-hidden="true">↗</span></a>`).join('')}</div></details>`;}).join('');}
function sidebarLinks(){return state.quickLinks.length||state.quickLinkGroups.length?'<div class="section-label">LINKS</div>'+quickLinksMarkup():'';}
document.addEventListener('toggle',e=>{if(e.target.matches?.('[data-sidebar-group]'))state.openLinkGroups[e.target.dataset.sidebarGroup]=e.target.open;},true);
function emptyLinkGroup(){return {id:'',title:'',position:0,links:[{title:'',url:'',description:''}]};}
function linkGroupRow(link={}){return `<div class="link-group-row"><label>Link name<input data-group-field="title" maxlength="80" required value="${esc(link.title||'')}"></label><label>Link URL<input data-group-field="url" type="url" maxlength="1024" required placeholder="https://" value="${esc(link.url||'')}"></label><label class="group-row-wide">Description (optional)<input data-group-field="description" maxlength="200" value="${esc(link.description||'')}"></label><div class="group-row-wide link-group-row-actions"><button type="button" class="btn secondary" data-group-row-up aria-label="Move link up">↑</button><button type="button" class="btn secondary" data-group-row-down aria-label="Move link down">↓</button><button type="button" class="btn secondary" data-group-row-remove>Remove link</button></div></div>`;}
function quickLinkGroupsAdmin(){if(!state.adminLoggedIn)return '';const d=state.linkGroupDraft;return `<section class="link-groups-admin"><div class="section-head"><h3>${d.id?'Edit dropdown group':'Add dropdown group'}</h3></div><p class="subtle">Create a named dropdown with up to 20 links. Groups and single links share the sidebar sort order; links within a group follow the order below.</p><form id="link-group-form"><label>Group name<input name="title" maxlength="80" required value="${esc(d.title)}" placeholder="e.g. Media services"></label><label>Group sort order<input name="position" type="number" min="-10000" max="10000" value="${esc(d.position)}"></label><div class="group-link-rows">${d.links.map(linkGroupRow).join('')}</div><div class="link-group-row-actions"><button type="button" class="btn secondary" data-group-row-add>Add another link</button><button type="submit" class="btn" ${state.linkGroupSaving?'disabled':''}>${state.linkGroupSaving?'Saving…':d.id?'Save dropdown group':'Add dropdown group'}</button>${d.id?'<button type="button" class="btn secondary" data-link-group-cancel>Cancel group editing</button>':''}</div><p class="link-group-feedback subtle" role="status">${esc(state.linkGroupMessage)}</p></form><h4>Existing dropdown groups</h4>${state.quickLinkGroups.map(g=>`<div class="calendar-entry"><div><strong>${esc(g.title)}</strong><div class="subtle">${g.links.length} links · sort order ${esc(g.position)}</div></div><button class="btn secondary" type="button" data-link-group-edit="${esc(g.id)}">Edit group</button><button class="btn secondary" type="button" data-link-group-delete="${esc(g.id)}">Delete group</button></div>`).join('')||'<p class="subtle">No dropdown groups yet.</p>'}</section>`;}
function quickLinksAdmin(){return singleQuickLinksAdmin()+quickLinkGroupsAdmin();}
function readLinkGroupDraft(form){return {id:state.linkGroupDraft.id,title:form.elements.title.value,position:form.elements.position.value,links:[...form.querySelectorAll('.link-group-row')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-group-field]')].map(el=>[el.dataset.groupField,el.value])))};}
document.addEventListener('input',e=>{const form=e.target.closest('#link-group-form');if(form)state.linkGroupDraft=readLinkGroupDraft(form);});
document.addEventListener('click',async e=>{
 const form=e.target.closest('#link-group-form');
 const add=e.target.closest('[data-group-row-add]'),remove=e.target.closest('[data-group-row-remove]'),up=e.target.closest('[data-group-row-up]'),down=e.target.closest('[data-group-row-down]');
 if(form&&(add||remove||up||down)){
  if(state.linkGroupSaving)return;
  const rows=form.querySelector('.group-link-rows');
  if(add){if(rows.children.length>=20){state.linkGroupMessage='Maximum 20 links per dropdown.';form.querySelector('.link-group-feedback').textContent=state.linkGroupMessage;return;}rows.insertAdjacentHTML('beforeend',linkGroupRow());rows.lastElementChild.querySelector('input').focus();}
  else{const row=e.target.closest('.link-group-row');if(remove){if(rows.children.length>1)row.remove();else row.querySelectorAll('input').forEach(input=>{input.value='';});}else if(up&&row.previousElementSibling)rows.insertBefore(row,row.previousElementSibling);else if(down&&row.nextElementSibling)rows.insertBefore(row.nextElementSibling,row);}
  state.linkGroupDraft=readLinkGroupDraft(form);return;
 }
 const edit=e.target.closest('[data-link-group-edit]'),del=e.target.closest('[data-link-group-delete]'),cancel=e.target.closest('[data-link-group-cancel]');
 if(!edit&&!del&&!cancel)return;if(state.linkGroupSaving)return;
 if(edit){const g=state.quickLinkGroups.find(g=>g.id===edit.dataset.linkGroupEdit);if(!g)return;state.linkGroupDraft={id:g.id,title:g.title,position:g.position,links:g.links.map(l=>({...l}))};state.linkGroupMessage='';render();document.querySelector('#link-group-form [name=title]')?.focus();return;}
 if(cancel){state.linkGroupDraft=emptyLinkGroup();state.linkGroupMessage='';render();return;}
 const group=state.quickLinkGroups.find(g=>g.id===del.dataset.linkGroupDelete);if(!group||!confirm('Delete dropdown “'+group.title+'” and its '+group.links.length+' grouped links? Existing single links are kept.'))return;
 try{await dashboardRequest('/api/quick-links',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'group-delete',id:group.id})});if(state.linkGroupDraft.id===group.id)state.linkGroupDraft=emptyLinkGroup();delete state.openLinkGroups[group.id];state.linkGroupMessage='Dropdown group deleted.';await loadQuickLinks();}catch(error){state.linkGroupMessage=error.message;render();}
});
document.addEventListener('submit',async e=>{if(e.target.id!=='link-group-form')return;e.preventDefault();if(state.linkGroupSaving)return;state.linkGroupDraft=readLinkGroupDraft(e.target);state.linkGroupSaving=true;state.linkGroupMessage='Saving dropdown group…';render();try{await dashboardRequest('/api/quick-links',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'group-save',...state.linkGroupDraft})});state.linkGroupDraft=emptyLinkGroup();state.linkGroupMessage='Dropdown group saved.';await loadQuickLinks();}catch(error){state.linkGroupMessage='Could not save group: '+error.message;}finally{state.linkGroupSaving=false;render();}});

function singleQuickLinksAdmin(){if(!state.adminLoggedIn)return '';const editing=state.quickLinks.find(l=>l.id===state.editingLinkId);return `<div class="section-head" style="margin-top:25px"><h3>Add link to sidebar</h3></div><p class="subtle">Add, edit, or remove sidebar links. Links open in a new tab.</p><form id="quick-link-form"><label>Name<input name="title" maxlength="80" required value="${esc(editing?.title||'')}"></label><label>URL<input name="url" type="url" maxlength="1024" required placeholder="https://" value="${esc(editing?.url||'')}"></label><label>Description<input name="description" maxlength="200" value="${esc(editing?.description||'')}"></label><label>Sort order<input name="position" type="number" min="-10000" max="10000" value="${editing?.position??0}"></label><button class="btn" type="submit">${editing?'Save link':'Add link'}</button>${editing?'<button class="btn secondary" type="button" data-link-cancel="1">Cancel</button>':''}</form>${state.quickLinks.map(l=>`<div class="calendar-entry"><span>${esc(l.title)}</span><button class="btn secondary" data-link-edit="${esc(l.id)}">Edit</button><button class="btn secondary" data-link-delete="${esc(l.id)}">Delete</button></div>`).join('')}`;}
document.addEventListener('submit',async e=>{if(e.target.id!=='quick-link-form')return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(state.editingLinkId){d.action='update';d.id=state.editingLinkId;}try{await dashboardRequest('/api/quick-links',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(d)});state.editingLinkId=null;state.adminError='';await loadQuickLinks();}catch(err){state.adminError=err.message;render();}});
document.addEventListener('click',async e=>{const edit=e.target.closest('[data-link-edit]'),del=e.target.closest('[data-link-delete]'),cancel=e.target.closest('[data-link-cancel]');if(!edit&&!del&&!cancel)return;if(edit||cancel){state.editingLinkId=edit?edit.dataset.linkEdit:null;render();return;}if(!confirm('Delete this sidebar link?'))return;try{await dashboardRequest('/api/quick-links',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'delete',id:del.dataset.linkDelete})});await loadQuickLinks();}catch(err){state.adminError=err.message;render();}});
loadQuickLinks();


function communityPolls(){const c=state.community;return `<div class="section-head" style="margin-top:26px"><h3>Find a date</h3></div>${c.member||c.admin?`<div class="panel"><h3>Propose possible dates</h3><form id="poll-form"><label>Session or event title<input name="title" maxlength="120" required></label><label>Dates and times (one per line, format YYYY-MM-DDTHH:MM) — enter times in your group’s agreed timezone<textarea name="dates" rows="3" placeholder="2026-11-01T19:00&#10;2026-11-08T19:00" required></textarea></label><p class="subtle">Poll times are currently stored as entered, without timezone conversion. Confirm the timezone with your group.</p><button class="btn" type="submit">Create date poll</button></form></div>`:''}${(c.polls||[]).map(p=>`<div class="panel"><div class="section-head"><h3>${esc(p.title)}</h3>${p.canDelete?`<button class="btn secondary" data-poll-delete="${esc(p.id)}">Delete</button>`:''}</div>${p.options.map(o=>`<div class="calendar-entry" style="display:block"><strong>${esc(o.startsAt.replace('T',' at '))}</strong><p class="subtle">${['Going','Maybe','Unavailable'].map(x=>x+': '+o.votes.filter(v=>v.response===x).length).join(' · ')}</p><div class="community-rsvps">${o.votes.map(v=>`<span class="community-pill">${esc(v.name)}: ${esc(v.response)}</span>`).join('')}</div>${c.member?`<div class="community-actions">${['Going','Maybe','Unavailable'].map(x=>`<button class="btn secondary" data-poll-vote="${esc(o.id)}" data-poll-answer="${x}">${x}</button>`).join('')}</div>`:''}</div>`).join('')}</div>`).join('')||'<p class="subtle">No date polls yet.</p>'}`;}
document.addEventListener('submit',async e=>{if(e.target.id!=='poll-form')return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await communityFetch('/api/community/poll',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(d)});await loadParty();}catch(err){state.community.error=err.message;render();}});
document.addEventListener('click',async e=>{const vote=e.target.closest('[data-poll-vote]'),del=e.target.closest('[data-poll-delete]');if(!vote&&!del)return;if(del&&!confirm('Delete this date poll and all votes?'))return;try{await communityFetch('/api/community/poll',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(vote?{action:'vote',optionId:vote.dataset.pollVote,response:vote.dataset.pollAnswer}:{action:'delete',id:del.dataset.pollDelete})});await loadParty();}catch(err){state.community.error=err.message;render();}});

// Uptime Kuma public status page summary; no Kuma admin token required.
const VISIBLE_KUMA_MONITORS=['nextcloud','plex internal','plex tv'];
function visibleKumaServices(services){const all=Array.isArray(services)?services:[];return VISIBLE_KUMA_MONITORS.map(name=>all.find(s=>String(s.name||'').trim().toLowerCase()===name)).filter(Boolean);}
function statusLabel(status){return status===1?'Operational':status===0?'Offline':status===3?'Maintenance':'Unknown';}
function statusClass(status){return status===1?'up':status===0?'down':'unknown';}
function kumaHome(){const k=state.kuma;if(!k.configured)return '';const visible=visibleKumaServices(k.services);return `<section class="section"><div class="section-head"><h3>Service health</h3><button class="btn secondary" data-page="Status">Details →</button></div>${k.loading?'<div class="panel">Checking service health…</div>':k.error?'<div class="panel">Status data currently unavailable</div>':`<div class="home-status-list">${visible.map(x=>`<article class="status-card"><div class="status-card-head"><strong>${esc(x.name)}</strong><span class="status-indicator ${statusClass(x.status)}">● ${statusLabel(x.status)}</span></div><div class="status-metrics"><span>24h uptime<b>${x.uptime24==null?'—':esc(x.uptime24.toFixed(2))+'%'}</b></span><span>Response time<b>${x.ping==null?'—':esc(Math.round(x.ping))+' ms'}</b></span></div><div class="status-history" aria-label="Recent checks">${(x.history||[]).map(h=>`<span class="history-bar ${statusClass(h.status)}" title="${statusLabel(h.status)}"></span>`).join('')||'<span class="subtle">No recent history available</span>'}</div></article>`).join('')||'<div class="panel">No matching monitors</div>'}</div>`}</section>`;}

function statusPage(){const k=state.kuma;const items=visibleKumaServices(k.services);const groups=[...new Set(items.map(x=>x.group||'Services'))];return `<section class="section"><div class="section-head"><div><h3>Service Status</h3><p class="subtle">Live public monitor data from Uptime Kuma. This page does not run its own checks.</p></div><button class="btn secondary" data-kuma-refresh="1">↻ Refresh</button></div>${!k.configured?'<div class="panel">Set the KUMA_STATUS_URL Worker variable to enable service monitoring.</div>':k.loading?'<div class="panel">Loading service monitors…</div>':k.error?`<div class="panel">${esc(k.error)}. Check that your Kuma status page is public and reachable.</div>`:!items.length?'<div class="panel">No monitors are published on this status page.</div>':groups.map(g=>`<div class="status-group"><h3>${esc(g)}</h3><div class="status-grid">${items.filter(x=>(x.group||'Services')===g).map(x=>`<article class="status-card"><div class="status-card-head"><strong>${esc(x.name)}</strong><span class="status-indicator ${statusClass(x.status)}">● ${statusLabel(x.status)}</span></div><div class="status-metrics"><span>24h uptime<b>${x.uptime24==null?'—':esc(x.uptime24.toFixed(2))+'%'}</b></span><span>Response time<b>${x.ping==null?'—':esc(Math.round(x.ping))+' ms'}</b></span></div><div class="status-history" aria-label="Recent checks">${(x.history||[]).map(h=>`<span class="history-bar ${statusClass(h.status)}" title="${statusLabel(h.status)}"></span>`).join('')||'<span class="subtle">No recent history available</span>'}</div></article>`).join('')}</div></div>`).join('')}${k.url?`<p class="subtle">Source: <a href="${esc(k.url)}" target="_blank" rel="noopener noreferrer">Uptime Kuma public status page ↗</a></p>`:''}</section>`;}
async function loadKuma(){try{const r=await fetch('/api/kuma/status',{cache:'no-store'});const d=await r.json();state.kuma={...d,loading:false};}catch(e){state.kuma={configured:true,loading:false,services:[],error:'Could not load status'}}render();}
loadKuma();
// Refresh Kuma data every two minutes while the page is visible.
let kumaRefreshInFlight=false;
async function refreshKumaOnInterval(){
 if(document.visibilityState==='hidden'||kumaRefreshInFlight)return;
 kumaRefreshInFlight=true;
 try{await loadKuma();}finally{kumaRefreshInFlight=false;}
}
window.setInterval(refreshKumaOnInterval,120000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshKumaOnInterval();});
document.addEventListener('click',e=>{if(e.target.closest('[data-kuma-refresh]')){state.kuma.loading=true;render();refreshKumaOnInterval();}});


function homeLayoutAdmin(){const draft=normalizedHomeLayout(state.layoutDraft||state.homeLayout);return `<details class="panel admin-panel layout-editor settings-outer"><summary>Home layout editor</summary><div class="settings-group-body"><div class="section-head"><h3>Customize Home</h3></div><p class="subtle">Reorder, resize, or hide dashboard sections. Changes are previewed here until saved. Saved layout is shared with every visitor.</p><div class="layout-list">${draft.map((item,i)=>`<div class="layout-item" draggable="true" data-layout-drag="${item.id}"><span class="layout-grip" title="Drag to reorder">⠿</span><strong>${esc(HOME_NAMES[item.id])}</strong><label>Width <select data-layout-width="${item.id}"><option value="half" ${item.width==='half'?'selected':''}>50% (Half)</option><option value="full" ${item.width==='full'?'selected':''}>100% (Full)</option></select></label><label class="layout-visible"><input type="checkbox" data-layout-enabled="${item.id}" ${item.enabled?'checked':''}> Show</label><button type="button" class="btn secondary layout-arrow" data-layout-move="${item.id}" data-delta="-1" ${i===0?'disabled':''} aria-label="Move up">↑</button><button type="button" class="btn secondary layout-arrow" data-layout-move="${item.id}" data-delta="1" ${i===draft.length-1?'disabled':''} aria-label="Move down">↓</button></div>`).join('')}</div><div class="layout-actions"><button class="btn secondary" data-layout-preview="1">Preview Home</button><button class="btn" data-layout-save="1">Save for everyone</button><button class="btn secondary" data-layout-reset="1">Restore defaults</button><button class="btn secondary" data-layout-discard="1">Discard changes</button></div>${state.layoutMessage?`<p class="subtle" role="status">${esc(state.layoutMessage)}</p>`:''}</div></details>`;}
function updateLayoutDraft(fn){const draft=normalizedHomeLayout(state.layoutDraft||state.homeLayout).map(x=>({...x}));fn(draft);state.layoutDraft=draft;state.layoutMessage='Unsaved changes';render();}
async function loadHomeLayout(){try{const d=await dashboardRequest('/api/dashboard/layout');state.homeLayout=normalizedHomeLayout(d.layout);state.layoutDraft=null;}catch(e){console.warn('Layout unavailable:',e.message);state.homeLayout=normalizedHomeLayout(null);}render();}
document.addEventListener('change',e=>{const width=e.target.closest('[data-layout-width]'),enabled=e.target.closest('[data-layout-enabled]');if(width)updateLayoutDraft(d=>{d.find(x=>x.id===width.dataset.layoutWidth).width=width.value;});if(enabled)updateLayoutDraft(d=>{d.find(x=>x.id===enabled.dataset.layoutEnabled).enabled=enabled.checked;});});
document.addEventListener('click',async e=>{const move=e.target.closest('[data-layout-move]'),save=e.target.closest('[data-layout-save]'),reset=e.target.closest('[data-layout-reset]'),discard=e.target.closest('[data-layout-discard]');if(e.target.closest('[data-layout-preview]')){state.page='Home';render();return;}if(!move&&!save&&!reset&&!discard)return;if(move){updateLayoutDraft(d=>{const i=d.findIndex(x=>x.id===move.dataset.layoutMove),j=i+Number(move.dataset.delta);if(j>=0&&j<d.length)[d[i],d[j]]=[d[j],d[i]];});return;}if(discard){state.layoutDraft=null;state.layoutMessage='Changes discarded';render();return;}if(reset&&!confirm('Restore the default dashboard layout for everyone?'))return;try{const d=await dashboardRequest('/api/admin/layout',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(reset?{action:'reset'}:{layout:normalizedHomeLayout(state.layoutDraft||state.homeLayout)})});state.homeLayout=normalizedHomeLayout(d.layout);state.layoutDraft=null;state.layoutMessage=reset?'Default layout restored':'Layout saved for everyone';render();}catch(err){state.layoutMessage='Could not save: '+err.message;render();}});
let draggedLayoutId=null;
document.addEventListener('dragstart',e=>{const item=e.target.closest('[data-layout-drag]');if(!item)return;draggedLayoutId=item.dataset.layoutDrag;e.dataTransfer.effectAllowed='move';});
document.addEventListener('dragover',e=>{if(draggedLayoutId&&e.target.closest('[data-layout-drag]'))e.preventDefault();});
document.addEventListener('drop',e=>{const target=e.target.closest('[data-layout-drag]');if(!target||!draggedLayoutId)return;e.preventDefault();const source=draggedLayoutId;draggedLayoutId=null;if(source===target.dataset.layoutDrag)return;updateLayoutDraft(d=>{const from=d.findIndex(x=>x.id===source),to=d.findIndex(x=>x.id===target.dataset.layoutDrag);if(from<0||to<0)return;d.splice(to,0,d.splice(from,1)[0]);});});
document.addEventListener('dragend',()=>{draggedLayoutId=null;});
loadHomeLayout();

// Manual Plex refresh without signing out or reloading the dashboard.
document.addEventListener('click',e=>{if(e.target.closest('[data-plex-refresh]'))loadPlex();});


function gateSettingsAdmin(){if(!state.adminLoggedIn)return '';return `<div class="section-head" style="margin-top:25px"><h3>Community entry question</h3></div><p class="subtle">Set the question visitors answer before entering ScreenDen. Leave the answer blank to keep the current answer. Changing the answer signs out existing community sessions.</p><form id="gate-settings-form"><label>Question<input name="question" maxlength="160" minlength="5" required value="${esc(state.gateConfig.question)}"></label><label>New answer (optional)<input name="answer" type="password" autocomplete="new-password" minlength="4" maxlength="128" placeholder="Leave blank to keep current answer"></label><button class="btn" type="submit">Save entry question</button></form>${state.gateError?`<p class="notice">${esc(state.gateError)}</p>`:''}${state.gateSaved?`<p class="subtle">${esc(state.gateSaved)}</p>`:''}`;}
async function loadGateSettings(){if(!state.adminLoggedIn)return;try{const cfg=await dashboardRequest('/api/gate/admin');state.gateConfig=cfg;}catch(e){state.gateError=e.message;}render();}
document.addEventListener('submit',async e=>{if(e.target.id!=='gate-settings-form')return;e.preventDefault();const form=e.target;const data=Object.fromEntries(new FormData(form));try{const result=await dashboardRequest('/api/gate/admin',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({question:data.question,answer:data.answer,keepExisting:true})});state.gateError='';state.gateSaved=result.answerChanged?'Saved. Community sessions have been reset; enter the new answer to return.':'Question saved.';if(result.answerChanged){location.replace('/');return;}await loadGateSettings();}catch(err){state.gateError=err.message;state.gateSaved='';render();}});


// Presentation content: banners, welcome, entry cards, cleanup countdowns.
function presentationTop(){const p=state.presentation;return `<div class="presentation-top">${p.welcome?`<div class="presentation-welcome">${esc(p.welcome)}</div>`:''}${(p.banners||[]).map(b=>`<div class="presentation-banner"><strong>${esc(b.title)}</strong>${b.body?`<span>${esc(b.body)}</span>`:''}</div>`).join('')}${(p.timers||[]).map(t=>`<div class="presentation-timer"><strong>${esc(t.title)}</strong><span class="countdown" data-deadline="${esc(t.deadline)}" data-repeat="${esc(t.repeat||'')}">Calculating…</span></div>`).join('')}</div>`;}
function presentationModal(){const cards=state.presentation.cards||[];const unseen=cards.filter(c=>!sessionStorage.getItem('mh-card-seen-'+c.id));if(!unseen.length)return '';const c=unseen[0];return `<div class="presentation-backdrop" role="presentation"><div class="presentation-dialog" role="dialog" aria-modal="true" aria-labelledby="presentation-card-title"><h2 id="presentation-card-title">${esc(c.title)}</h2><p>${esc(c.body)}</p><button class="btn" data-presentation-dismiss="${esc(c.id)}">Got it</button>${unseen.length>1?`<small>${unseen.length} information cards</small>`:''}</div></div>`;}
function presentationAdmin(){if(!state.adminLoggedIn)return '';const p=state.presentationAll||{};const entries=(kind)=>Array.isArray(p[kind])?p[kind]:[];return `<div class="section-head" style="margin-top:25px"><h3>Site messages and countdowns</h3></div><p class="subtle">Announcements remain regular Home posts. Banners are prominent, information cards open when visitors arrive, and countdowns share one deadline.</p><form id="presentation-welcome"><label>Welcome message<textarea name="welcome" maxlength="500" rows="3">${esc(p.welcome||'')}</textarea></label><button class="btn" type="submit">Save welcome message</button></form>${['banner','card','timer'].map(kind=>{const plural=kind==='banner'?'banners':kind==='card'?'cards':'timers';return `<h3 style="margin-top:25px">${kind==='banner'?'Site banners':kind==='card'?'Opening information cards':'Countdown widgets'}</h3><form class="presentation-add" data-kind="${kind}"><label>Title<input name="title" maxlength="100" required placeholder="${kind==='timer'?'Game folder cleanup':'Message title'}"></label>${kind==='timer'?`<label>Cleanup deadline (local time)<input name="deadline" type="datetime-local" required></label>`:`<label>Message<textarea name="body" maxlength="1500" rows="3"></textarea></label>`}${kind==='timer'?`<label>Repeat <select name="repeat"><option value="none">One-time</option><option value="weekly">Weekly (same day and time)</option></select></label>`:''}<label>Expires (optional)<input name="expiresAt" type="datetime-local"></label><button class="btn" type="submit">Add ${kind}</button></form>${entries(plural).map(x=>`<div class="calendar-entry"><span>${esc(x.title)}${x.deadline?` · ${date(x.deadline)}`:''}</span><button class="btn secondary" data-presentation-delete="${esc(x.id)}" data-presentation-kind="${kind}">Delete</button></div>`).join('')}`}).join('')}${state.presentationError?`<p class="notice">${esc(state.presentationError)}</p>`:''}`;}
async function loadPresentation(){try{const d=await dashboardRequest('/api/presentation');state.presentation={welcome:d.welcome,banners:d.banners||[],cards:d.cards||[],timers:d.timers||[]};state.presentationAll=d.all||{};state.presentationError='';render();updateCountdowns();}catch(e){state.presentationError=e.message;console.warn('Site messages unavailable:',e.message)}}
function updateCountdowns(){document.querySelectorAll('.countdown[data-deadline]').forEach(el=>{let target=Date.parse(el.dataset.deadline);if(el.dataset.repeat==='weekly'){const now=Date.now();while(target<=now)target+=7*86400000;}const delta=target-Date.now();if(!Number.isFinite(delta)){el.textContent='Invalid deadline';return;}if(delta<=0){el.textContent='Cleanup time reached';return;}const sec=Math.ceil(delta/1000),days=Math.floor(sec/86400),h=Math.floor(sec%86400/3600),m=Math.floor(sec%3600/60),s=sec%60;el.textContent=(days?days+'d ':'')+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');});}
setInterval(updateCountdowns,1000);
document.addEventListener('click',e=>{const b=e.target.closest('[data-presentation-dismiss]');if(!b)return;sessionStorage.setItem('mh-card-seen-'+b.dataset.presentationDismiss,'1');render();updateCountdowns();});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='presentation-welcome'&&!f.matches('.presentation-add'))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));d.action=f.id==='presentation-welcome'?'welcome':f.dataset.kind;if(d.action==='timer')d.timezone=Intl.DateTimeFormat().resolvedOptions().timeZone;try{await dashboardRequest('/api/presentation',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(d)});await loadPresentation();}catch(err){state.presentationError=err.message;render();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-presentation-delete]');if(!b)return;if(!confirm('Delete this item?'))return;try{await dashboardRequest('/api/presentation',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:b.dataset.presentationKind,operation:'delete',id:b.dataset.presentationDelete})});await loadPresentation();}catch(err){state.presentationError=err.message;render();}});
loadPresentation();


// v3.4.13 dashboard tools: search local dashboard data, kiosk view, backup/restore.
function searchMatches(){const q=state.searchQuery.trim().toLowerCase();if(q.length<2)return [];
 const entries=[...(state.announcements||[]).map(x=>({kind:'Announcement',title:x.title,detail:x.body,page:'Home'})),...(state.events||[]).map(x=>({kind:'Event',title:x.title,detail:x.notes||'',page:'Calendar'})),...(state.party?.events||[]).map(x=>({kind:'Party event',title:x.title,detail:x.description||'',page:'Calendar'})),...flatSidebarLinks().map(x=>({kind:'Sidebar link',title:x.title,detail:x.description||'',url:x.url})),...(state.items||[]).map(x=>({kind:'Shared file',title:x.name,detail:x.type||'',page:'Shared Files'}))];
 return entries.filter(x=>(String(x.title||'')+' '+String(x.detail||'')).toLowerCase().includes(q)).slice(0,30);
}
function searchUI(){return `<section class="section tool-search"><div class="section-head"><h3>Search dashboard</h3><button class="btn secondary" data-search-close="1">Close</button></div><input id="dashboard-search" placeholder="Search announcements, events, sidebar links and loaded shared files" value="${esc(state.searchQuery)}" autocomplete="off"><div id="search-results">${searchMatches().map(x=>`<div class="file-row"><div><strong>${esc(x.title||'Untitled')}</strong><div class="subtle">${esc(x.kind)} · ${esc(String(x.detail||'').slice(0,160))}</div></div>${x.url?`<a class="btn secondary" target="_blank" rel="noopener noreferrer" href="${esc(x.url)}">Open ↗</a>`:`<button class="btn secondary" data-page="${esc(x.page)}">View</button>`}</div>`).join('')||'<p class="subtle">Enter at least two characters, or no matching loaded items.</p>'}</div></section>`;}
function configurationAdmin(){if(!state.adminLoggedIn)return '';return `<details class="panel admin-panel settings-outer"><summary>Backup & restore</summary><div class="settings-group-body"><h3>Backup and restore settings</h3><p class="subtle">Download dashboard configuration JSON. No credentials, sessions, private party data or API keys. Restore updates branding, layout, presentation and announcements; sidebar links are exported but not restored in this build.</p><button class="btn" data-config-export="1">Export configuration</button><label style="display:block;margin-top:16px">Restore JSON backup <input id="config-import-file" type="file" accept=".json,application/json"></label><button class="btn secondary" data-config-import="1">Restore selected backup</button>${state.backupMessage?`<p class="notice">${esc(state.backupMessage)}</p>`:''}</div></details>`;}
document.addEventListener('click',async e=>{
 if(e.target.closest('[data-search-open]')){state.searchOpen=true;render();document.getElementById('dashboard-search')?.focus();return;}
 if(e.target.closest('[data-search-close]')){state.searchOpen=false;render();return;}
 if(e.target.closest('[data-kiosk-toggle]')){state.kiosk=!state.kiosk;document.body.classList.toggle('kiosk-mode',state.kiosk);render();return;}
 if(e.target.closest('[data-config-export]')){try{const data=await dashboardRequest('/api/admin/config-backup');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='screenden-settings-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(err){state.backupMessage=err.message;render();}return;}
 if(e.target.closest('[data-config-import]')){const file=document.getElementById('config-import-file')?.files?.[0];if(!file){state.backupMessage='Choose a JSON file first';render();return;}if(file.size>200000){state.backupMessage='Backup file too large';render();return;}if(!confirm('Restore saved configuration? Existing settings with matching keys will be overwritten.'))return;try{const raw=await file.text();await dashboardRequest('/api/admin/config-backup',{method:'POST',headers:{'content-type':'application/json'},body:raw});location.reload();}catch(err){state.backupMessage=err.message;render();}return;}
});
document.addEventListener('input',e=>{if(e.target.id!=='dashboard-search')return;state.searchQuery=e.target.value;const result=document.getElementById('search-results');if(result){const p=document.createElement('div');p.innerHTML=searchUI();result.innerHTML=p.querySelector('#search-results').innerHTML;}});


// Nextcloud Lab is deliberately separate from the existing shared Nextcloud integration.
function ncLabPanel(){const s=state.ncLab;return `<details class="panel admin-panel settings-outer nc-lab"><summary>Nextcloud Lab — experimental (admin only)</summary><div class="settings-group-body"><h3>Personal Nextcloud connections</h3><p class="subtle">This is an isolated admin test area. Your existing shared Nextcloud feed and Files page remain unchanged. Connections tested here use the administrator's browser session only; visitor identity is not implemented yet.</p><p class="subtle">${s.secretConfigured?'Encryption secret configured.':'Before login testing, configure the NC_LAB_ENCRYPTION_KEY Worker secret (32+ characters).'}</p><form id="nc-lab-add" class="nc-lab-add"><label>Display name<input name="name" maxlength="70" placeholder="Family Nextcloud" required></label><label>Nextcloud HTTPS URL<input name="url" type="url" placeholder="https://cloud.example.com" required></label><button class="btn" type="submit">Add test installation</button></form><button class="btn secondary" data-nc-lab-reload="1">Refresh connections</button>${s.servers.map(x=>`<div class="panel nc-lab-server"><div class="section-head"><div><strong>${esc(x.name)}</strong><p class="subtle">${esc(x.url)} · ${x.username?'Connected as '+esc(x.username):'Not connected'}</p></div></div><div class="nc-lab-actions"><button class="btn secondary" data-nc-lab-test="${esc(x.id)}">Test server</button><button class="btn secondary" data-nc-lab-start="${esc(x.id)}" ${!s.secretConfigured?'disabled':''}>Connect account</button>${x.username?`<button class="btn secondary" data-nc-lab-browse="${esc(x.id)}">Browse my files</button><button class="btn secondary" data-nc-lab-disconnect="${esc(x.id)}">Disconnect</button>`:''}<button class="btn secondary" data-nc-lab-remove="${esc(x.id)}">Remove</button></div></div>`).join('')||'<p class="subtle">No experimental installations configured.</p>'}${s.activeId?`<div class="panel"><strong>Lab folder browser · ${esc(s.servers.find(x=>x.id===s.activeId)?.name||'Nextcloud')}</strong><p class="subtle">${esc(s.path||'Files root')}</p><div class="nc-lab-actions"><button class="btn secondary" data-nc-lab-up="1">Up</button><button class="btn secondary" data-nc-lab-pin="${esc(s.path)}">Pin current folder</button><button class="btn secondary" data-nc-lab-close="1">Close</button></div>${s.items.map(f=>`<div class="calendar-entry"><span>${f.folder?'▤':'▣'} ${esc(f.name)}</span>${f.folder?`<span class="nc-lab-actions"><button class="btn secondary" data-nc-lab-folder="${esc(f.path)}">Open</button><button class="btn secondary" data-nc-lab-pin="${esc(f.path)}">Pin</button></span>`:''}</div>`).join('')||'<p class="subtle">No items in this folder.</p>'}</div>`:''}<div class="panel"><strong>Lab pinned folders (admin preview only)</strong><p class="subtle">These are saved selections, not published to members or Home.</p>${s.pins.map(p=>`<div class="calendar-entry"><span>${esc(s.servers.find(x=>x.id===p.server_id)?.name||'Nextcloud')} / ${esc(p.label)} <small class="subtle">${esc(p.path||'/')}</small></span><span class="nc-lab-actions"><button class="btn secondary" data-nc-lab-preview="${esc(p.server_id)}" data-nc-lab-path="${esc(p.path)}">Browse</button><button class="btn secondary" data-nc-lab-unpin="${esc(p.server_id)}" data-nc-lab-path="${esc(p.path)}">Unpin</button></span></div>`).join('')||'<p class="subtle">No pinned folders yet.</p>'}</div>${s.message?`<p class="notice" role="status">${esc(s.message)}</p>`:''}<p class="subtle">Disconnect deletes locally stored credentials. Revoke the app password inside Nextcloud to invalidate it remotely.</p></div></details>`;}
async function ncLabReq(path,body){const r=await fetch('/api/lab/nextcloud/'+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'HTTP '+r.status);return d;}
async function ncLabLoad(){if(!state.adminLoggedIn)return;try{const d=await ncLabReq('servers');state.ncLab.servers=d.servers||[];state.ncLab.pins=d.pins||[];state.ncLab.secretConfigured=!!d.secretConfigured;}catch(e){state.ncLab.message=e.message;}render();}
async function ncLabBrowse(id,path=''){try{const d=await ncLabReq('browse?id='+encodeURIComponent(id)+'&path='+encodeURIComponent(path));state.ncLab.activeId=id;state.ncLab.path=path;state.ncLab.items=d.items||[];state.ncLab.message='';}catch(e){state.ncLab.message=e.message;}render();}
document.addEventListener('submit',async e=>{if(e.target.id!=='nc-lab-add')return;e.preventDefault();const f=new FormData(e.target);try{await ncLabReq('servers',{name:f.get('name'),url:f.get('url')});state.ncLab.message='Test installation added.';await ncLabLoad();}catch(x){state.ncLab.message=x.message;render();}});
document.addEventListener('click',async e=>{const t=e.target.closest('[data-nc-lab-reload],[data-nc-lab-test],[data-nc-lab-start],[data-nc-lab-disconnect],[data-nc-lab-remove],[data-nc-lab-browse],[data-nc-lab-folder],[data-nc-lab-up],[data-nc-lab-close], [data-nc-lab-pin], [data-nc-lab-unpin], [data-nc-lab-preview]');if(!t)return;e.preventDefault();const d=t.dataset;try{
 if(d.ncLabPin!==undefined){const path=d.ncLabPin;const label=prompt('Folder label',path.split('/').pop()||'Files root');if(label===null)return;await ncLabReq('pin',{id:state.ncLab.activeId,path,label});state.ncLab.message='Folder pinned in Lab only.';await ncLabLoad();return;}
 if(d.ncLabUnpin!==undefined){await ncLabReq('unpin',{id:d.ncLabUnpin,path:d.ncLabPath||''});state.ncLab.message='Lab pin removed.';await ncLabLoad();return;}
 if(d.ncLabPreview!==undefined){await ncLabBrowse(d.ncLabPreview,d.ncLabPath||'');return;}
 if(d.ncLabReload!==undefined){await ncLabLoad();return;}
 if(d.ncLabClose!==undefined){state.ncLab.activeId='';render();return;}
 if(d.ncLabUp!==undefined){await ncLabBrowse(state.ncLab.activeId,state.ncLab.path.split('/').slice(0,-1).join('/'));return;}
 if(d.ncLabFolder!==undefined){await ncLabBrowse(state.ncLab.activeId,d.ncLabFolder);return;}
 if(d.ncLabBrowse){await ncLabBrowse(d.ncLabBrowse);return;}
 if(d.ncLabTest){const r=await ncLabReq('test',{id:d.ncLabTest});state.ncLab.message=r.message+(r.version?' · '+r.version:'');}
 if(d.ncLabDisconnect){if(!confirm('Delete the stored Nextcloud connection from ScreenDen?'))return;const r=await ncLabReq('disconnect',{id:d.ncLabDisconnect});state.ncLab.message=r.notice;await ncLabLoad();return;}
 if(d.ncLabRemove){if(!confirm('Remove this test installation and its local credentials?'))return;await ncLabReq('remove',{id:d.ncLabRemove});state.ncLab.message='Test installation removed.';await ncLabLoad();return;}
 if(d.ncLabStart){const r=await ncLabReq('start',{id:d.ncLabStart});const w=window.open(r.loginUrl,'nextcloud-lab-login','width=650,height=780');state.ncLab.message='Complete login in Nextcloud. Checking for authorization…';render();for(let i=0;i<55;i++){await new Promise(done=>setTimeout(done,4000));const p=await ncLabReq('poll',{id:d.ncLabStart});if(p.connected){state.ncLab.message='Connected as '+p.username;try{w?.close()}catch{}await ncLabLoad();return;}}state.ncLab.message='Login timed out. Try connecting again.';}
 }catch(x){state.ncLab.message=x.message;}render();});
// Keep lab data fresh after an administrator unlocks Settings.
const ncLabRefreshObserver=new MutationObserver(()=>{if(state.page==='Settings'&&state.adminLoggedIn&&!state.ncLab.servers.length&&!state.ncLab._loaded){state.ncLab._loaded=true;ncLabLoad();}if(!state.adminLoggedIn)state.ncLab._loaded=false;});
ncLabRefreshObserver.observe(document.getElementById('app'),{childList:true});


// Shared Resources: external links only, including PDFs and APKs. No embedded PDF viewer.
function visibleResources(homeOnly){return (state.resources||[]).filter(r=>r.visibility!=='hidden'&&(r.visibility==='all'||(state.kiosk?r.visibility==='tv':r.visibility==='standard'))&&(!homeOnly||r.show_home));}
function resourcesPanel(homeOnly){const list=visibleResources(homeOnly);if(!list.length)return homeOnly?'':'<section class="section"><h3>Shared Resources</h3><p class="subtle">No resources are currently available in this viewing mode.</p></section>';
 const cards=list.map(r=>`<a class="resource-card panel" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(r.title)}"><span class="resource-icon" aria-hidden="true">${r.type==='apk'?'▣':r.type==='pdf'?'▤':r.type==='website'?'↗':'⇩'}</span><span class="resource-text"><strong>${esc(r.title)}</strong>${r.description?`<small>${esc(r.description)}</small>`:''}<small class="subtle">${esc(r.type.toUpperCase())} · Open external link ↗</small></span></a>`).join('');
 return `<section class="section resource-section"><div class="section-head"><div><h3>${state.kiosk?'TV Resources':'Shared Resources'}</h3><p class="subtle">Community downloads and useful links${state.kiosk?' · TV mode':''}</p></div>${homeOnly?'<button class="btn secondary" data-page="Resources">All resources →</button>':''}</div><div class="resource-grid">${cards}</div></section>`;}
function resourcesAdmin(){if(!state.adminLoggedIn)return '';const current=state.resources.find(r=>r.id===state.resourceEditId)||{};
 return `<details class="panel admin-panel settings-outer" id="resource-admin"><summary>Shared Resources · APKs, PDFs & links</summary><div class="settings-group-body"><p class="subtle">Manage externally hosted files (including public Google Drive links). TV Only resources appear only while TV mode is enabled. Visibility does not restrict access to the original URL.</p><form id="resource-form" class="resource-form"><label>Name<input name="title" maxlength="100" required value="${esc(current.title||'')}" placeholder="Android TV app"></label><label>External URL<input name="url" type="url" maxlength="2000" required value="${esc(current.url||'')}" placeholder="https://drive.google.com/file/d/..."></label><label class="resource-wide">Description (optional)<input name="description" maxlength="350" value="${esc(current.description||'')}" placeholder="What is this resource?"></label><label>Type<select name="type">${[['apk','APK / TV app'],['pdf','PDF document'],['file','Other file'],['website','Website']].map(([v,n])=>`<option value="${v}" ${current.type===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Visible in<select name="visibility">${[['all','All modes'],['tv','TV mode only'],['standard','Standard mode only'],['hidden','Hidden']].map(([v,n])=>`<option value="${v}" ${current.visibility===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Order<input name="position" type="number" value="${Number(current.position||0)}"></label><label class="resource-check"><input type="checkbox" name="show_home" ${current.show_home?'checked':''}> Show on Home dashboard</label><div class="resource-wide resource-actions"><button class="btn" type="submit">${current.id?'Save changes':'Add resource'}</button>${current.id?'<button class="btn secondary" type="button" data-resource-cancel="1">Cancel editing</button>':''}</div></form>${state.resourceMessage?`<p class="notice">${esc(state.resourceMessage)}</p>`:''}<div class="resource-admin-list">${state.resources.map(r=>`<div class="resource-admin-row"><div><strong>${esc(r.title)}</strong><div class="subtle">${esc(r.type)} · ${esc(r.visibility)} · ${r.show_home?'Home':'Resources page'}</div></div><div><button class="btn secondary" data-resource-edit="${esc(r.id)}">Edit</button> <button class="btn secondary" data-resource-delete="${esc(r.id)}">Remove</button></div></div>`).join('')||'<p class="subtle">No resources configured yet.</p>'}</div></div></details>`;}
async function loadResources(){try{const d=await dashboardRequest('/api/resources');state.resources=d.resources||[];}catch(e){console.warn('Shared resources unavailable:',e.message);}render();}
document.addEventListener('submit',async e=>{if(e.target.id!=='resource-form')return;e.preventDefault();const form=e.target;const d=Object.fromEntries(new FormData(form));d.show_home=form.elements.show_home.checked;d.action=state.resourceEditId?'update':'create';if(state.resourceEditId)d.id=state.resourceEditId;try{await dashboardRequest('/api/resources',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(d)});state.resourceEditId=null;state.resourceMessage='Resource saved.';await loadResources();}catch(ex){state.resourceMessage=ex.message;render();}});
document.addEventListener('click',async e=>{const edit=e.target.closest('[data-resource-edit]'),del=e.target.closest('[data-resource-delete]'),cancel=e.target.closest('[data-resource-cancel]');if(!edit&&!del&&!cancel)return;if(edit||cancel){state.resourceEditId=edit?edit.dataset.resourceEdit:null;state.resourceMessage='';render();document.getElementById('resource-admin')?.setAttribute('open','');return;}if(!confirm('Remove this resource link? The external file will not be deleted.'))return;try{await dashboardRequest('/api/resources',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'delete',id:del.dataset.resourceDelete})});state.resourceMessage='Resource removed.';await loadResources();}catch(ex){state.resourceMessage=ex.message;render();}});
loadResources();


// Ombi Lab is admin-only. Native Ombi login is NOT an OAuth handoff to ScreenDen.
state.ombiLab={message:'',details:'',busy:false,loggedIn:false,query:'',kind:'movie',results:[],searching:false};
function ombiLabPanel(){const x=state.ombiLab;return `<details class="panel admin-panel settings-outer"><summary>Ombi Lab — final authentication test (admin only)</summary><div class="settings-group-body"><h3>Ombi authentication diagnostics</h3><p class="subtle">Experimental only. No member-facing Ombi integration. The native login window cannot return a login session to ScreenDen; use the separate API credential test below.</p><p><strong>Server:</strong> https://example.com/ombi</p><div style="display:flex;flex-wrap:wrap;gap:8px;margin:12px 0"><button type="button" class="btn secondary" data-ombi-open>Open native Ombi login ↗</button><button type="button" class="btn secondary" data-ombi-test>Test API reachability</button></div><form id="ombi-lab-login" autocomplete="off" style="max-width:520px"><label>Ombi username<input name="username" autocomplete="username" required maxlength="120"></label><label>Ombi password<input name="password" type="password" autocomplete="current-password" required></label><button class="btn" type="submit" ${x.busy?'disabled':''}>${x.busy?'Testing…':'Test user API login once'}</button></form><p class="subtle">The password is sent to ScreenDen over HTTPS for this test, forwarded to Ombi, and not saved in ScreenDen. No JWT or password is returned to the browser.</p>${x.message?`<p class="notice" role="status">${esc(x.message)}</p>`:''}${x.details?`<pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(x.details)}</pre>`:''}</div></details>`;}
document.addEventListener('click',async e=>{if(e.target.closest('[data-ombi-open]')){window.open('https://example.com/ombi','_blank','noopener,noreferrer');return;}if(!e.target.closest('[data-ombi-test]'))return;try{const d=await dashboardRequest('/api/lab/ombi/health');state.ombiLab.message=d.message||'API checked';state.ombiLab.details='HTTP '+d.httpStatus+' · '+(d.contentType||'unknown content type');}catch(ex){state.ombiLab.message=ex.message;state.ombiLab.details='';}render();});
document.addEventListener('submit',async e=>{if(e.target.id!=='ombi-lab-login')return;e.preventDefault();if(state.ombiLab.busy)return;const f=e.target;const username=f.elements.username.value,password=f.elements.password.value;f.elements.password.value='';state.ombiLab.busy=true;try{const d=await dashboardRequest('/api/lab/ombi/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username,password})});state.ombiLab.message=d.message;state.ombiLab.details='HTTP '+d.httpStatus+' · '+(d.identity||'');}catch(ex){state.ombiLab.message=ex.message;state.ombiLab.details='';}finally{state.ombiLab.busy=false;render();}});

// Ombi Lab: admin-only standalone page. Never expose bearer tokens to frontend.
function ombiLabPage(){if(!state.adminLoggedIn)return '<div class="panel">Administrator access required.</div>';const x=state.ombiLab;const v=x.draft||{};return `<section class="section"><div class="section-head"><div><h2>Ombi Lab — Archived</h2><p class="subtle">Failed · No longer in development · Admin only. Use the existing Ombi sidebar link for media requests.</p></div><a class="btn secondary" href="https://example.com/ombi" target="_blank" rel="noopener noreferrer">Open Ombi ↗</a></div><div class="panel"><h3>Connect Ombi account</h3><form id="ombi-lab-session-login" class="resource-form" autocomplete="off"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><div class="resource-wide resource-actions"><button class="btn" type="submit">Connect account</button><button class="btn secondary" type="button" data-ombi-disconnect>Disconnect</button></div></form><p class="subtle">${x.loggedIn?'Connected':'Connect before submitting'} · Encrypted HttpOnly session</p></div><div class="panel"><h3>Find media</h3><form id="ombi-lab-search" class="resource-form"><label>Search title<input name="query" required maxlength="120" value="${esc(x.query)}" placeholder="Search movies or TV"></label><label>Media type<select name="kind"><option value="movie" ${x.kind==='movie'?'selected':''}>Movies</option><option value="tv" ${x.kind==='tv'?'selected':''}>TV shows</option></select></label><div class="resource-wide"><button class="btn" type="submit">Search Ombi</button></div></form><div style="margin-top:16px"><label>Or enter a verified TMDB ID directly<input id="ombi-manual-id" inputmode="numeric" pattern="[0-9]+" placeholder="South Park: 2190"></label><button class="btn secondary" type="button" data-ombi-manual="1">Open request window by TMDB ID</button></div>${x.message?`<p class="notice" role="status">${esc(x.message)}</p>`:''}<div class="resource-grid">${x.results.map((r,i)=>`<div class="panel resource-card"><strong>${esc(r.title||r.name||'Untitled')}</strong><p class="subtle">${esc(r.releaseDate||r.firstAired||r.year||'')}</p><p class="subtle">TMDB: ${esc(String(r.theMovieDbId||r.tmdbId||'Not provided'))} · Search ID: ${esc(String(r.id||'n/a'))}</p><p class="subtle">${esc(r.overview||r.summary||'').slice(0,240)}</p><button class="btn secondary" data-ombi-request="${i}">Review request</button></div>`).join('')}</div></div>${x.draft?`<div class="panel" id="ombi-request-window" style="border:2px solid var(--accent,#748bce);margin-top:18px"><div class="section-head"><div><h3>Request ${esc(v.kind==='tv'?'TV show':'movie')}: ${esc(v.title||'TMDB title')}</h3><p class="subtle">TMDB ID ${esc(String(v.id))} · Verify the title and season choices before submitting</p></div><button class="btn secondary" type="button" data-ombi-close="1">Close</button></div><form id="ombi-request-form" class="resource-form"><label>TMDB ID<input name="id" type="number" min="1" required value="${esc(String(v.id))}"></label><label>Media type<select name="kind"><option value="tv" ${v.kind==='tv'?'selected':''}>TV show</option><option value="movie" ${v.kind==='movie'?'selected':''}>Movie</option></select></label><div class="resource-wide" id="ombi-tv-fields" style="${v.kind==='tv'?'':'display:none'}"><h4>Seasons and episodes</h4><p class="subtle">Default: First Season. Ombi's details API may return 204, so you can enter season numbers yourself. Individual episode selection is not yet supported; each chosen season requests its episodes.</p><label>Selection<select name="scope"><option value="first" selected>First Season (recommended)</option><option value="latest">Latest Season</option><option value="custom">Selected Seasons</option><option value="all">All Seasons (explicit opt-in)</option></select></label><label>Season numbers (comma-separated)<input name="seasons" value="1" placeholder="1,2,3" required></label><button class="btn secondary" type="button" data-ombi-load-seasons="1">Try loading seasons from Ombi</button><p class="subtle" id="ombi-season-feedback">For Latest Season, enter the latest season number. For All Seasons, enter all known season numbers.</p></div><details class="resource-wide" style="margin-top:12px"><summary>Advanced Ombi / Sonarr options</summary><p class="subtle">Optional overrides. Copy IDs from your own Ombi settings; nothing is hardcoded.</p><label>Request on behalf of (Ombi user UUID)<input name="requestOnBehalf" placeholder="Optional user ID"></label><label>Root folder ID<input name="rootFolderOverride" placeholder="Optional, e.g. 4"></label><label>Quality profile ID<input name="qualityPathOverride" placeholder="Optional, e.g. 1"></label><label>Language code<input name="languageCode" value="en" maxlength="5"></label><label>Language profile ID<input name="languageProfile" placeholder="Optional"></label></details><div class="resource-wide"><button class="btn" type="submit">Submit request to Ombi</button><p class="subtle">This submits a real request. It does not download media directly.</p></div></form></div>`:''}</section>`;}
document.addEventListener('submit',async e=>{if(e.target.id==='ombi-lab-session-login'){e.preventDefault();const f=e.target;const username=f.elements.username.value,password=f.elements.password.value;f.elements.password.value='';try{const d=await dashboardRequest('/api/lab/ombi/session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username,password})});state.ombiLab.loggedIn=!!d.ok;state.ombiLab.message=d.message||'Connected';}catch(ex){state.ombiLab.message=ex.message;}render();}else if(e.target.id==='ombi-lab-search'){e.preventDefault();const f=e.target;state.ombiLab.query=f.elements.query.value.trim();state.ombiLab.kind=f.elements.kind.value;state.ombiLab.message='Searching…';state.ombiLab.results=[];render();try{const d=await dashboardRequest('/api/lab/ombi/search?kind='+encodeURIComponent(state.ombiLab.kind)+'&q='+encodeURIComponent(state.ombiLab.query));state.ombiLab.results=d.items||[];state.ombiLab.message=d.items?.length?`${d.items.length} results`:'No results';}catch(ex){state.ombiLab.message=ex.message;}render();}});
function ombiOpenDraft(id,kind,title){const n=Number(id);if(!Number.isSafeInteger(n)||n<=0){state.ombiLab.message='Missing valid TMDB ID. Use manual TMDB ID entry instead.';render();return;}state.ombiLab.draft={id:n,kind,title};state.ombiLab.message='';render();document.getElementById('ombi-request-window')?.scrollIntoView({behavior:'smooth',block:'start'});}
document.addEventListener('click',async e=>{
 if(e.target.closest('[data-ombi-disconnect]')){try{await dashboardRequest('/api/lab/ombi/session',{method:'DELETE'});state.ombiLab.loggedIn=false;state.ombiLab.results=[];state.ombiLab.draft=null;state.ombiLab.message='Disconnected';}catch(ex){state.ombiLab.message=ex.message;}render();return;}
 if(e.target.closest('[data-ombi-close]')){state.ombiLab.draft=null;render();return;}
 if(e.target.closest('[data-ombi-manual]')){const id=document.getElementById('ombi-manual-id')?.value;ombiOpenDraft(id,state.ombiLab.kind,'Manual TMDB lookup');return;}
 const b=e.target.closest('[data-ombi-request]');if(b){const r=state.ombiLab.results[Number(b.dataset.ombiRequest)];if(r)ombiOpenDraft(r.theMovieDbId||r.tmdbId,state.ombiLab.kind,r.title||r.name||'Untitled');return;}
 if(e.target.closest('[data-ombi-load-seasons]')){const form=document.getElementById('ombi-request-form');const id=form?.elements.id.value;const feedback=document.getElementById('ombi-season-feedback');if(!feedback)return;feedback.textContent='Loading from Ombi…';try{const d=await dashboardRequest('/api/lab/ombi/details?id='+encodeURIComponent(id));const seasons=(d.details?.seasons||[]).map(s=>Number(s.seasonNumber??s.season??s.number)).filter(n=>Number.isInteger(n)&&n>0);if(seasons.length){form.elements.seasons.value=[...new Set(seasons)].join(',');feedback.textContent='Loaded seasons: '+form.elements.seasons.value+'. Choose First/Latest/Selected/All before submitting.';}else feedback.textContent='Ombi returned no season data. Enter seasons manually. Diagnostics: '+JSON.stringify(d.report||[]).slice(0,500);}catch(ex){feedback.textContent=ex.message+' — Enter seasons manually.';}return;}
});
document.addEventListener('change',e=>{if(e.target.name==='kind'&&e.target.form?.id==='ombi-request-form'){document.getElementById('ombi-tv-fields').style.display=e.target.value==='tv'?'':'none';}if(e.target.name==='scope'&&e.target.form?.id==='ombi-request-form'){const seasons=e.target.form.elements.seasons;if(e.target.value==='first')seasons.value='1';}});
document.addEventListener('submit',async e=>{if(e.target.id!=='ombi-request-form')return;e.preventDefault();const f=e.target;const d=Object.fromEntries(new FormData(f));const seasons=d.seasons.split(',').map(s=>Number(s.trim())).filter(n=>Number.isSafeInteger(n)&&n>=0);if(d.kind==='tv'&&!seasons.length){state.ombiLab.message='Enter at least one season number';render();return;}if(d.scope==='all'&&!confirm('Request ALL entered seasons? This may download a large amount of media.'))return;if(!confirm('Submit '+d.kind+' TMDB '+d.id+' to Ombi with '+(d.kind==='tv'?d.scope+' season selection':'movie request')+'?'))return;try{const result=await dashboardRequest('/api/lab/ombi/request',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...d,seasons})});state.ombiLab.message=result.message||'Ombi responded. Check its request list.';state.ombiLab.draft=null;}catch(ex){state.ombiLab.message=ex.message;}render();});



function featuredArt(m){return m&&m.thumb?'/api/plex/art?server='+encodeURIComponent(m.machine)+'&path='+encodeURIComponent(m.thumb):'';}
function featuredAdminPanel(kind='show'){const s=featuredSlot(kind);const f=s.featuredAdmin;const chosen=s.featuredResults[s.featuredPreview];const results=s.featuredResults;return `<details class="panel admin-panel settings-outer featured-admin" data-featured-kind="${kind}" open><summary>${kind==='movie'?'Movie':'Show'} of the Week · Plex featured media</summary><div class="settings-group-body"><div class="featured-admin-head"><div><div class="eyebrow">CURATE YOUR LIBRARY</div><h3>Choose the next featured ${kind==='movie'?'movie':'show'}</h3><p class="subtle">Browse ${kind==='movie'?'movies':'TV shows'} already on your Plex servers. Pick a poster to preview before publishing.</p></div>${f?`<span class="featured-status">${f.enabled?'● Live on dashboard':'○ Hidden'}</span>`:''}</div><form id="featured-search-form-${kind}" data-featured-search="${kind}" class="featured-search"><label class="featured-search-label">Find a title<input name="query" required minlength="2" maxlength="100" placeholder="Search your Plex ${kind==='movie'?'movies':'TV shows'}…" value="${esc(s.featuredQuery)}"></label><button class="btn" type="submit">⌕ Search library</button></form>${s.featuredMessage?`<p class="featured-feedback" role="status">${esc(s.featuredMessage)}</p>`:''}${results.length?`<div class="featured-rail-header"><strong>Search results</strong><span class="subtle">${results.length} titles · Scroll to explore →</span></div><div class="featured-rail-wrap"><button type="button" class="featured-arrow" data-featured-scroll="-1" aria-label="Scroll posters left">❮</button><div class="featured-rail" id="featured-rail-${kind}">${results.map((m,i)=>`<button type="button" class="featured-tile ${i===s.featuredPreview?'selected':''}" data-featured-preview="${i}" aria-pressed="${i===s.featuredPreview}"><span class="featured-tile-art">${featuredArt(m)?`<img src="${esc(featuredArt(m))}" alt="${esc(m.title)} poster" loading="lazy" onerror="this.style.display='none'">`:''}<span class="featured-tile-fallback">${esc(m.title)}</span></span><strong>${esc(m.title)}</strong><small>${esc(m.year||'')} · ${m.type==='show'?'Series':'Movie'}</small></button>`).join('')}</div><button type="button" class="featured-arrow" data-featured-scroll="1" aria-label="Scroll posters right">❯</button></div>`:''}${chosen?`<div class="featured-preview"><div class="featured-preview-art">${featuredArt(chosen)?`<img src="${esc(featuredArt(chosen))}" alt="${esc(chosen.title)} poster" loading="lazy">`:''}</div><div class="featured-preview-info"><div class="eyebrow">READY TO FEATURE</div><h3>${esc(chosen.title)}</h3><p class="subtle">${esc(chosen.serverName)} · ${chosen.type==='show'?'TV series':'Movie'}${chosen.year?' · '+esc(chosen.year):''}</p><p>${esc(chosen.summary||'Selected from your Plex library.')}</p><label class="featured-note-label">Your recommendation (optional)<textarea id="featured-note-${kind}" maxlength="500" rows="3" placeholder="Why should everyone watch this?">${esc(s.featuredNote)}</textarea></label><button class="btn" type="button" data-featured-publish="1" ${s.featuredSaving?'disabled':''}>${s.featuredSaving?'Saving…':'★ Feature this title'}</button>${s.featuredSaveMessage?`<p class="featured-feedback" role="status">${esc(s.featuredSaveMessage)}</p>`:''}</div></div>`:''}${f?`<div class="featured-current"><div class="featured-current-info"><span class="featured-current-art">${f.art?`<img src="${esc(f.art)}" alt="" loading="lazy">`:''}</span><div><div class="eyebrow">CURRENT SELECTION</div><strong>${esc(f.title)}</strong><div class="subtle">${f.enabled?'Published on dashboard':'Currently hidden'} · ${esc(f.type||'')}</div></div></div><div class="featured-current-actions"><button type="button" class="btn secondary" data-featured-toggle="${f.enabled?'0':'1'}">${f.enabled?'Hide widget':'Republish'}</button><button type="button" class="btn secondary" data-featured-clear="1">Remove</button></div></div>`:''}</div></details>`;}

async function loadFeatured(kind){const kinds=kind?[kind]:['show','movie'];await Promise.all(kinds.map(async k=>{const s=featuredSlot(k);try{const d=await dashboardRequest('/api/featured?kind='+k);s.featured=d.featured||null;}catch(e){console.warn('Featured '+k+' unavailable:',e.message);}if(state.adminLoggedIn){try{const d=await dashboardRequest('/api/admin/featured?kind='+k);s.featuredAdmin=d.featured||null;}catch(e){console.warn('Featured '+k+' admin unavailable:',e.message);}}}));render();}
document.addEventListener('change',e=>{if(e.target.id==='plex-server-select'){const machine=e.target.value;if(state.plexServers.some(s=>s.machine===machine)){state.plexSelectedMachine=machine;plexStore('last',machine);render();}}});
document.addEventListener('submit',async e=>{if(!e.target.matches('[data-featured-search]'))return;e.preventDefault();const kind=e.target.dataset.featuredSearch,s=featuredSlot(kind);if(s.featuredSaving)return;s.featuredQuery=e.target.elements.query.value.trim();s.featuredMessage='Searching Plex…';render();try{const d=await dashboardRequest('/api/plex/catalog?kind='+kind+'&q='+encodeURIComponent(s.featuredQuery));s.featuredResults=(d.items||[]).filter(m=>m.type===kind);s.featuredPreview=-1;s.featuredNote='';s.featuredSaveMessage='';s.featuredMessage=s.featuredResults.length?s.featuredResults.length+' matching titles':'No matching Plex titles found';}catch(ex){s.featuredMessage=ex.message;}render();});
document.addEventListener('input',e=>{if(e.target.matches('textarea[id^=featured-note-]'))featuredSlot(e.target.closest('[data-featured-kind]').dataset.featuredKind).featuredNote=e.target.value;});
document.addEventListener('click',async e=>{
 const panel=e.target.closest('[data-featured-kind]');if(!panel)return;const kind=panel.dataset.featuredKind,s=featuredSlot(kind);
 const scroll=e.target.closest('[data-featured-scroll]');if(scroll){const rail=document.getElementById('featured-rail-'+kind);if(rail)rail.scrollBy({left:Number(scroll.dataset.featuredScroll)*Math.max(280,rail.clientWidth*.75),behavior:'smooth'});return;}
 const preview=e.target.closest('[data-featured-preview]');if(preview){if(s.featuredSaving)return;s.featuredPreview=Number(preview.dataset.featuredPreview);s.featuredNote='';s.featuredSaveMessage='';render();return;}
 const publish=e.target.closest('[data-featured-publish]'),toggle=e.target.closest('[data-featured-toggle]'),clear=e.target.closest('[data-featured-clear]');if((!publish&&!toggle&&!clear)||s.featuredSaving)return;
 let body;
 if(publish){const m=s.featuredResults[s.featuredPreview];if(!m){s.featuredMessage='Choose a title from the search results first.';render();return;}s.featuredNote=document.getElementById('featured-note-'+kind)?.value||s.featuredNote||'';body={action:'publish',machine:m.machine,ratingKey:m.ratingKey,note:s.featuredNote};}
 else if(toggle){body={action:'toggle',enabled:toggle.dataset.featuredToggle==='1'};}
 else{if(!confirm('Remove the featured title from the dashboard?'))return;body={action:'clear'};}
 s.featuredSaving=true;if(publish)s.featuredSaveMessage='Saving featured title…';else s.featuredMessage='Saving featured media…';render();
 try{
  // Publishing needs the Plex cookie, scoped to /api/plex, as well as the root admin cookie.
  await dashboardRequest((publish?'/api/plex/featured':'/api/admin/featured')+'?kind='+kind,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});
  if(publish)s.featuredSaveMessage='Featured title saved. It is now available on the dashboard.';else s.featuredMessage='Featured media saved.';
  await loadFeatured(kind);
 }catch(ex){if(publish)s.featuredSaveMessage='Could not feature this title: '+ex.message;else s.featuredMessage=ex.message;}
 finally{s.featuredSaving=false;render();}
});

loadFeatured();

// Dashboard-only personal Plex default control (browser-scoped per Plex account).
document.addEventListener('click',async e=>{const button=e.target.closest('[data-plex-default]');if(!button)return;e.preventDefault();const select=document.getElementById('plex-server-select');const machine=select?.value||state.plexSelectedMachine;if(!machine||!state.plexServers.some(s=>String(s.machine)===String(machine))){button.textContent='Select a server first';return;}state.plexSelectedMachine=machine;button.disabled=true;button.textContent='Saving…';
 try{const result=await plexFetch('preferences',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({defaultMachine:machine})});
  state.plexRemoteDefault=result.defaultMachine;state.plexPreferenceReady=true;
  plexStore('default',machine);plexStore('last',machine);render();
  const confirmation=document.querySelector('[data-plex-default]');if(confirmation){confirmation.disabled=false;confirmation.textContent='✓ Default saved to account';}
 }catch(ex){button.disabled=false;button.textContent='⚠ Save failed: '+ex.message;} });


// v3.5.0: D1-backed public news, changelog and admin-curated picks.
const RELEASE_NOTES=[
{version:'1.0.0-rc.1',date:'2026-10-23',type:'Release candidate',title:'ScreenDen — first public snapshot',sections:[['About',['ScreenDen is a self-hosted streaming-style homepage for your household: Plex movies, TV and watch progress, community news, requests and polls, plus an optional Nextcloud file feed and an optional Uptime Kuma service monitor.','This release candidate is the first public edition. It starts with neutral defaults and no pre-set servers, addresses or contacts — everything is configured by the admin who installs it.','A pre-publication pass replaced the inherited entry-gate default with a neutral starter question and answer, and the gate page itself now carries the ScreenDen name (change it on first sign-in — the starter stops working once you do), pointed the preview CORS allowlist at a placeholder origin, and renamed the Plex client identity and the config-backup format; backups in the legacy format still import.']],['Report a Problem',['Reports are always stored in the app for the admin. Email delivery is optional: set RESEND_API_KEY, REPORT_FROM_EMAIL and REPORT_TO_EMAIL on the Worker and reports are also emailed to the address you choose.']]]}
];

function tavernEnabled(id){return (state.pendingWidgetSettings||state.tavern.widgets)[id]!==false;}
const NEWS_DRAFT_KEY='mh_tavern_news_draft_v1';
function newsDraftRead(){try{return JSON.parse(localStorage.getItem(NEWS_DRAFT_KEY)||'null')}catch{return null}}
function newsDraftSave(form){try{const d=newsCapture(form);localStorage.setItem(NEWS_DRAFT_KEY,JSON.stringify({...d,savedAt:new Date().toISOString()}));return true}catch{return false}}
function newsCompose(){if(!state.newsCompose){const d=newsDraftRead();state.newsCompose={id:d?.id||'',title:d?.title||'',body:d?.body||'',category:d?.category||'announcement',clientId:d?.clientId||crypto.randomUUID()};}return state.newsCompose;}
function newsCapture(form=document.getElementById('tavern-news-form')){if(!form)return;const d=newsCompose();for(const k of ['id','title','body','category'])d[k]=form.elements[k]?.value||'';return d;}
function newsArchive(d){try{const key='mh_tavern_news_recovery_v1';let old=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(old))old=[];localStorage.setItem(key,JSON.stringify([{...d,savedAt:new Date().toISOString()},...old.filter(x=>x.title!==d.title||x.body!==d.body)].slice(0,5)));return true}catch{return false}}
function newsReset(clearLocal=true){state.newsCompose={id:'',title:'',body:'',category:'announcement',clientId:crypto.randomUUID()};if(clearLocal)try{localStorage.removeItem(NEWS_DRAFT_KEY)}catch{}}
async function publishNews(form){if(state.newsPublishing)return;const d={...newsCapture(form)};newsDraftSave(form);newsArchive(d);state.newsPublishing=true;state.tavern.message='Publishing… Your draft has been kept.';render();try{const result=await dashboardRequest('/api/admin/tavern',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'news-save',...d})});const a=result.article;if(!result.ok||!a?.id||a.title!==d.title.trim()||a.body!==d.body.trim())throw Error('The server did not confirm the saved article. Your draft is retained; retrying will not create a duplicate.');state.tavern.news=[a,...state.tavern.news.filter(x=>x.id!==a.id)];const did=state.newsDraftId;newsReset();state.newsDraftId='';state.newsDraftRevisions=[];if(did)dashboardRequest('/api/admin/news-drafts',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'delete',id:did})}).catch(()=>{});state.newsSkipCapture=true;state.tavern.message=d.id?'Post updated and confirmed in storage.':'Post published and confirmed in storage.';}catch(e){state.tavern.message='Publishing failed: '+e.message+' Your draft is retained below and on this device when browser storage is available.';}finally{state.newsPublishing=false;render();}}

// Server drafts (v3.6.16): named Tavern News drafts with revision history in
// D1, on top of the browser-local draft above. The local copy stays the
// keystroke buffer; the server copy is what survives a closed browser, a
// cleared cache or a different machine. See newsDraftsRoute in worker.js.
let newsAutosaveTimer=null;
async function loadNewsDrafts(){try{const d=await dashboardRequest('/api/admin/news-drafts');state.newsDrafts=d.drafts||[];}catch(e){state.newsAutosave={status:'Could not load server drafts: '+e.message};}state.newsDraftsLoaded=true;if(state.page==='Tavern News')render();}
function newsAutosaveStatus(text){state.newsAutosave={status:text};const el=document.getElementById('mh-news-autosave');if(el)el.textContent=text;}
function scheduleNewsAutosave(){if(!state.adminLoggedIn)return;clearTimeout(newsAutosaveTimer);newsAutosaveTimer=setTimeout(saveNewsDraftNow,2500);}
async function saveNewsDraftNow(){
 const c=newsCompose();
 if(!c.title.trim()&&!c.body.trim())return;
 newsAutosaveStatus('Autosaving to server…');
 try{
  const r=await dashboardRequest('/api/admin/news-drafts',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'save',id:state.newsDraftId||undefined,articleId:c.id||'',title:c.title,body:c.body,category:c.category})});
  state.newsDraftId=r.id;
  newsAutosaveStatus(r.unchanged?'Server draft is up to date.':'Autosaved to server at '+new Date(r.updatedAt).toLocaleTimeString()+'.');
  // Refresh the list silently: no render(), so typing is never interrupted.
  dashboardRequest('/api/admin/news-drafts').then(d=>{state.newsDrafts=d.drafts||[];}).catch(()=>{});
 }catch(e){newsAutosaveStatus('Server autosave failed ('+e.message+') — the local copy on this device is still current.');}
}
function newsDraftsPanel(){
 const rows=state.newsDrafts.map(d=>`<div class="mh-draft-row"><div class="mh-draft-main"><strong>${esc(d.title||'Untitled draft')}</strong><span class="subtle">${esc(newsCategory(d.category))} · Updated ${esc(new Date(d.updatedAt).toLocaleString())}</span>${d.preview?`<span class="subtle mh-draft-preview">${esc(d.preview)}…</span>`:''}</div><div class="mh-draft-actions"><button class="btn secondary" type="button" data-draft-load="${esc(d.id)}">Load</button><button class="btn secondary" type="button" data-draft-delete="${esc(d.id)}">Delete</button></div></div>`).join('');
 const revs=state.newsDraftId?`<div class="mh-draft-revisions"><h4>Revision history — loaded draft</h4>${state.newsDraftRevisions.length?state.newsDraftRevisions.map(r=>`<div class="mh-draft-row"><div class="mh-draft-main"><strong>${esc(r.title||'Untitled')}</strong><span class="subtle">Saved ${esc(new Date(r.savedAt).toLocaleString())}</span></div><button class="btn secondary" type="button" data-draft-restore="${r.id}">Restore</button></div>`).join(''):'<p class="subtle">No revisions yet — the next autosave creates the first one.</p>'}</div>`:'';
 return `<div class="panel mh-drafts"><div class="section-head"><div><div class="eyebrow">SERVER DRAFTS</div><h3>Article drafts</h3><p class="subtle">Drafts autosave to the server as you type and survive closing the browser. Publishing a post removes the server draft it came from.</p></div><span class="tag">${state.newsDrafts.length} saved</span></div>${state.newsAutosave.status?`<p class="subtle" role="status">${esc(state.newsAutosave.status)}</p>`:''}${rows||'<p class="subtle">No server drafts yet. Start typing above and one will be kept here.</p>'}${revs}</div>`;
}




function newsCategory(value){return ({announcement:'Announcement',maintenance:'Maintenance',update:'Development update',event:'Community event',notice:'Important notice'})[value]||'Announcement'}
document.addEventListener('click',async e=>{
 const load=e.target.closest('[data-draft-load]'),del=e.target.closest('[data-draft-delete]'),res=e.target.closest('[data-draft-restore]');
 if(load){
  try{const d=await dashboardRequest('/api/admin/news-drafts?id='+encodeURIComponent(load.dataset.draftLoad));
   state.newsCompose={id:d.draft.articleId||'',title:d.draft.title,body:d.draft.body,category:d.draft.category,clientId:crypto.randomUUID()};
   state.newsDraftId=d.draft.id;state.newsDraftRevisions=d.revisions||[];
   try{localStorage.setItem(NEWS_DRAFT_KEY,JSON.stringify({...state.newsCompose,savedAt:new Date().toISOString()}));}catch{}
   state.newsSkipCapture=true;state.tavern.message='Draft loaded into the editor.';render();
  }catch(ex){state.tavern.message='Could not load that draft: '+ex.message;render();}
 }
 if(del){
  if(!confirm('Delete this draft and its revision history? This cannot be undone.'))return;
  try{await dashboardRequest('/api/admin/news-drafts',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'delete',id:del.dataset.draftDelete})});
   if(state.newsDraftId===del.dataset.draftDelete){state.newsDraftId='';state.newsDraftRevisions=[];}
   state.tavern.message='Draft deleted.';await loadNewsDrafts();
  }catch(ex){state.tavern.message='Could not delete that draft: '+ex.message;render();}
 }
 if(res){
  try{const r=await dashboardRequest('/api/admin/news-drafts',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'restore',id:state.newsDraftId,revisionId:Number(res.dataset.draftRestore)})});
   state.newsCompose={id:state.newsCompose.id,title:r.draft.title,body:r.draft.body,category:r.draft.category,clientId:state.newsCompose.clientId};
   const d=await dashboardRequest('/api/admin/news-drafts?id='+encodeURIComponent(state.newsDraftId));state.newsDraftRevisions=d.revisions||[];
   state.newsSkipCapture=true;state.tavern.message='Revision restored into the editor. The replaced text was kept as a new revision.';render();
  }catch(ex){state.tavern.message='Could not restore that revision: '+ex.message;render();}
 }
});

// Per-widget "something's broken" button (v3.6.17): opens Report a Problem
// with the widget and app version attached automatically, so the member
// only has to describe what happened.
document.addEventListener('click',e=>{const b=e.target.closest('[data-broken-widget]');if(!b)return;state.reportContext={widget:HOME_NAMES[b.dataset.brokenWidget]||b.dataset.brokenWidget};state.page='Report a Problem';render();setTimeout(()=>{document.querySelector('#mh-report [name="details"]')?.focus();},60);});
function newsPage(){const admin=state.adminLoggedIn;const draft=admin?newsDraftRead():null;const compose=admin?newsCompose():null;if(admin&&!state.newsDraftsLoaded&&!state.newsDraftsLoading){state.newsDraftsLoading=true;Promise.resolve().then(()=>loadNewsDrafts()).finally(()=>{state.newsDraftsLoading=false;});}const editor=admin?`<div class="panel tavern-news-editor mh-news-studio"><div class="mh-news-studio-head"><div><div class="eyebrow">ADMIN PUBLISHING STUDIO</div><h3>Create a Tavern News post</h3><p class="subtle">Compose an announcement, review the preview, then publish it to the Tavern.</p></div><span class="mh-news-status" id="mh-news-status">${draft?'Unsaved draft available':'New post'}</span></div><form id="tavern-news-form" method="post" action="/api/admin/tavern"><input type="hidden" name="id" value="${esc(compose.id)}"><div class="mh-news-editor-grid"><div class="mh-news-compose"><label>Post type <select name="category">${['announcement','maintenance','update','event','notice'].map(x=>`<option value="${x}" ${compose.category===x?'selected':''}>${esc(newsCategory(x))}</option>`).join('')}</select></label><label>Headline <span class="mh-required">*</span><input name="title" maxlength="140" required placeholder="Give your update a clear, compelling headline" value="${esc(compose.title)}"><small class="subtle" data-news-count="title">0 / 140</small></label><label>Post content <span class="mh-required">*</span><textarea name="body" rows="12" maxlength="5000" required placeholder="Write your announcement here. Use short paragraphs for readability.&#10;&#10;What changed? What should members know? What happens next?">${esc(compose.body)}</textarea><small class="subtle" data-news-count="body">0 / 5000</small></label><p class="subtle mh-news-hint">Use blank lines to separate paragraphs. Content is displayed as plain text for safety.</p></div><aside class="mh-news-preview-wrap"><div class="mh-news-preview-heading"><strong>Live preview</strong><span class="subtle">As members will see it</span></div><article class="mh-news-preview" aria-live="polite"><span class="mh-news-category" data-news-preview="category">Announcement</span><h3 data-news-preview="title">Your headline appears here</h3><small class="subtle">Tavern News · Preview</small><p class="tavern-body" data-news-preview="body">Start writing to see your post.</p></article></aside></div><div class="mh-news-actions"><button class="btn" type="submit" data-news-publish ${state.newsPublishing?'disabled':''}>${state.newsPublishing?'Publishing…':compose.id?'Save changes':'Publish to Tavern →'}</button><button class="btn secondary" type="button" data-news-save-draft>Save draft on this device</button><button class="btn secondary" type="button" data-news-load-draft ${draft?'':'hidden'}>Restore draft</button><button class="btn secondary" type="button" data-tavern-cancel-edit="1" hidden>Cancel editing</button><button class="btn secondary" type="button" data-news-clear>Clear editor</button><button class="btn secondary" type="button" data-news-recover-last>Recover last submitted article</button><span class="subtle" id="mh-news-autosave" role="status"></span></div><p class="subtle" id="mh-news-feedback" role="status">Publishing makes your post visible to all Tavern members.</p></form>${state.tavern.message?`<p class="notice" role="status">${esc(state.tavern.message)}</p>`:''}</div>`:'';return `<section class="section mh-news-page"><div class="section-head"><div><div class="eyebrow">FROM THE TAVERN</div><h2>Tavern News</h2><p class="subtle">Updates, community announcements and maintenance notices.</p></div><button class="btn secondary" data-tavern-refresh="1">Refresh news</button></div>${editor}${admin?newsDraftsPanel():''}<div class="mh-news-feed-heading"><h3>Published posts</h3><span class="subtle">${state.tavern.news.length} ${state.tavern.news.length===1?'post':'posts'}</span></div><div class="tavern-news-list">${state.tavern.news.length?state.tavern.news.map(n=>`<article class="panel tavern-post mh-news-post"><div class="mh-news-post-meta"><span class="mh-news-category">${esc(newsCategory(n.category))}</span><small class="subtle">${esc(date(n.updatedAt))}</small></div><h3>${esc(n.title)}</h3><p class="tavern-body">${esc(n.body)}</p>${admin?`<div class="news-post-actions"><button class="btn secondary" data-tavern-edit="${esc(n.id)}">Edit post</button><button class="btn secondary" data-tavern-delete="${esc(n.id)}">Delete</button></div>`:''}</article>`).join(''):'<div class="panel mh-news-empty">No posts yet. Published Tavern updates will appear here.</div>'}</div></section>`;}
function newsPreview(form){if(!form)return;const title=form.elements.title.value,body=form.elements.body.value,category=form.elements.category.value;const root=form.closest('.mh-news-studio');if(!root)return;root.querySelector('[data-news-preview="title"]').textContent=title.trim()||'Your headline appears here';root.querySelector('[data-news-preview="body"]').textContent=body.trim()||'Start writing to see your post.';root.querySelector('[data-news-preview="category"]').textContent=newsCategory(category);root.querySelector('[data-news-count="title"]').textContent=title.length+' / 140';root.querySelector('[data-news-count="body"]').textContent=body.length+' / 5000';}
document.addEventListener('input',e=>{const form=e.target.closest('#tavern-news-form');if(form){newsPreview(form);const saved=newsDraftSave(form);const feedback=document.getElementById('mh-news-feedback');if(feedback)feedback.textContent=saved?'Draft saved automatically on this device. Not published yet.':'Browser storage is unavailable. Keep this tab open or copy your text before leaving.';scheduleNewsAutosave();}});
document.addEventListener('change',e=>{const form=e.target.closest('#tavern-news-form');if(form)newsPreview(form)});
document.addEventListener('click',e=>{const btn=e.target.closest('[data-news-save-draft],[data-news-load-draft],[data-news-clear]');if(!btn)return;const form=document.getElementById('tavern-news-form');if(!form)return;const feedback=document.getElementById('mh-news-feedback');if(btn.hasAttribute('data-news-save-draft')){feedback.textContent=newsDraftSave(form)?'Draft saved on this device. It has not been published.':'Unable to save draft on this device.';const load=form.querySelector('[data-news-load-draft]');if(load)load.hidden=false;}else if(btn.hasAttribute('data-news-load-draft')){const d=newsDraftRead();if(d){form.elements.id.value=d.id||'';newsCompose().clientId=d.clientId||crypto.randomUUID();form.elements.title.value=d.title||'';form.elements.body.value=d.body||'';form.elements.category.value=d.category||'announcement';newsCapture(form);newsPreview(form);feedback.textContent='Local draft restored. Review before publishing.';}}else if(confirm('Clear the editor? Your saved local draft will be kept.')){newsArchive({...newsCapture(form)});form.reset();form.elements.id.value='';newsReset(false);form.querySelector('[type=submit]').textContent='Publish to Tavern →';form.querySelector('[data-tavern-cancel-edit]').hidden=true;newsPreview(form);feedback.textContent='Editor cleared.';}});
function newsWidget(){const n=state.tavern.news[0];if(!n||!myTavernExtraVisible('news'))return '';return `<section class="section"><div class="section-head"><h3>Latest Tavern News</h3><button class="btn secondary" data-page="Tavern News">All news →</button></div><div class="panel"><strong>${esc(n.title)}</strong><p class="tavern-body">${esc(n.body.slice(0,250))}${n.body.length>250?'…':''}</p></div></section>`;}
function changelogPage(){return `<section class="section release-notes"><div class="section-head"><div><div class="eyebrow">WHAT'S NEW</div><h2>Changelog</h2><p class="subtle">Features, improvements, fixes, and known limitations across ScreenDen releases.</p></div></div><div class="release-timeline">${RELEASE_NOTES.map((r,i)=>`<article class="panel release-entry"><div class="release-entry-head"><div><span class="release-version">v${esc(r.version)}</span>${i===0?'<span class="release-latest">Latest</span>':''}<h3>${esc(r.title)}</h3><p class="subtle">${esc(r.date)} · ${esc(r.type)}</p></div></div>${r.sections.map(([heading,items])=>`<div class="release-section"><h4>${esc(heading)}</h4><ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`).join('')}</article>`).join('')}</div></section>`;}
function staffPicksWidget(){if(!myTavernExtraVisible('staff')||!state.tavern.picks.length)return '';return `<section class="section"><div class="section-head"><h3>Staff Picks</h3></div><div class="media-grid tavern-picks">${state.tavern.picks.map(m=>`<a class="media-card" href="${esc(m.link)}" target="_blank" rel="noopener noreferrer"><div class="art">${m.thumb?`<img loading="lazy" src="/api/plex/art?server=${encodeURIComponent(m.machine)}&path=${encodeURIComponent(m.thumb)}" alt="">`:''}<span class="art-title">${esc(m.title)}</span></div><strong>${esc(m.title)}</strong><small>${esc(m.year||'')} · ${esc(m.note||'Staff recommendation')}</small></a>`).join('')}</div></section>`;}
const MY_TAVERN_EXTRA='mh_my_tavern_extras_v1';
function myTavernExtraPrefs(){try{const v=JSON.parse(localStorage.getItem(MY_TAVERN_EXTRA)||'{}');return v&&typeof v==='object'?v:{}}catch{return {}}}
function myTavernExtraVisible(k){return myTavernExtraPrefs()[k]!==false;}
function myTavernExtrasSettings(){const p=myTavernExtraPrefs(),resources=visibleResources(false);return `<div class="panel" style="margin-top:14px"><h4>Favorite services</h4><p class="subtle">Pinned services appear in the movable Favorite Services widget.</p>${resources.map(r=>`<label class="layout-item"><input type="checkbox" data-tavern-favorite="${esc(r.id)}" ${Array.isArray(p.favorites)&&p.favorites.includes(String(r.id))?'checked':''}> ${esc(r.title||r.name||'Resource')}</label>`).join('')||'<p class="subtle">No shared resources available.</p>'}</div>`;}

function favoriteServicesWidget(){const p=myTavernExtraPrefs(),ids=Array.isArray(p.favorites)?p.favorites:[],list=visibleResources(false).filter(r=>ids.includes(String(r.id)));if(!list.length)return '';return `<section class="section"><h3>Favorite Services</h3><div class="panel">${list.map(r=>`<a class="btn secondary" style="margin:5px" href="${esc(r.url||r.href||'#')}" target="_blank" rel="noopener noreferrer">${esc(r.title||r.name||'Resource')} ↗</a>`).join('')}</div></section>`;}
document.addEventListener('change',e=>{const extra=e.target.closest('[data-tavern-extra],[data-tavern-favorite]');if(!extra)return;const p=myTavernExtraPrefs();if(extra.dataset.tavernExtra)p[extra.dataset.tavernExtra]=extra.checked;else{const id=extra.dataset.tavernFavorite;const fav=new Set(Array.isArray(p.favorites)?p.favorites:[]);extra.checked?fav.add(id):fav.delete(id);p.favorites=[...fav];}try{localStorage.setItem(MY_TAVERN_EXTRA,JSON.stringify(p));}catch{alert('Could not save favorites on this device.');}render();});
async function loadTavern(){try{const d=await dashboardRequest('/api/tavern');state.tavern.news=d.news||[];state.tavern.picks=d.picks||[];state.tavern.widgets=d.widgets||{surprise:true,staff:true,news:true};}catch(e){state.tavern.message='Could not refresh news: '+e.message+'. Any draft is retained.';console.warn('Tavern unavailable:',e.message);}render();}
function tavernAdmin(){const t=state.tavern;return `<details class="panel admin-panel settings-outer"><summary>Tavern News, Staff Picks & widget availability</summary><div class="settings-group-body"><h3>Widget availability</h3>${[['surprise','Surprise Me · Movies'],['surpriseShow','Surprise Me · TV Shows'],['roulette','Watch Roulette'],['staff','Staff Picks'],['news','Latest Tavern News'],['movieNight','Movie Night Voting'],['games','Recently Added Games']].map(([id,name])=>`<label class="layout-item"><input type="checkbox" data-tavern-widget="${id}" ${tavernEnabled(id)?'checked':''}> ${name} (available to users)</label>`).join('')}<h3>Recently Added Games</h3><p class="subtle">Use the game importer to browse authorized Nextcloud folders, match titles to Steam metadata, and publish games to the dashboard.</p><p><a class="btn secondary" href="/media-discovery">Open Game Importer ↗</a></p><h3>Staff Picks</h3><p class="subtle">Search your Plex catalog, choose a title, and publish multiple recommendations.</p><form id="tavern-pick-search"><input name="q" placeholder="Search Plex movies and shows" minlength="2" required><button class="btn secondary" type="submit">Search</button></form>${t.matches.map((m,i)=>`<button class="btn secondary" data-tavern-select="${i}">${esc(m.title)} (${esc(m.year||'')})</button>`).join('')}${t.selected?`<form id="tavern-pick-add"><strong>${esc(t.selected.title)}</strong><label>Recommendation (optional)<input name="note" maxlength="300"></label><button class="btn" type="submit">Add Staff Pick</button></form>`:''}${t.picks.map(m=>`<div class="layout-item"><strong>${esc(m.title)}</strong><button class="btn secondary" data-tavern-unpick="${esc(m.machine+':'+m.ratingKey)}">Remove</button></div>`).join('')}${t.message?`<p class="notice">${esc(t.message)}</p>`:''}</div></details>`;}
async function tavernPost(body){await dashboardRequest('/api/admin/tavern',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});await loadTavern();}
document.addEventListener('submit',async e=>{const formId=e.target.getAttribute('id');if(!['tavern-news-form','tavern-pick-search','tavern-pick-add'].includes(formId))return;e.preventDefault();try{if(formId==='tavern-news-form'){await publishNews(e.target);}else if(formId==='tavern-pick-search'){const q=e.target.elements.q.value.trim();const d=await dashboardRequest('/api/plex/catalog?q='+encodeURIComponent(q));state.tavern.matches=d.items||[];state.tavern.selected=null;render();}else{const m=state.tavern.selected;if(!m)return;await tavernPost({action:'pick-add',machine:m.machine,ratingKey:m.ratingKey,note:e.target.elements.note.value});state.tavern.selected=null;state.tavern.matches=[];render();}}catch(ex){state.tavern.message=ex.message;render();}});
document.addEventListener('click',async e=>{if(e.target.closest('[data-tavern-refresh]'))return loadTavern();const cancel=e.target.closest('[data-tavern-cancel-edit]');if(cancel){const f=document.getElementById('tavern-news-form');if(f){newsArchive({...newsCapture(f)});f.reset();f.elements.id.value='';newsReset(false);f.querySelector('[type=submit]').textContent='Publish post';cancel.hidden=true;newsPreview(f);}return;}const s=e.target.closest('[data-tavern-select]');if(s){state.tavern.selected=state.tavern.matches[Number(s.dataset.tavernSelect)];render();return;}const ed=e.target.closest('[data-tavern-edit]');if(ed){const n=state.tavern.news.find(x=>x.id===ed.dataset.tavernEdit);const f=document.getElementById('tavern-news-form');if(n&&f){f.elements.id.value=n.id;f.elements.title.value=n.title;f.elements.body.value=n.body;f.elements.category.value=n.category||'announcement';newsPreview(f);const submit=f.querySelector('[type=submit]');if(submit)submit.textContent='Save changes';const cancel=f.querySelector('[data-tavern-cancel-edit]');if(cancel)cancel.hidden=false;f.scrollIntoView({behavior:'smooth'});}return;}const del=e.target.closest('[data-tavern-delete]'),unpick=e.target.closest('[data-tavern-unpick]');if(!del&&!unpick)return;if(!confirm('Remove this entry?'))return;try{await tavernPost(del?{action:'news-delete',id:del.dataset.tavernDelete}:{action:'pick-remove',key:unpick.dataset.tavernUnpick});}catch(ex){state.tavern.message=ex.message;render();}});
document.addEventListener('change',e=>{const el=e.target.closest('[data-tavern-widget]');if(!el)return;state.pendingWidgetSettings={...(state.pendingWidgetSettings||state.tavern.widgets),[el.dataset.tavernWidget]:el.checked};state.adminSaveMessage='Unsaved widget settings';render();});
window.addEventListener('DOMContentLoaded',loadTavern);

// 3.5.1: Movie Night, Help/FAQ, Report a Problem, and Uptime Kuma history.
function movieNightWidget(){const p=state.community351.poll;if(!p||!tavernEnabled('movieNight'))return '';return `<section class="section"><div class="section-head"><h3>Movie Night Voting</h3></div><div class="panel"><strong>${esc(p.title)}</strong><p class="subtle">${p.options.length} movies · ${Date.parse(p.deadline)>Date.now()?'Vote by '+date(p.deadline):'Results available'}</p><button class="btn secondary" data-page="Movie Night">View Movie Night →</button></div></section>`}
function movieNightPage(){const c=state.community351,p=c.poll;if(!p)return `<section class="section"><h2>Movie Night</h2><div class="panel">No active movie vote is published.</div></section>`;const closed=Date.parse(p.deadline)<=Date.now();return `<section class="section"><h2>Movie Night Voting</h2><div class="panel"><h3>${esc(p.title)}</h3><p class="subtle">${closed?'Voting closed':'Vote before '+date(p.deadline)}. One vote per Plex account.</p>${p.options.map(o=>{const count=c.votes.find(v=>v.id===o.id)?.votes||0;return `<div class="layout-item"><div><strong>${esc(o.title)}</strong> ${o.year?`(${esc(o.year)})`:''}<p class="subtle">${closed?count+' vote(s)':''}</p></div>${!closed?`<button class="btn secondary" data-movie-vote="${esc(o.id)}" ${!state.plexUser?'disabled':''}>${c.myVote===o.id?'✓ Voted':'Vote'}</button>`:''}</div>`}).join('')}${!state.plexUser?'<p class="subtle">Sign into Plex on Home to vote.</p>':''}${closed?(()=>{const winner=p.options.slice().sort((a,b)=>(c.votes.find(v=>v.id===b.id)?.votes||0)-(c.votes.find(v=>v.id===a.id)?.votes||0))[0];const link=winner?'https://app.plex.tv/desktop/#!/server/'+encodeURIComponent(winner.machine)+'/details?key='+encodeURIComponent('/library/metadata/'+winner.ratingKey):'';return `<p><strong>Winner:</strong> ${esc(winner?.title||'None')} ${link?`<a class="btn secondary" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open in Plex ↗</a>`:''}</p>`})():''}</div></section>`}
function reportPage(){return `<section class="section mh-report-page"><div class="mh-report-intro"><div class="eyebrow">TAVERN SUPPORT</div><h2>How can we help?</h2><p class="subtle">Found a bug, something broken, or have an idea? Send the team a detailed report. We'll review it and reply if you provide an email address.</p></div><div class="panel mh-report-card"><div class="mh-report-card-title"><span class="mh-report-symbol">✉</span><div><h3>Send a support request</h3><p class="subtle">Delivered to the report address your admin configured, when email delivery is set up.</p></div></div><form id="mh-report" class="mh-report-form">${state.reportContext?`<p class="notice" role="status">Reporting the <strong>${esc(state.reportContext.widget)}</strong> widget · ScreenDen ${esc(MEDIA_HUB_VERSION)}. The widget and app version are attached to your report automatically — just describe what happened below.</p>`:''}<div class="mh-report-row"><label>What do you need help with? <span aria-hidden="true">*</span><select name="category" required><option value="bug">Something isn't working</option><option value="account">Account or sign-in</option><option value="media">Media or library issue</option><option value="suggestion">Suggestion or feedback</option><option value="other">Something else</option></select></label><label>Your email (for a reply)<input name="email" type="email" maxlength="254" autocomplete="email" placeholder="you@example.com"></label></div><label>Subject <span aria-hidden="true">*</span><input name="subject" maxlength="120" placeholder="A short summary of the problem" value="${state.reportContext?esc('Problem with '+state.reportContext.widget):''}" required></label><label>Tell us what happened <span aria-hidden="true">*</span><textarea name="details" maxlength="3000" minlength="10" rows="8" placeholder="What were you trying to do? What happened instead? Include any error message and steps to reproduce it." required></textarea></label><div class="mh-report-row"><label>Where did it happen?<select name="area"><option value="dashboard">Dashboard</option><option value="plex">Plex</option><option value="nextcloud">Shared files / Nextcloud</option><option value="settings">Settings</option><option value="other">Other</option></select></label><label>Urgency<select name="priority"><option value="normal">Normal</option><option value="low">Low — suggestion</option><option value="high">High — blocking use</option></select></label></div><p class="subtle mh-report-note">Please don't include passwords, tokens, or private account information. Submissions are rate-limited to prevent spam.</p><div class="mh-report-actions"><button class="btn" type="submit">Send support request →</button><span class="subtle">Replies are not guaranteed.</span></div></form>${state.community351.reportStatus?`<p class="notice" role="status">${esc(state.community351.reportStatus)}</p>`:''}</div></section>`}

function kumaHistory(){const k=state.kuma;const services=visibleKumaServices(k.services);const ids=new Set(services.map(x=>String(x.id)));const incidents=(k.incidents||[]).filter(x=>ids.has(String(x.monitorId)));return `<section class="section"><h3>Service incident history</h3><p class="subtle">${esc(k.archiveNote||'Historical incidents are sampled by scheduled Worker polling when a Cloudflare Cron Trigger is configured. Short outages between polls may be missed.')}</p>${k.archiveAvailable?`<div class="panel"><strong>Recorded outage and recovery events</strong>${incidents.length?incidents.map(e=>`<div class="file-row"><strong>${esc(e.monitorName)}</strong><span class="status-indicator ${statusClass(e.status)}">${e.status===0?'Outage detected':'Recovered'}</span><time>${date(e.time)}</time></div>`).join(''):'<p class="subtle">No outage or recovery events have been recorded yet.</p>'}</div>`:'<div class="panel">D1 incident archive unavailable. Recent public heartbeat history is shown below.</div>'}<h3>Recent heartbeat samples</h3>${services.map(s=>`<div class="panel tavern-post"><strong>${esc(s.name)}</strong><div class="mh-history">${(s.history||[]).map(h=>`<span title="${statusLabel(h.status)}" class="mh-history-dot ${statusClass(h.status)}"></span>`).join('')||'<small>No heartbeat history available</small>'}</div></div>`).join('')||'<div class="panel">No public history available.</div>'}</section>`}
function community351Admin(){const c=state.community351,p=c.poll;return `<details class="panel admin-panel settings-outer"><summary>Movie Night and problem reports</summary><div class="settings-group-body"><h3>Movie Night</h3><p class="subtle">Choose 2–6 movies from Plex search results, set a deadline, then publish.</p><form id="mh-movie-search"><input name="q" minlength="2" placeholder="Search Plex movies" required><button class="btn secondary">Search</button></form>${c.pollSearch.map((m,i)=>`<button class="btn secondary" type="button" data-mh-movie-add="${i}">${esc(m.title)} (${esc(m.year||'')}) +</button>`).join('')}<form id="mh-poll-publish"><label>Vote title<input name="title" maxlength="120" value="Movie Night" required></label><label>Voting deadline<input name="deadline" type="datetime-local" required></label><p>${(c.pollSelection||[]).map(x=>esc(x.title)).join(', ')||'No movies selected'}</p><button class="btn">Publish vote (2–6 movies)</button></form>${p?`<p>Current poll: ${esc(p.title)} <button class="btn secondary" data-mh-poll-close="1">Remove poll</button></p>`:''}<h3>Problem reports</h3>${c.reports.map(r=>`<div class="panel tavern-post"><strong>${esc(r.subject)}</strong><small> ${esc(r.status)} · ${date(r.createdAt)}</small><p class="tavern-body">${esc(r.details)}</p><button class="btn secondary" data-mh-report-resolve="${esc(r.id)}">${r.status==='resolved'?'Reopen':'Resolve'}</button></div>`).join('')||'<p>No reports.</p>'}${c.adminMessage?`<p>${esc(c.adminMessage)}</p>`:''}</div></details>`}
async function loadCommunity351(){try{const d=await dashboardRequest('/api/community351');Object.assign(state.community351,{poll:d.poll||null,votes:d.votes||[],myVote:d.myVote||'',faq:d.faq||[]});if(state.adminLoggedIn){try{const a=await dashboardRequest('/api/admin/community351');state.community351.reports=a.reports||[]}catch{}}}catch(e){console.warn('Community features:',e.message)}render()}
async function postCommunity351(payload,admin=false){return dashboardRequest(admin?'/api/admin/community351':'/api/community351',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)})}
document.addEventListener('submit',async e=>{const id=e.target.id;if(!['mh-report','mh-movie-search','mh-poll-publish'].includes(id))return;e.preventDefault();const form=e.target;try{if(id==='mh-report'){const fd=Object.fromEntries(new FormData(form));if(state.reportContext){fd.area=state.reportContext.widget;fd.details=(fd.details||'')+'\n\n[Attached automatically] Widget: '+state.reportContext.widget+' · App: '+MEDIA_HUB_VERSION+' · Page: Home';}await postCommunity351({action:'report',...fd});state.reportContext=null;state.community351.reportStatus='Your request was received and emailed to Tavern support.';form.reset();}else if(id==='mh-movie-search'){const d=await dashboardRequest('/api/plex/catalog?q='+encodeURIComponent(form.elements.q.value));state.community351.pollSearch=(d.items||[]).filter(x=>x.type==='movie');}else{const opts=state.community351.pollSelection||[];if(opts.length<2||opts.length>6)throw Error('Select 2–6 movies.');await postCommunity351({action:'poll-publish',title:form.elements.title.value,deadline:new Date(form.elements.deadline.value).toISOString(),options:opts},true);state.community351.pollSelection=[];state.community351.pollSearch=[];}await loadCommunity351()}catch(ex){state.community351.adminMessage=ex.message;state.community351.reportStatus=ex.message;render()}});
document.addEventListener('click',async e=>{const vote=e.target.closest('[data-movie-vote]'),add=e.target.closest('[data-mh-movie-add]'),resolve=e.target.closest('[data-mh-report-resolve]'),close=e.target.closest('[data-mh-poll-close]');try{if(vote){await postCommunity351({action:'vote',optionId:vote.dataset.movieVote});await loadCommunity351()}else if(add){const m=state.community351.pollSearch[Number(add.dataset.mhMovieAdd)];const arr=state.community351.pollSelection||[];if(m&&!arr.some(x=>x.machine===m.machine&&x.ratingKey===m.ratingKey)&&arr.length<6)arr.push({id:crypto.randomUUID(),machine:m.machine,ratingKey:m.ratingKey,title:m.title,year:m.year});state.community351.pollSelection=arr;render()}else if(resolve||close){await postCommunity351(resolve?{action:'report-status',id:resolve.dataset.mhReportResolve}:{action:'poll-remove'},true);await loadCommunity351()}}catch(ex){state.community351.adminMessage=ex.message;render()}});
window.addEventListener('DOMContentLoaded',loadCommunity351);
// Recently Added Games is rendered inside the unified Home layout.
function recentGamesWidget(){if(!state.recentGames.length)return '';return `<section class="section"><div class="section-head"><h3>Recently Added Games</h3></div><div class="media-grid tavern-picks">${state.recentGames.slice(0,8).map(g=>`<a class="media-card" href="${esc(g.nextcloudUrl||'#')}" target="_blank" rel="noopener noreferrer"><div class="art">${g.image?`<img src="${esc(g.image)}" alt="" loading="lazy">`:''}<span class="art-title">${esc(g.title||'Game')}</span></div><strong>${esc(g.title||'Game')}</strong></a>`).join('')}</div></section>`;}
function quickLinksWidget(){if(!state.quickLinks.length&&!state.quickLinkGroups.length)return '';return '<section class="section"><div class="section-head"><h3>Quick Links</h3></div><div class="panel quick-link-collection">'+quickLinksMarkup()+'</div></section>';}
async function loadRecentGames(){try{const r=await dashboardRequest('/api/games/recent');state.recentGames=r.items||[];state.recentGamesError='';}catch(e){state.recentGamesError=e.message;}render();}
window.addEventListener('DOMContentLoaded',loadRecentGames);

// Download Centre (v3.6.16): the FTP guide, connection details with copy
// buttons, the recommended app and troubleshooting in one place. Connection
// details match the printed guide exactly. No credentials live in the app —
// members use the shared login they were given.
// Game widgets (v3.6.19): Game of the Week + a curated New Games list.
// Metadata comes from Steam through the existing metadata search; the admin
// sets the external link each game points at (Steam page by default).
async function loadGameWidgets(){try{const[f,p]=await Promise.all([dashboardRequest('/api/games/featured'),dashboardRequest('/api/games/picks')]);state.gameFeatured=f.featured||null;state.gamePicks=p.items||[];if(state.page==='Home')render();}catch(e){console.warn('Game widgets unavailable:',e.message)}}
window.addEventListener('DOMContentLoaded',loadGameWidgets);
function gameWeekWidget(){const f=state.gameFeatured;if(!f)return '';return `<section class="section featured-media game-week"><div class="section-head"><div><div class="eyebrow">FEATURED GAME</div><h3>Game of the Week</h3></div></div><div class="game-week-body">${f.image?`<img class="game-art" src="${esc(f.image)}" alt="${esc(f.title)} artwork" loading="lazy">`:''}<h3>${esc(f.title)}</h3>${f.releaseDate?`<p class="subtle">Released ${esc(f.releaseDate)}</p>`:''}<p>${esc(f.note||f.description||'Featured game of the week')}</p><p><a class="btn" target="_blank" rel="noopener noreferrer" href="${esc(f.link||f.steamUrl)}">Download game ↗</a> <a class="btn secondary" target="_blank" rel="noopener noreferrer" href="${esc(f.steamUrl)}">View on Steam ↗</a></p></div></section>`;}
function newGamesWidget(){const items=state.gamePicks;if(!items.length)return '';return `<section class="section"><div class="section-head"><h3>New Games</h3></div><div class="media-grid tavern-picks">${items.slice(0,12).map(g=>`<a class="media-card" href="${esc(g.link||g.steamUrl||'#')}" target="_blank" rel="noopener noreferrer"><div class="art">${g.image?`<img loading="lazy" src="${esc(g.image)}" alt="">`:''}<span class="art-title">${esc(g.title||'Game')}</span></div><strong>${esc(g.title||'Game')}</strong>${g.releaseDate?`<div class="subtle">${esc(g.releaseDate)}</div>`:''}</a>`).join('')}</div></section>`;}
async function loadGameAdmin(){const a=state.gameAdmin;if(a.loading)return;a.loading=true;try{const[f,p,q,cs]=await Promise.all([dashboardRequest('/api/admin/games/featured'),dashboardRequest('/api/games/picks'),dashboardRequest('/api/games/requests'),dashboardRequest('/api/admin/games/coming-soon')]);state.gameFeaturedAdmin=f.featured||null;state.gamePicks=p.items||[];state.gameRequests=q.items||[];state.gameRequestsLoaded=true;state.comingSoonAdmin={enabled:cs.enabled!==false,items:cs.items||[]};a.loaded=true;}catch(e){a.message='Could not load game widgets: '+e.message;}finally{a.loading=false;if(state.page==='Settings')render();}}
function gameWidgetsAdminPanel(){if(!state.adminLoggedIn)return '';const a=state.gameAdmin,f=state.gameFeaturedAdmin;if(!a.loaded&&!a.loading)Promise.resolve().then(loadGameAdmin);
 const results=a.results.map(g=>`<div class="game-admin-row"><img src="${esc(g.image||'')}" alt="" loading="lazy"><div class="game-admin-main"><strong>${esc(g.title)}</strong><span class="subtle">${esc(g.releaseDate||'Steam')}</span></div><button class="btn secondary" type="button" data-game-gotw="${esc(g.id)}">Game of the Week</button><button class="btn secondary" type="button" data-game-add="${esc(g.id)}">Add to New Games</button><button class="btn secondary" type="button" data-game-cs-add="${esc(g.id)}">Coming Soon</button></div>`).join('');
 const picks=state.gamePicks.map(g=>{const key=g.provider+':'+g.id;return `<div class="layout-item"><strong>${esc(g.title)}</strong><span class="subtle">${esc(g.link||'')}</span><input type="url" data-pick-link-for="${esc(key)}" value="${esc(g.link||'')}" maxlength="500" placeholder="External link (blank = Steam)" aria-label="External link"><button class="btn secondary" type="button" data-game-pick-link="${esc(key)}">Set link</button><button class="btn secondary" type="button" data-game-remove="${esc(key)}">Remove</button></div>`}).join('');
 const csA=state.comingSoonAdmin;
 const csRows=csA?csA.items.map(g=>{const key=g.provider+':'+g.id;return `<div class="layout-item"><strong>${esc(g.title)}</strong><span class="subtle">${esc(g.releaseDate||'')}</span><input type="url" data-cs-link-for="${esc(key)}" value="${esc(g.link||'')}" maxlength="500" placeholder="External link (blank = Steam)" aria-label="External link"><button class="btn secondary" type="button" data-game-cs-link="${esc(key)}">Set link</button><button class="btn secondary" type="button" data-game-cs-remove="${esc(key)}">Remove</button></div>`}).join(''):'';
 const openCount=state.gameRequests.filter(r=>r.status==='pending').length;
 return `<details class="panel admin-panel settings-outer"><summary>Game of the Week &amp; New Games</summary><div class="settings-group-body"><h3>Game of the Week</h3>${f?`<p><strong>${esc(f.title)}</strong> ${f.enabled?'· showing on Home':'· hidden'}<br><span class="subtle">Links to ${esc(f.link||f.steamUrl)}</span></p><p><button class="btn secondary" type="button" data-game-gotw-toggle="${f.enabled?'0':'1'}">${f.enabled?'Hide':'Show'}</button> <button class="btn secondary" type="button" data-game-gotw-clear="1">Clear</button></p>`:'<p class="subtle">Nothing featured right now. Search Steam below and choose “Game of the Week” on a result.</p>'}<label>External link for Game of the Week (optional — Steam page if blank)<input id="game-gotw-link" type="url" maxlength="500" placeholder="https://…"></label><label>Note (optional)<input id="game-gotw-note" maxlength="300" placeholder="Why this one?"></label><h3>New Games</h3><label>External link for the next game added (optional — Steam page if blank)<input id="game-pick-link" type="url" maxlength="500" placeholder="https://…"></label>${picks||'<p class="subtle">No games in the list yet.</p>'}<h3>Coming Soon (Games page)</h3>${csA?`<p><span class="subtle">${csA.enabled?'Showing on the Games page':'Hidden from the Games page'}</span> <button class="btn secondary" type="button" data-game-cs-toggle="${csA.enabled?'0':'1'}">${csA.enabled?'Hide section':'Show section'}</button></p>${csRows||'<p class="subtle">Nothing being watched yet. Search Steam below and choose “Coming Soon” on a result.</p>'}`:'<p class="subtle">Loading…</p>'}<h3>Requests (games, movies, TV)</h3><p class="subtle">${openCount?openCount+' pending request'+(openCount===1?'':'s')+' on the board.':'No pending requests.'} Requests are worked on the Requests page — signed in as admin, every request there carries its action buttons.</p><p><button class="btn secondary" type="button" data-page="Requests">Open the Requests page</button></p><h3>Search Steam</h3><form id="game-admin-search"><label>Title<input name="q" minlength="2" required placeholder="e.g. Elden Ring"></label><button class="btn" type="submit">Search Steam</button></form>${results}${a.message?`<p class="notice" role="status">${esc(a.message)}</p>`:''}</div></details>`;}
document.addEventListener('submit',async e=>{if(e.target.id!=='game-admin-search')return;e.preventDefault();const a=state.gameAdmin;const q=e.target.elements.q.value.trim();try{const d=await dashboardRequest('/api/metadata/search?kind=game&provider=steam&q='+encodeURIComponent(q));a.results=d.results||[];a.message=a.results.length?'':'No Steam matches for “'+q+'”.';}catch(err){a.message='Steam search failed: '+err.message;}render();});
document.addEventListener('click',async e=>{
 const gw=e.target.closest('[data-game-gotw]'),add=e.target.closest('[data-game-add]'),rem=e.target.closest('[data-game-remove]'),tog=e.target.closest('[data-game-gotw-toggle]'),clr=e.target.closest('[data-game-gotw-clear]'),csAdd=e.target.closest('[data-game-cs-add]'),csRem=e.target.closest('[data-game-cs-remove]'),csTog=e.target.closest('[data-game-cs-toggle]'),csLink=e.target.closest('[data-game-cs-link]'),pickLink=e.target.closest('[data-game-pick-link]');
 if(!gw&&!add&&!rem&&!tog&&!clr&&!csAdd&&!csRem&&!csTog&&!csLink&&!pickLink)return;const a=state.gameAdmin;
 try{
  if(gw){const link=document.getElementById('game-gotw-link')?.value||'';const note=document.getElementById('game-gotw-note')?.value||'';const d=await dashboardRequest('/api/admin/games/featured',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'publish',providerId:gw.dataset.gameGotw,link,note})});state.gameFeaturedAdmin=d.featured;state.gameFeatured=d.featured;a.message='Game of the Week published.';}
  if(add){const link=document.getElementById('game-pick-link')?.value||'';await dashboardRequest('/api/admin/games/picks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'add',providerId:add.dataset.gameAdd,link})});const p=await dashboardRequest('/api/games/picks');state.gamePicks=p.items||[];a.message='Added to New Games.';}
  if(rem){await dashboardRequest('/api/admin/games/picks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'remove',id:rem.dataset.gameRemove})});const p=await dashboardRequest('/api/games/picks');state.gamePicks=p.items||[];a.message='Removed from New Games.';}
  if(tog){await dashboardRequest('/api/admin/games/featured',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'toggle',enabled:tog.dataset.gameGotwToggle==='1'})});await loadGameWidgets();if(state.gameFeaturedAdmin)state.gameFeaturedAdmin.enabled=tog.dataset.gameGotwToggle==='1';a.message='Game of the Week updated.';}
  if(csAdd){await dashboardRequest('/api/admin/games/coming-soon',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'add',providerId:csAdd.dataset.gameCsAdd})});state.comingSoon.loaded=false;await loadGameAdmin();a.message='Added to Coming Soon.';}
  if(csRem){await dashboardRequest('/api/admin/games/coming-soon',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'remove',id:csRem.dataset.gameCsRemove})});state.comingSoon.loaded=false;await loadGameAdmin();a.message='Removed from Coming Soon.';}
  if(csTog){await dashboardRequest('/api/admin/games/coming-soon',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'toggle',enabled:csTog.dataset.gameCsToggle==='1'})});state.comingSoon.loaded=false;await loadGameAdmin();a.message='Coming Soon section '+(csTog.dataset.gameCsToggle==='1'?'shown.':'hidden.');}
  if(csLink){const key=csLink.dataset.gameCsLink;const input=document.querySelector('[data-cs-link-for="'+CSS.escape(key)+'"]');await dashboardRequest('/api/admin/games/coming-soon',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'link',id:key,link:input?.value||''})});state.comingSoon.loaded=false;await loadGameAdmin();a.message='Coming Soon link updated.';}
  if(pickLink){const key=pickLink.dataset.gamePickLink;const input=document.querySelector('[data-pick-link-for="'+CSS.escape(key)+'"]');await dashboardRequest('/api/admin/games/picks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'link',id:key,link:input?.value||''})});const p=await dashboardRequest('/api/games/picks');state.gamePicks=p.items||[];a.message='New Games link updated.';}
  if(clr){if(!confirm('Clear Game of the Week?'))return;await dashboardRequest('/api/admin/games/featured',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'clear'})});state.gameFeaturedAdmin=null;state.gameFeatured=null;a.message='Game of the Week cleared.';}
 }catch(err){a.message=err.message;}
 render();
});

// Games page and game requests (v3.6.20): the Games page gathers the two
// Home game widgets, Recently Added Games, Coming Soon and the requests
// board. Admin request actions compose the Steam search with the existing
// picks/featured endpoints, then mark the request added.
async function loadGameRequests(){if(state.gameRequestsLoading)return;state.gameRequestsLoading=true;try{const d=await dashboardRequest('/api/games/requests');state.gameRequests=d.items||[];state.gameRequestsLoaded=true;}catch(e){console.warn('Game requests unavailable:',e.message)}finally{state.gameRequestsLoading=false;if(state.page==='Games'||state.page==='Settings'||state.page==='Requests')render();}}
window.addEventListener('DOMContentLoaded',loadGameRequests);
async function loadComingGames(){const c=state.comingSoon;if(c.loading)return;c.loading=true;try{const d=await dashboardRequest('/api/games/coming-soon');c.items=d.items||[];c.enabled=d.enabled!==false;}catch(e){console.warn('Coming Soon unavailable:',e.message)}finally{c.loaded=true;c.loading=false;if(state.page==='Games')render();}}
function gamesPage(){
 if(!state.comingSoon.loaded&&!state.comingSoon.loading)Promise.resolve().then(loadComingGames);
 if(!state.gameRequestsLoaded&&!state.gameRequestsLoading)Promise.resolve().then(loadGameRequests);
 const cs=state.comingSoon;
 const soon=cs.enabled&&cs.items.length?`<section class="section"><div class="section-head"><h3>Coming Soon</h3></div><div class="media-grid tavern-picks">${cs.items.slice(0,12).map(g=>`<a class="media-card" href="${esc(g.link||g.steamUrl||'#')}" target="_blank" rel="noopener noreferrer"><div class="art">${g.image?`<img loading="lazy" src="${esc(g.image)}" alt="">`:''}<span class="art-title">${esc(g.title||'Game')}</span></div><strong>${esc(g.title||'Game')}</strong>${g.releaseDate?`<div class="subtle">${esc(g.releaseDate)}</div>`:''}</a>`).join('')}</div></section>`:'';
 return `${gameWeekWidget()}${newGamesWidget()}${tavernEnabled('games')?recentGamesWidget():''}${soon}${gameRequestsBoard()}`;
}
function requestKindLabel(k){return k==='movie'?'Movie':k==='show'?'TV Show':k==='program'?'Program':'Game';}
function requestAdminActions(r){const k=r.kind||'game';const id=esc(r.id);const mark=(st,label)=>`<button class="btn secondary" type="button" data-game-req-mark="${st}" data-req-id="${id}">${label}</button>`;const del=`<button class="btn secondary" type="button" data-game-req-delete="${id}">Delete</button>`;if(r.status==='pending'){const quick=k==='program'?'':k==='game'?`<button class="btn secondary" type="button" data-game-req-add="${id}">Add to New Games</button><button class="btn secondary" type="button" data-game-req-feature="${id}">Game of the Week</button>`:`<button class="btn secondary" type="button" data-game-req-featureit="${id}">Feature it (${k==='movie'?'Movie':'Show'} of the Week)</button>`;return quick+mark('fulfilled','✓ Mark fulfilled')+mark('denied','✗ Mark denied')+del;}return mark('pending','↩ Mark pending')+(r.status==='fulfilled'?mark('denied','✗ Mark denied'):mark('fulfilled','✓ Mark fulfilled'))+del;}
function requestRows(items,admin=false){return items.map(r=>`<div class="layout-item"><strong>${esc(r.title)}${r.year?' ('+esc(r.year)+')':''}</strong><span class="tag ${r.status==='fulfilled'?'tag-ok':r.status==='denied'?'tag-no':'tag-wait'}">${r.status==='fulfilled'?'Fulfilled ✓':r.status==='denied'?'Denied':'Pending'}</span><span class="subtle">asked by ${esc(r.requester||'A member')}${r.note?' · '+esc(r.note):''}</span>${admin?requestAdminActions(r):''}</div>`).join('');}
function gameRequestsBoard(){
 const rows=requestRows(state.gameRequests.filter(r=>(r.kind||'game')==='game'));
 return `<section class="section"><div class="section-head"><h3>Request a Game</h3></div><div class="panel"><p class="subtle">Want a game on the server? Ask for it here — when it is added, it shows up in New Games above. Movies and shows can be requested on the Requests page.</p><form id="game-request-form"><input type="hidden" name="kind" value="game"><label>Game title<input name="title" minlength="2" maxlength="120" required placeholder="e.g. Balatro"></label><label>Your name<input name="requester" maxlength="40" placeholder="So we know who asked" value="${esc(state.plexUser?.name||'')}"></label><label>Note (optional)<input name="note" maxlength="200" placeholder="Anything to add?"></label><button class="btn" type="submit">Send request</button></form>${state.gameRequestMessage?`<p class="notice" role="status">${esc(state.gameRequestMessage)}</p>`:''}</div>${rows?`<div class="panel"><h3>On the board</h3>${rows}</div>`:''}</section>`;
}

// ---- Roadmap page (v3.6.34) ----
// A vertical timeline of shipped milestones and what is planned, stored
// server-side (mh_roadmap) so the admin can edit it without a redeploy.
// Members just read it; the editor renders only for the admin session.
async function loadRoadmap(){if(state.roadmap.loading)return;state.roadmap.loading=true;try{const d=await dashboardRequest('/api/roadmap');state.roadmap.items=d.items||[];state.roadmap.loaded=true;}catch(e){console.warn('Roadmap unavailable:',e.message)}finally{state.roadmap.loading=false;if(state.page==='Roadmap')render();}}
async function roadmapSave(msg){try{const d=await dashboardRequest('/api/admin/roadmap',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({items:state.roadmap.items})});state.roadmap.items=d.items||state.roadmap.items;state.roadmap.msg=msg;}catch(e){state.roadmap.msg='Could not save: '+e.message;}render();}
function roadmapPage(){
 if(!state.roadmap.loaded&&!state.roadmap.loading)Promise.resolve().then(loadRoadmap);
 const items=state.roadmap.items;
 const chip=s=>s==='shipped'?'<span class="tag tag-ok">Shipped</span>':s==='progress'?'<span class="tag tag-wait">In progress</span>':'<span class="tag">Planned</span>';
 const timeline=items.length?`<div class="roadmap">${items.map(r=>`<div class="roadmap-item ${esc(r.status||'planned')}"><span class="roadmap-dot"></span><div class="roadmap-body"><div class="roadmap-head"><strong>${esc(r.title)}</strong>${chip(r.status)}${r.date?`<span class="subtle">${esc(r.date)}</span>`:''}</div>${r.body?`<p>${esc(r.body)}</p>`:''}</div></div>`).join('')}</div>`:'<p class="subtle">Nothing on the roadmap yet.</p>';
 let admin='';
 if(state.adminLoggedIn){
  const rows=items.map((r,i)=>`<div class="layout-item"><strong>${esc(r.title)}</strong><span class="subtle">${esc(r.date||'')}</span><select data-roadmap-status="${i}"><option value="planned" ${r.status==='planned'?'selected':''}>Planned</option><option value="progress" ${r.status==='progress'?'selected':''}>In progress</option><option value="shipped" ${r.status==='shipped'?'selected':''}>Shipped</option></select><button class="btn secondary" type="button" data-roadmap-up="${i}">↑</button><button class="btn secondary" type="button" data-roadmap-down="${i}">↓</button><button class="btn secondary" type="button" data-roadmap-del="${i}">Delete</button></div>`).join('');
  admin=`<div class="panel"><h3>Edit the roadmap</h3><p class="subtle">Changes save immediately and show for everyone. New items land at the top; use the arrows to order the list.</p>${state.roadmap.msg?`<p class="notice" role="status">${esc(state.roadmap.msg)}</p>`:''}<form id="roadmap-add-form"><label>Title<input name="title" required minlength="2" maxlength="120" placeholder="What is coming?"></label><label>When / version<input name="date" maxlength="40" placeholder="Planned, In progress, v3.7, Nov 2026…"></label><label>Status<select name="status"><option value="planned">Planned</option><option value="progress">In progress</option><option value="shipped">Shipped</option></select></label><label>Details<input name="body" maxlength="400" placeholder="A sentence or two"></label><button class="btn" type="submit">Add to the top</button></form>${rows}</div>`;
 }
 return `<section class="section"><div class="section-head"><h3>Roadmap</h3></div>${admin}<div class="panel"><p class="subtle">Where this hub has been — and where it is going.</p>${timeline}</div></section>`;
}
document.addEventListener('submit',async e=>{if(e.target.id!=='roadmap-add-form')return;e.preventDefault();const fd=new FormData(e.target);const item={title:String(fd.get('title')||'').trim(),date:String(fd.get('date')||'').trim(),body:String(fd.get('body')||'').trim(),status:String(fd.get('status')||'planned')};if(item.title.length<2)return;state.roadmap.items=[item,...state.roadmap.items];await roadmapSave('Roadmap item added.');});
document.addEventListener('change',async e=>{const sel=e.target.closest('[data-roadmap-status]');if(!sel)return;const i=Number(sel.dataset.roadmapStatus);if(state.roadmap.items[i]){state.roadmap.items[i].status=sel.value;await roadmapSave('Roadmap updated.');}});
document.addEventListener('click',async e=>{const up=e.target.closest('[data-roadmap-up]'),down=e.target.closest('[data-roadmap-down]'),del=e.target.closest('[data-roadmap-del]');if(!up&&!down&&!del)return;const items=state.roadmap.items;const swap=(a,b)=>{const t=items[a];items[a]=items[b];items[b]=t;};
 if(up){const i=Number(up.dataset.roadmapUp);if(i>0){swap(i,i-1);await roadmapSave('Roadmap reordered.');}}
 else if(down){const i=Number(down.dataset.roadmapDown);if(i<items.length-1){swap(i,i+1);await roadmapSave('Roadmap reordered.');}}
 else if(del){const i=Number(del.dataset.roadmapDel);if(confirm('Remove this roadmap item?')){items.splice(i,1);await roadmapSave('Roadmap item removed.');}}});

document.addEventListener('input',e=>{if(e.target.id!=='brand-icon-search')return;const q=e.target.value.trim().toLowerCase();document.querySelectorAll('[data-icon-tile]').forEach(t=>{t.style.display=!q||t.dataset.iconTile.includes(q)?'':'none';});});
function requestsPage(){
 if(!state.gameRequestsLoaded&&!state.gameRequestsLoading)Promise.resolve().then(loadGameRequests);
 const groups=[['movie','Movies'],['show','TV Shows'],['game','Games'],['program','Programs']].map(([k,label])=>{const items=state.gameRequests.filter(r=>(r.kind||'game')===k);return items.length?`<div class="panel"><h3>${label}</h3>${requestRows(items,state.adminLoggedIn)}</div>`:''}).join('');
 return `<section class="section"><div class="section-head"><h3>Request Something</h3></div><div class="panel"><p class="subtle">Ask for a movie, a TV show, a game, or a program. When it is fulfilled, your request shows Fulfilled here — games also land in New Games on the Games page.</p><form id="game-request-form"><label>What kind?<select name="kind"><option value="movie">Movie</option><option value="show">TV Show</option><option value="game">Game</option><option value="program">Program</option></select></label><label>Title<span class="suggest-wrap"><input name="title" minlength="2" maxlength="120" required placeholder="Start typing a title…" autocomplete="off"><span class="suggest-list" data-suggest hidden></span></span></label><input type="hidden" name="year"><input type="hidden" name="imdbId"><label>Your name<input name="requester" maxlength="40" placeholder="So we know who asked" value="${esc(state.plexUser?.name||'')}"></label><label>Note (optional)<input name="note" maxlength="200" placeholder="Anything to add?"></label><button class="btn" type="submit">Send request</button></form>${state.gameRequestMessage?`<p class="notice" role="status">${esc(state.gameRequestMessage)}</p>`:''}</div>${state.adminLoggedIn?`<div class="panel"><p class="subtle">You are signed in as admin — every request below carries its buttons: add it, feature it, mark it fulfilled, denied or pending, or delete it.</p>${state.gameAdmin.message?`<p class="notice" role="status">${esc(state.gameAdmin.message)}</p>`:''}</div>`:''}${groups||'<p class="subtle">Nothing on the board yet — be the first to ask.</p>'}</section>`;
}
// IMDb title suggestions for the movie/TV request form (v3.6.26): as the
// member types, the Worker proxies IMDb's suggestion endpoint; picking a
// result fills the title and carries its year + IMDb id on the request, so
// the board shows "Title (Year)" and Feature-it can prefer the right remake.
// Games keep the plain field. Everything degrades silently — no suggestions
// never blocks a request.
let reqSuggestTimer=0,reqSuggestItems=[],reqSuggestIdx=-1,reqSuggestPicked='';
function reqSuggestBox(form){return form?.querySelector('[data-suggest]');}
function reqSuggestHide(form){const box=reqSuggestBox(form);if(box){box.hidden=true;box.innerHTML='';}reqSuggestItems=[];reqSuggestIdx=-1;}
function reqSuggestPick(form,item){const title=form.elements.title;title.value=item.title;form.elements.year.value=item.year||'';form.elements.imdbId.value=item.imdbId||'';reqSuggestPicked=item.title;reqSuggestHide(form);title.focus();}
document.addEventListener('input',e=>{
 const input=e.target;if(input.name!=='title')return;const form=input.closest('#game-request-form');if(!form)return;
 const kind=form.elements.kind?.value||'game';if(kind==='game'||kind==='program'){reqSuggestHide(form);return;}
 if(input.value!==reqSuggestPicked){form.elements.year.value='';form.elements.imdbId.value='';}
 const q=input.value.trim();clearTimeout(reqSuggestTimer);
 if(q.length<2){reqSuggestHide(form);return;}
 reqSuggestTimer=setTimeout(async()=>{try{const d=await dashboardRequest('/api/requests/suggest?kind='+kind+'&q='+encodeURIComponent(q));reqSuggestItems=d.items||[];reqSuggestIdx=-1;const box=reqSuggestBox(form);if(!box)return;
  if(!reqSuggestItems.length){reqSuggestHide(form);return;}
  box.innerHTML=reqSuggestItems.map((it,i)=>`<button type="button" class="suggest-item" data-suggest-idx="${i}">${it.image?`<img src="${esc(it.image)}" alt="" loading="lazy">`:''}<span><strong>${esc(it.title)}</strong><span class="subtle">${esc(it.year||'')}${it.year?' · ':''}${kind==='movie'?'Movie':'TV Show'}</span></span></button>`).join('');box.hidden=false;}catch{reqSuggestHide(form);}},250);
});
document.addEventListener('keydown',e=>{
 const input=e.target;if(input.name!=='title')return;const form=input.closest('#game-request-form');if(!form)return;const box=reqSuggestBox(form);if(!box||box.hidden||!reqSuggestItems.length)return;
 if(e.key==='Escape'){reqSuggestHide(form);return;}
 if(e.key!=='ArrowDown'&&e.key!=='ArrowUp'&&e.key!=='Enter')return;
 if(e.key==='Enter'){if(reqSuggestIdx>=0&&reqSuggestItems[reqSuggestIdx]){e.preventDefault();reqSuggestPick(form,reqSuggestItems[reqSuggestIdx]);}return;}
 e.preventDefault();reqSuggestIdx=(reqSuggestIdx+(e.key==='ArrowDown'?1:-1)+reqSuggestItems.length)%reqSuggestItems.length;
 box.querySelectorAll('.suggest-item').forEach((el,i)=>el.classList.toggle('active',i===reqSuggestIdx));
});
document.addEventListener('click',e=>{
 const item=e.target.closest('[data-suggest-idx]');if(item){const form=item.closest('#game-request-form');const picked=reqSuggestItems[Number(item.dataset.suggestIdx)];if(form&&picked)reqSuggestPick(form,picked);return;}
 if(!e.target.closest('#game-request-form'))document.querySelectorAll('[data-suggest]').forEach(b=>{b.hidden=true;});
});
document.addEventListener('change',e=>{
 if(e.target.name!=='kind')return;const form=e.target.closest('#game-request-form');if(!form)return;
 form.elements.year.value='';form.elements.imdbId.value='';reqSuggestPicked='';reqSuggestHide(form);
});
document.addEventListener('submit',async e=>{if(e.target.id!=='game-request-form')return;e.preventDefault();const fd=new FormData(e.target);try{await dashboardRequest('/api/games/requests',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind:fd.get('kind')||'game',title:fd.get('title'),requester:fd.get('requester'),note:fd.get('note'),year:fd.get('year')||'',imdbId:fd.get('imdbId')||''})});state.gameRequestMessage='Request sent — it is on the board below.';state.gameRequestsLoaded=false;await loadGameRequests();}catch(err){state.gameRequestMessage=err.message;}render();});
document.addEventListener('click',async e=>{
 const add=e.target.closest('[data-game-req-add]'),feat=e.target.closest('[data-game-req-feature]'),fit=e.target.closest('[data-game-req-featureit]'),mark=e.target.closest('[data-game-req-mark]'),del=e.target.closest('[data-game-req-delete]');
 if(!add&&!feat&&!fit&&!mark&&!del)return;const a=state.gameAdmin;
 const setStatus=async(id,status)=>dashboardRequest('/api/admin/games/requests',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'status',id,status})});
 try{
  if(mark){await setStatus(mark.dataset.reqId,mark.dataset.gameReqMark);a.message='Request marked '+mark.dataset.gameReqMark+'.';}
  if(del){if(!confirm('Delete this request permanently?'))return;await dashboardRequest('/api/admin/games/requests',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'delete',id:del.dataset.gameReqDelete})});state.gameRequestsLoaded=false;a.message='Request deleted.';}

  if(fit){const reqItem=state.gameRequests.find(r=>r.id===fit.dataset.gameReqFeatureit);if(!reqItem)throw Error('Request not found');const kind=reqItem.kind||'game';const d=await dashboardRequest('/api/plex/catalog?kind='+kind+'&q='+encodeURIComponent(reqItem.title));const typed=(d.items||[]).filter(m=>m.type===kind);const match=typed.find(m=>reqItem.year&&String(m.year)===String(reqItem.year))||typed[0];if(!match)throw Error('No Plex match for "'+reqItem.title+'" — it may not be in the library yet.');await dashboardRequest('/api/plex/featured?kind='+kind,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'publish',machine:match.machine,ratingKey:match.ratingKey,note:''})});await setStatus(reqItem.id,'fulfilled');a.message='Matched Plex: '+match.title+' — featured as '+(kind==='movie'?'Movie':'Show')+' of the Week.';}
  if(add||feat){const btn=add||feat;const reqItem=state.gameRequests.find(r=>r.id===btn.dataset[add?'gameReqAdd':'gameReqFeature']);if(!reqItem)throw Error('Request not found');const d=await dashboardRequest('/api/metadata/search?kind=game&provider=steam&q='+encodeURIComponent(reqItem.title));const match=(d.results||[])[0];if(!match)throw Error('No Steam match for "'+reqItem.title+'" — search manually below.');if(add){await dashboardRequest('/api/admin/games/picks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'add',providerId:match.id,link:''})});}else{const f=await dashboardRequest('/api/admin/games/featured',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'publish',providerId:match.id,link:'',note:''})});state.gameFeaturedAdmin=f.featured;state.gameFeatured=f.featured;}await setStatus(reqItem.id,'fulfilled');a.message='Matched Steam: '+match.title+' — request marked fulfilled.';}
 }catch(err){a.message=err.message;}
 state.gameRequestsLoaded=false;await loadGameRequests();const p=await dashboardRequest('/api/games/picks').catch(()=>null);if(p)state.gamePicks=p.items||[];
 render();
});

