function downloadsPage(){
 const row=(label,value,note)=>`<div class="dl-row"><div><strong>${esc(label)}</strong><div class="subtle">${esc(note)}</div></div><code class="dl-value">${esc(value)}</code><button class="btn secondary" type="button" data-copy="${esc(value)}">Copy</button></div>`;
 return `<section class="section"><div class="section-head"><div><div class="eyebrow">GET FILES</div><h2>Download Centre</h2><p class="subtle">Everything needed to pull files from Shared Files onto your own device — the guide, the connection details, the right app, and fixes for the common snags.</p></div></div>
 <div class="panel"><div class="section-head"><h3>Connection details</h3></div>
 ${row('Server','your-server.example.com','The address your FTP app connects to')}
 ${row('Port','21','The standard explicit FTPS port — use the port your host gave you if it differs')}
 ${row('Protocol','FTP-SSL (Explicit AUTH TLS)','Choose this in the connection dialog')}
 <p class="subtle">Username and password: use the shared login you were given. They are never stored in ScreenDen.</p></div>
 <div class="panel"><div class="section-head"><h3>The step-by-step guide</h3></div><p class="subtle">Illustrated instructions: installing the app, connecting for the first time, the certificate popup, the big-file speed-up, and where finished files land.</p><div class="dl-actions"><a class="btn" href="/ftp-guide">Open the guide →</a></div></div>
 <div class="panel"><div class="section-head"><h3>Recommended app</h3></div><div class="dl-row"><div><strong>Cyberduck</strong><div class="subtle">Free, for Windows and Mac. The guide is written for it, including the segmented-download setting that makes large files reliable.</div></div><a class="btn secondary" href="https://cyberduck.io/" target="_blank" rel="noopener noreferrer">Get Cyberduck ↗</a></div><p class="subtle">Any FTP client that supports explicit FTP over TLS can work, but help here assumes Cyberduck.</p></div>
 <div class="panel"><div class="section-head"><h3>Troubleshooting</h3></div>
 <div class="dl-faq"><strong>Login failed (error 530)</strong><p class="subtle">Re-check the username and password, and confirm the protocol is FTP-SSL (Explicit AUTH TLS) and the port your host gave you. <a href="/ftp-guide#guide-step-3">Guide: connecting for the first time →</a></p></div>
 <div class="dl-faq"><strong>A certificate popup appears</strong><p class="subtle">That is expected on this server — click Continue. <a href="/ftp-guide#guide-step-4">Guide: the scary popup →</a></p></div>
 <div class="dl-faq"><strong>Downloads are slow, or stall on big files</strong><p class="subtle">Turn on segmented downloads once, and let the Transfers window finish before closing Cyberduck. <a href="/ftp-guide#guide-step-6">Guide: the big-file speed-up →</a></p></div>
 <div class="dl-faq"><strong>The file is not in the folder</strong><p class="subtle">Refresh the folder in Cyberduck. If it is still missing it may not have been added yet — ask the person who shared it. More help: <a href="/ftp-guide#guide-step-10">Guide: something went wrong →</a></p></div>
 <p class="subtle">Still stuck? <button class="btn secondary" type="button" data-page="Report a Problem">Report a Problem</button> and include the exact error wording you saw.</p></div>
 </section>`;
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy]');if(!b)return;const v=b.dataset.copy;let ok=false;try{await navigator.clipboard.writeText(v);ok=true;}catch{const t=document.createElement('textarea');t.value=v;document.body.appendChild(t);t.select();try{ok=document.execCommand('copy')}catch{}t.remove();}const old=b.textContent;b.textContent=ok?'Copied ✓':'Copy failed';setTimeout(()=>{b.textContent=old;},1500);});

