function settings(){const template=document.createElement('template');template.innerHTML=settingsContent();const entries=[];const roots=[...template.content.querySelectorAll('details.settings-outer,details.settings-group')].filter(el=>!el.parentElement?.closest('details.settings-outer,details.settings-group'));const seen={};for(const el of roots){const summary=el.querySelector('summary'),title=(summary?.textContent||'Settings').replace(/⌄/g,'').trim();let id='settings-'+title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/-$/,'');seen[id]=(seen[id]||0)+1;if(seen[id]>1)id+='-'+seen[id];el.id=id;el.dataset.settingsSection=id;el.classList.add('settings-destination');if(Object.hasOwn(state.settingsNav.open,id))el.open=state.settingsNav.open[id];else el.open=false;entries.push({id,title});}const connections=template.content.querySelector('.two-col');if(connections){connections.id='settings-connections';connections.classList.add('settings-destination');entries.splice(1,0,{id:'settings-connections',title:'Connections & Shared Files'});}const q=state.settingsNav.filter.toLowerCase();return `<div class="settings-workspace"><aside class="settings-index" aria-label="Settings navigation"><div class="settings-index-heading"><span class="eyebrow">SETTINGS</span><h2>Find your way</h2><p class="subtle">Jump to a section.</p></div><label class="settings-filter-label">Find a setting<input type="search" id="settings-section-filter" placeholder="Nextcloud, layout, links…" value="${esc(state.settingsNav.filter)}"></label><nav class="settings-index-links" aria-label="Settings sections">${entries.map(x=>`<button type="button" data-settings-jump="${esc(x.id)}" ${x.title.toLowerCase().includes(q)?'':'hidden'} ${state.settingsNav.active===x.id?'aria-current="location"':''}>${esc(x.title.replace(' · ',' — '))}</button>`).join('')}</nav><p class="subtle settings-no-match" ${entries.some(x=>x.title.toLowerCase().includes(q))?'hidden':''}>No matching sections.</p><button class="btn secondary settings-collapse" data-settings-collapse="1">Collapse all sections</button></aside><div class="settings-content">${template.innerHTML}</div><button class="btn secondary settings-back-to-index" data-settings-top="1">Sections ↑</button></div>`;}
function settingsJump(id){const el=document.getElementById(id);if(!el)return;if(el.tagName==='DETAILS'){el.open=true;state.settingsNav.open[id]=true;}state.settingsNav.active=id;document.querySelectorAll('[data-settings-jump]').forEach(x=>{if(x.dataset.settingsJump===id)x.setAttribute('aria-current','location');else x.removeAttribute('aria-current')});el.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});const focus=el.querySelector('summary,h3');if(focus){if(focus.tagName!=='SUMMARY')focus.setAttribute('tabindex','-1');focus.focus({preventScroll:true});}}
document.addEventListener('click',e=>{if(e.target.closest('[data-settings-top]')){document.querySelector('.settings-index')?.scrollIntoView({block:'start'});document.getElementById('settings-section-filter')?.focus({preventScroll:true});}const jump=e.target.closest('[data-settings-jump]'),find=e.target.closest('[data-settings-find]');if(jump)settingsJump(jump.dataset.settingsJump);if(find){const target=[...document.querySelectorAll('[data-settings-section]')].find(x=>x.querySelector('summary')?.textContent.includes(find.dataset.settingsFind));if(target)settingsJump(target.id);}if(e.target.closest('[data-settings-collapse]')){document.querySelectorAll('[data-settings-section]').forEach(x=>{x.open=false;state.settingsNav.open[x.id]=false;});}});
document.addEventListener('toggle',e=>{if(e.target.dataset?.settingsSection)state.settingsNav.open[e.target.id]=e.target.open;},true);
document.addEventListener('input',e=>{if(e.target.id!=='settings-section-filter')return;state.settingsNav.filter=e.target.value;const q=e.target.value.toLowerCase();let matches=0;document.querySelectorAll('[data-settings-jump]').forEach(x=>{x.hidden=!x.textContent.toLowerCase().includes(q);if(!x.hidden)matches++});const empty=document.querySelector('.settings-no-match');if(empty)empty.hidden=!!matches;});

