document.addEventListener('click',e=>{if(!e.target.closest('[data-news-recover-last]'))return;const form=document.getElementById('tavern-news-form');if(!form||state.newsPublishing)return;try{const saved=JSON.parse(localStorage.getItem('mh_tavern_news_recovery_v1')||'[]')[0];if(!saved)throw Error('No submitted recovery copy is available yet.');for(const k of ['id','title','body','category'])form.elements[k].value=saved[k]||'';newsCapture(form);state.newsCompose.clientId=saved.clientId||crypto.randomUUID();newsDraftSave(form);newsPreview(form);document.getElementById('mh-news-feedback').textContent='Last submitted article recovered. Review it before publishing.';}catch(e){document.getElementById('mh-news-feedback').textContent=e.message;}});
