function recoverNewsSubmissionUrl(){const params=new URLSearchParams(location.search);if(!params.has('title')||!params.has('body')||!params.get('body'))return;const recovered={id:'',title:params.get('title')||'',body:params.get('body')||'',category:params.get('category')||'announcement',clientId:crypto.randomUUID()};newsArchive(recovered);state.newsCompose=recovered;try{localStorage.setItem(NEWS_DRAFT_KEY,JSON.stringify({...recovered,savedAt:new Date().toISOString()}));for(const k of ['title','body','category','id'])params.delete(k);history.replaceState(null,'',location.pathname+(params.size?'?'+params.toString():'')+location.hash);}catch{}state.page='Tavern News';state.newsSkipCapture=true;state.tavern.message='Recovered an article from a failed submission URL. Review the draft before publishing.';render();}
