// ---- Notifications page + Web Push client (v3.6.28) ----
// The inbox lives under /api/plex/* because the Plex session cookie is scoped
// to that path (see the cookie lesson) — the admin cookie is Path=/ so admin
// identity works there too. Preferences and push controls live on this page
// (not in Settings) so members can reach them.
const NOTIF_ICONS={request:'✉',requests_admin:'✉',reports:'⚠',server:'●',featured:'★',news:'✦','movie-night':'🎬'};
const notifPost=(path,body)=>dashboardRequest(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body||{})});
async function loadNotifications(rerender=true){
 if(state.notif.loading)return;state.notif.loading=true;
 try{const d=await dashboardRequest('/api/plex/notifications');state.notif.items=d.items||[];state.notif.unread=d.unread||0;}
 catch{state.notif.items=[];state.notif.unread=0;}
 state.notif.loading=false;
 if(rerender&&state.page==='Notifications')render();
 else{const b=document.querySelector('.notif-badge');if(b){b.textContent=state.notif.unread>99?'99+':state.notif.unread;b.style.display=state.notif.unread?'':'none';}}
}
async function loadNotifPrefs(){
 try{state.notif.prefs=await dashboardRequest('/api/plex/notifications/prefs');}catch{state.notif.prefs=null;}
 if(state.page==='Notifications')render();
}
function notifTime(ts){const d=new Date(ts);return d.toLocaleDateString(undefined,{month:'short',day:'numeric'})+' · '+d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});}
function mhGo(p){state.page=p;state.mobileMenu=false;window.scrollTo({top:0});render();}
function notificationsPage(){
 if(!state.notif.loadedOnce){state.notif.loadedOnce=true;Promise.resolve().then(()=>{loadNotifications();loadNotifPrefs();});}
 Promise.resolve().then(pushRefreshStatus);
 const p=state.notif.prefs;
 const signedIn=!!state.plexUser||state.adminLoggedIn;
 const items=state.notif.items.map(n=>`<button class="notif-item ${n.read?'':'unread'}" data-notif-open="${n.id}" data-notif-page="${esc(n.page||'')}">
   <span class="notif-icon">${NOTIF_ICONS[n.category]||'•'}</span>
   <span class="notif-main"><strong>${esc(n.title)}</strong>${n.body?`<span class="subtle">${esc(n.body)}</span>`:''}<span class="subtle">${notifTime(n.createdAt)}</span></span>
   ${n.read?'':'<span class="notif-dot" aria-label="Unread"></span>'}
 </button>`).join('');
 const cats=p?p.categories.filter(c=>!c.adminOnly||state.adminLoggedIn).map(c=>`<label class="notif-pref"><span>${esc(c.label)}${c.adminOnly?' (admin)':''}</span><input type="checkbox" data-notif-mute="${c.id}" ${c.muted?'':'checked'}> <span class="subtle">${c.muted?'muted':'on'}</span></label>`).join(''):'<p class="subtle">Loading your preferences…</p>';
 const pushSupported='serviceWorker' in navigator&&'PushManager' in window;
 const pushBlock=!signedIn?'<p class="subtle">Sign in to manage phone alerts.</p>':!pushSupported?'<p class="subtle">This browser does not support push notifications. On iPhone, add this site to your Home Screen first — Apple only allows alerts for installed web apps.</p>':p&&!p.push.configured?'<p class="subtle">Phone alerts are not switched on yet'+(state.adminLoggedIn?' — generate the push keys below to enable them for everyone.':' — ask the admin to enable them in the section below.')+'</p>':`<p class="subtle" data-push-status>Checking this device…</p><div class="actions-row"><button class="btn" data-push-enable="1">Enable alerts on this device</button><button class="btn secondary" data-push-disable="1">Turn off on this device</button></div><p class="subtle">Alerts arrive even when the tab is closed. Each phone or browser opts in separately.</p>`;
 const discordPanel=(target,label,blurb)=>{
 const d=p&&p.discord?p.discord[target]:null;
 return `<div class="panel"><h3>Discord alerts — ${label} (admin)</h3>
   <p class="subtle">${blurb} In Discord: channel settings → Integrations → Webhooks → New Webhook → Copy URL, then paste it here. The URL is a secret and is never shown again.</p>
   <p class="subtle">${d?(d.configured?'A webhook is saved.'+(d.lastStatus?' Last delivery: HTTP '+esc(d.lastStatus)+(d.lastAt?' · '+notifTime(d.lastAt):''):''):'No webhook saved yet.'):'Loading…'}</p>
   <div class="actions-row"><input type="url" data-discord-url="${target}" placeholder="https://discord.com/api/webhooks/…" autocomplete="off" style="flex:1;min-width:220px"><button class="btn secondary" data-discord-save="${target}">Save webhook</button><button class="btn secondary" data-discord-test="${target}">Send a test</button></div>
   ${d?`<div class="notif-prefs">${p.categories.map(c=>`<label class="notif-pref"><span>${esc(c.label)}</span><input type="checkbox" data-discord-cat="${target}:${c.id}" ${d.cats.includes(c.id)?'checked':''}></label>`).join('')}</div>`:''}
   <p class="subtle">${state.notif.discordMsg&&state.notif.discordMsgTarget===target?esc(state.notif.discordMsg):''}</p></div>`;
};
const adminBlock=state.adminLoggedIn?`<div class="panel"><h3>Push server (admin)</h3>
   <p class="subtle">${p?(p.push.configured?'Push keys are generated — members can enable alerts on their devices.':'No push keys yet. Generate a keypair to switch phone alerts on. The private key never leaves the server.'):''}</p>
   <div class="actions-row"><button class="btn secondary" data-push-vapid="1">${p&&p.push.configured?'Regenerate push keys':'Generate push keys'}</button><button class="btn secondary" data-push-test="1">Send a test notification</button></div>
   <p class="subtle">${p&&p.push.lastStatus?'Last push delivery: HTTP '+esc(p.push.lastStatus)+(p.push.lastAt?' · '+notifTime(p.push.lastAt):''):'No push has been sent yet.'}</p>
   <p class="subtle" data-push-admin-msg>${state.notif.adminMsg?esc(state.notif.adminMsg):''}</p></div>
   ${discordPanel('admin','Admin channel','Admin-only alerts: new requests, problem reports, and servers going down or coming back up. Point this at a channel only you can see.')}
   ${discordPanel('public','Public channel','Household alerts: request outcomes, new featured picks, Tavern News and Movie Night. Everyone in the channel sees these posts.')}`:'';
 return `<section class="section"><div class="section-head"><h3>Notifications</h3></div><p class="subtle">Request outcomes, new picks, news and server alerts — here, and on your phone if you opt in.</p>
 ${signedIn?`<div class="panel"><div class="section-head"><h3>Your alerts</h3>${state.notif.unread?`<button class="btn secondary" data-notif-readall="1">Mark all read</button>`:''}</div>
 ${state.notif.items.length?`<div class="notif-list">${items}</div>`:'<p class="subtle">Nothing yet. When a request of yours is fulfilled, a new pick is featured, or news is posted, it will land here.</p>'}</div>
 <div class="panel"><h3>What reaches you</h3><div class="notif-prefs">${cats}</div></div>
 <div class="panel"><h3>Phone alerts</h3>${pushBlock}</div>${adminBlock}</section>`:'<div class="panel"><h3>Sign in first</h3><p class="subtle">Alerts are personal — sign in with Plex (or as admin) to see yours.</p></div></section>'}`;
}
async function pushRefreshStatus(){
 const el=document.querySelector('[data-push-status]');if(!el)return;
 try{const reg=await navigator.serviceWorker.ready;const sub=await reg.pushManager.getSubscription();el.textContent=sub?'This device is subscribed — alerts are on.':'This device is not subscribed yet.';}catch{el.textContent='Could not check this device.';}
}
function urlB64ToUint8(b64){const pad='='.repeat((4-b64.length%4)%4);const raw=atob(b64.replace(/-/g,'+').replace(/_/g,'/')+pad);return Uint8Array.from(raw,c=>c.charCodeAt(0));}
document.addEventListener('click',async e=>{
 const open=e.target.closest('[data-notif-open]');
 if(open){const id=open.getAttribute('data-notif-open');const item=state.notif.items.find(x=>x.id===id);if(item&&!item.read){item.read=true;state.notif.unread=Math.max(0,state.notif.unread-1);try{await notifPost('/api/plex/notifications/read',{id});}catch{}}const page=open.getAttribute('data-notif-page');if(page&&page!==state.page){mhGo(page);}else render();return;}
 if(e.target.closest('[data-notif-readall]')){try{await notifPost('/api/plex/notifications/read',{all:true});state.notif.items.forEach(x=>x.read=true);state.notif.unread=0;}catch{}render();return;}
 if(e.target.closest('[data-push-enable]')){const msg=document.querySelector('[data-push-status]');try{
   const perm=await Notification.requestPermission();if(perm!=='granted'){if(msg)msg.textContent='The browser blocked notifications — allow them in the browser settings, then try again.';return;}
   const prefs=state.notif.prefs||await dashboardRequest('/api/plex/notifications/prefs');state.notif.prefs=prefs;
   if(!prefs.push.configured){if(msg)msg.textContent='Push keys are not generated yet — the admin needs to generate them below first.';return;}
   const reg=await navigator.serviceWorker.ready;const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlB64ToUint8(prefs.push.publicKey)});
   await notifPost('/api/plex/push/subscribe',sub.toJSON());
   if(msg)msg.textContent='This device is subscribed — alerts are on.';}catch(err){if(msg)msg.textContent='Could not subscribe this device: '+(err.message||err);}return;}
 if(e.target.closest('[data-push-disable]')){const msg=document.querySelector('[data-push-status]');try{const reg=await navigator.serviceWorker.ready;const sub=await reg.pushManager.getSubscription();if(sub){await notifPost('/api/plex/push/unsubscribe',{endpoint:sub.endpoint});await sub.unsubscribe();}if(msg)msg.textContent='This device is unsubscribed.';}catch{}return;}
 if(e.target.closest('[data-push-vapid]')){try{await notifPost('/api/plex/push/vapid',{});state.notif.adminMsg='Push keys generated. Members can now enable alerts on their devices.';state.notif.prefs=null;loadNotifPrefs();}catch(err){state.notif.adminMsg='Key generation failed: '+(err.message||err);render();}return;}
 if(e.target.closest('[data-push-test]')){try{await notifPost('/api/plex/push/test',{});state.notif.adminMsg='Test sent — check the bell and your phone.';loadNotifications();}catch(err){state.notif.adminMsg='Test failed: '+(err.message||err);render();}return;}
 const dSave=e.target.closest('[data-discord-save]');
 if(dSave){const target=dSave.getAttribute('data-discord-save');const input=document.querySelector('[data-discord-url="'+target+'"]');const webhook=input?input.value.trim():'';state.notif.discordMsgTarget=target;try{const r=await notifPost('/api/plex/push/discord',{target,webhook});state.notif.discordMsg=r.configured?'Webhook saved — '+target+' mirroring is on.':'Webhook cleared — '+target+' mirroring is off.';state.notif.prefs=null;loadNotifPrefs();}catch(err){state.notif.discordMsg='Could not save: '+(err.message||err);render();}return;}
 const dTest=e.target.closest('[data-discord-test]');
 if(dTest){const target=dTest.getAttribute('data-discord-test');state.notif.discordMsgTarget=target;try{const r=await notifPost('/api/plex/push/discord-test',{target});state.notif.discordMsg=r.ok?'Test posted to the '+target+' channel (HTTP '+r.status+').':'Discord answered HTTP '+r.status+' — the webhook may have been deleted in Discord.';state.notif.prefs=null;loadNotifPrefs();}catch(err){state.notif.discordMsg='Test failed: '+(err.message||err);render();}return;}
});
document.addEventListener('change',async e=>{
 const dcat=e.target.closest('[data-discord-cat]');
 if(dcat){const [target]=dcat.getAttribute('data-discord-cat').split(':');const cats=[...document.querySelectorAll('[data-discord-cat]')].filter(x=>x.checked&&x.getAttribute('data-discord-cat').startsWith(target+':')).map(x=>x.getAttribute('data-discord-cat').split(':')[1]);try{await notifPost('/api/plex/push/discord',{target,cats});const d=state.notif.prefs?.discord?.[target];if(d)d.cats=cats;}catch{}return;}
 const mute=e.target.closest('[data-notif-mute]');if(!mute)return;
 const category=mute.getAttribute('data-notif-mute');const muted=!mute.checked;
 try{await notifPost('/api/plex/notifications/prefs',{category,muted});const c=state.notif.prefs?.categories.find(x=>x.id===category);if(c)c.muted=muted;loadNotifications(false);}catch{}
 render();
});
// Service worker: registers the push receiver; a notification click that
// finds this tab open messages it the target page instead of opening a copy.
if('serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{});navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='mh-navigate'&&e.data.page)mhGo(e.data.page);});}
loadNotifications(false);
setInterval(()=>{if(!document.hidden)loadNotifications(false);},90000);

// ---- Android back-button guard (v3.6.30; double-back standard v3.6.31) ----
// This app is a single page: in-app navigation never creates browser history.
// In an Android WebView / installed web app, pressing Back with an empty
// history closes the app outright. So we seed a sentinel history entry and
// handle every Back (popstate) inside the app, re-seeding the sentinel:
// close transient UI first (search, mobile menu), then step back to Home.
// At Home the standard is DOUBLE-BACK TO EXIT: the first Back arms a ~2s
// window and shows "Press back again to exit"; a second Back inside the
// window steps OUT past the root sentinel (no re-seed) so the app really
// closes. A lone Back never closes anything.
(function(){
 try{
  let armedAt=0,toastTimer=null;
  const toast=()=>{
   let el=document.getElementById('mh-exit-toast');
   if(!el){el=document.createElement('div');el.id='mh-exit-toast';el.textContent='Press back again to exit';el.style.cssText='position:fixed;left:50%;bottom:calc(84px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:#1d2739;color:#e8edf7;border:1px solid #3a4a6b;padding:10px 16px;border-radius:999px;font:600 14px system-ui,sans-serif;z-index:9999;box-shadow:0 8px 24px rgba(0,0,0,.45)';document.body.appendChild(el);}
   el.style.display='block';
   clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.style.display='none';},2000);
  };
  history.replaceState({mhRoot:true},'');
  history.pushState({mhGuard:true},'');
  addEventListener('popstate',()=>{
   if(state.searchOpen){state.searchOpen=false;armedAt=0;render();}
   else if(state.mobileMenu){state.mobileMenu=false;armedAt=0;render();}
   else if(state.page!=='Home'){state.page='Home';window.scrollTo({top:0});armedAt=0;render();}
   else if(armedAt&&Date.now()-armedAt<2000){armedAt=0;history.back();return;}
   else{armedAt=Date.now();toast();}
   history.pushState({mhGuard:true},'');
  });
 }catch{}
})();
